def model_lab(st, key, **kw):
    code = _lang_code(st)
    return MODEL_STATUS_LABELS.get(code, MODEL_STATUS_LABELS["en"])[key].format(**kw)


def _private_hits_text(text, terms, paths):
    raw = text.encode("utf-8", "replace")
    hits = []
    for term in terms:
        if not term: continue
        if re.fullmatch(r"[A-Za-z0-9_]+", term):
            if re.search(r"(?<![A-Za-z0-9_])" + re.escape(term) + r"(?![A-Za-z0-9_])", text, re.I): hits.append(("*****", "private word"))
        elif _bytes_has(raw, _needles([term])): hits.append(("*****", "private word"))
    # Match each path-like token using the guard's gitignore glob matcher.
    for i, rule in enumerate(paths, 1):
        if any(_path_rule_hit(token, rule) for token in re.findall(r"[\w./\\-]+", text)):
            hits.append(("*****", f"private path rule #{i}"))
    return hits


def _task_dispatch_model(st, tid):
    task = st.get("tasks", {}).get(tid, {})
    requested = task.get("route") or task.get("model") or (st.get("threads", {}).get(task.get("owner") or "") or {}).get("model")
    if requested not in MODELS:
        return None
    kind = task.get("kind") or task.get("type")
    order = ("gpt", "fable", "opus")
    initial = requested
    choices = list(order[order.index(initial):])
    for model in choices:
        if kind and _denied(st, kind, model): continue
        if model == "gpt" and st.get("models", {}).get("gpt", {}).get("down"):
            urgent = bool(task.get("urgent") or task.get("priority") == "P0")
            if urgent: return {"model": "fable", "status": None, "reason": model_lab(st, "gpt_down_p0")}
            return {"model": "gpt", "status": model_lab(st, "gpt_down_wait"), "reason": None}
        reason = (model_lab(st, "model_switched", initial=initial, kind=kind, model=model) if model != initial and kind else None)
        return {"model": model, "status": None, "reason": reason}
    return {"model": initial, "status": model_lab(st, "model_no_higher", initial=initial, kind=kind), "reason": None}


PRIMARY_FALSE_WORDS = ("正常", "可用", "工作", "ok", "works")
PRIMARY_SUSPECT_WORDS = ("mock", "stub", "fake", "jsdom", "msw", "nock", "sinon", "mockito",
                         "fixture", "dummy", "simulated", "placeholder", "假数据", "模拟", "虚拟", "样例数据",
                         "假的", "unittest", "unit test")
PRIMARY_INTERNAL_WORDS = ("return", "变量", "函数", "内部值", "internal value")


def _primary_text_valid(value):
    value = (value or "").strip()
    cjk = len(re.findall(r"[\u3400-\u9fff]", value))
    too_short = cjk < 5 if cjk else len(re.sub(r"[\W_]", "", value, flags=re.UNICODE)) < 8
    if too_short:
        return False
    plain = re.sub(r"[\W_]+", "", value, flags=re.UNICODE).lower()
    return plain not in {re.sub(r"[\W_]+", "", x, flags=re.UNICODE).lower() for x in PRIMARY_FALSE_WORDS}


def _primary_evidence_specific(d, evidence):
    evidence = (evidence or "").strip()
    if not evidence:
        return False
    if re.search(r"https?://\S+", evidence, re.I):
        return True
    # Accept an existing path anywhere in the evidence string: absolute, or relative to the
    # current folder or the project folder (bare names like shot.png and docs/shots/a.png too).
    roots = [Path.cwd()] + ([Path(d).parent] if d else [])
    tokens = re.findall(r'"([^"\n]+)"|\'([^\'\n]+)\'|([^\s,;，；、()（）"\'`]+)', evidence)
    for token_parts in tokens:
        token = next((part for part in token_parts if part), "")
        token = token.strip(".:：。")
        if not token or not re.search(r"[./\\]", token):
            continue
        normalized = token.replace("\\", "/").lower()
        if normalized.startswith(("/etc/", "/usr/", "/bin/", "/system/", "/dev/")):
            continue
        p = Path(token).expanduser()
        if any((p if p.is_absolute() else r / p).is_file() for r in roots):
            return True
    # A numeric result is concrete output; bare numbers without surrounding result text are not.
    # (Chinese is dense: "输出 15 条" is concrete, a bare "15" is not.)
    residue = re.sub(r"\d+|ok|done|passed|works|through|looks|fine|正常|可用|工作|通过|完成|没问题", "", evidence,
                     flags=re.I)
    meaningful = re.findall(r"[a-z]+|[\u3400-\u9fff]+", residue.lower())
    return bool(re.search(r"\d", evidence) and len("".join(meaningful)) >= 2 and
                sum(len(w) for w in meaningful) >= 3)


def _primary_suspect(d, how, evidence):
    words = "|".join(re.escape(w) for w in PRIMARY_SUSPECT_WORDS)
    negation = re.compile(rf"\b(?:no|not|without|never)\s+(?:(?:use|using|used|a|any)\s+)*(?:{words})"
                          rf"|(?:不用|没用|没有用|未用|不是|并非|非|无|没有)\s*(?:{words})", re.I)
    project = Path(d).resolve().parent if d else Path.cwd().resolve()
    roots = [Path.cwd().resolve(), project]
    fixtures_name = ""
    if d:
        state_path = Path(d) / "state.json"
        if state_path.is_file():
            try:
                fixtures_name = pref(json.loads(state_path.read_text(encoding="utf-8")), "fixtures_dir")
            except (OSError, ValueError, AttributeError):
                pass
    fixtures = (project / fixtures_name).resolve() if fixtures_name else None

    def random_tmp_component(component):
        return bool(re.fullmatch(r"tmp[A-Za-z0-9_-]{8}", component))

    def human_text(value):
        value = value or ""
        tokens = re.findall(r'"([^"\n]+)"|\'([^\'\n]+)\'|([^\s,;，；、()（）"\'`]+)', value)
        for parts in tokens:
            token = next((part for part in parts if part), "")
            clean = token.strip(".:：。")
            if not clean or not re.search(r"[./\\]", clean):
                continue
            path = Path(clean).expanduser()
            candidates = [path] if path.is_absolute() else [root / path for root in roots]
            existing = next((candidate.resolve() for candidate in candidates if candidate.is_file()), None)
            if existing:
                if fixtures:
                    try:
                        existing.relative_to(fixtures)
                        value = value.replace(token, "")
                        continue
                    except ValueError:
                        pass
                try:
                    relative = existing.relative_to(Path(tempfile.gettempdir()).resolve())
                except ValueError:
                    relative = existing
                replacement = " ".join(part for part in relative.parts if not random_tmp_component(part))
                value = value.replace(token, replacement)
        return value

    text = f"{human_text(how)} {human_text(evidence)}"
    for sentence in re.split(r"[,，.;；/]|\bbut\b|但|只好", text, flags=re.I):
        if negation.search(sentence):
            continue
        if any(word in sentence.lower() for word in PRIMARY_SUSPECT_WORDS):
            return True
    return False


def review_tests_line(st, review):
    return lab(st, "review_tests_line", tests=lab(st, "review_tests_" + (review.get("tests") or "unrecorded").replace("-", "_")),
               why=(lab(st, "tests_why_fmt", why=review.get("tests_why"))
                    if review.get("tests") == "not-run" and review.get("tests_why") else ""),
               base=(review.get("base") or "-")[:9])


def task_primary_label(st, task):
    check = task.get("primary_check") or {}
    if task.get("primary_exempt"): return lab(st, "primary_exempt")
    if task.get("primary_legacy"): return lab(st, "primary_legacy")
    return lab(st, "primary_" + check.get("result", "missing").replace("-", "_")) if check else "—"


def primary_gate(st, tid, before, k, changes, a, said):
    """Primary checks run only for a relevant change; legacy rows get one safe migration pass."""
    relevant = changes.get("status_to") in ("review", "done", "working", "merge") or any(
        changes.get(x) for x in ("review_recorded", "verify", "primary", "base", "accept"))
    if not relevant:
        return
    if k.pop("primary_legacy", False):
        if changes.get("verify") or changes.get("status_to") == "working":
            pass
        else:
            k["primary_legacy"] = True
            return
    if changes.get("status_to") == "verify":
        if not k.get("primary"):
            sys.exit(lab(st, "primary_verify_no_primary", task=tid))
        if before.get("status") == "done":
            sys.exit(lab(st, "primary_verify_done", task=tid))
    if changes.get("status_to") == "working":
        k.pop("primary_legacy", None)
    if k.get("primary_exempt") and changes.get("status_to") in ("review", "done", "merge"):
        return
    if not pref(st, 'require_primary'):
        return
    check = k.get("primary_check") or {}
    result = check.get("result")
    target = changes.get("status_to")
    review_check = target == "review" or (changes.get("review_recorded") and getattr(a, "review", None) in PASSING)
    if review_check and not k.get("primary_exempt"):
        if not (k.get("primary") and result in ("seen", "pending-real")):
            sys.exit(lab(st, "primary_review_gate", primary=k.get("primary") or "—"))
    if target in ("done", "merge"):
        if target == "done" and result != "seen" and not (result == "pending-real" and said.strip()):
            sys.exit(lab(st, "primary_done_gate", primary=k.get("primary") or "—"))
        if target == "merge" and (k.get("review") or {}).get("result") == "blocked-env" and not said.strip():
            sys.exit(lab(st, "env_merge_blocked", task=tid, env=lab(st, "review_blocked_env")))
        if target == "merge" and result not in ("seen", "pending-real"):
            if not said.strip(): sys.exit(lab(st, "primary_merge_gate", task=tid))
            changes.setdefault("primary_waivers", []).append(tid)
    if changes.get("review_recorded") and getattr(a, "review", None) in PASSING and not k.get("primary_exempt"):
        if not getattr(a, "recheck_how", None) or not _primary_evidence_specific(find_dir(), getattr(a, "recheck_evidence", "")):
            sys.exit(lab(st, "primary_recheck_gate"))
        norm = lambda x: re.sub(r"[\W_]+", "", (x or "").lower(), flags=re.UNICODE)
        if norm(a.recheck_evidence) == norm(check.get("evidence")):
            sys.exit(lab(st, "primary_recheck_independent"))
        if (k.get("primary_suspect") or _primary_suspect(find_dir(), a.recheck_how, a.recheck_evidence)) and not getattr(a, "suspect_cleared", False):
            sys.exit(lab(st, "primary_suspect_gate"))


def g8_gate(st, tid, before, k, changes, a, said):
    """G8 review evidence and environment rules, registered beside the primary gate."""
    if changes.get("review_recorded"):
        if a.env_down and a.review != "fail":
            sys.exit(lab(st, "g8_env_fail"))
        if a.review in PASSING and a.tests == "not-run" and k.get("checks") != "pass" and not a.recheck_evidence:
            sys.exit(lab(st, "g8_notrun_pass"))


TASK_GATES = [primary_gate, g8_gate]  # Root's root-cause gate can register here later; keep cmd_root unchanged.


def fixtures_gate(st, tid, before, k, changes, a, said):
    """Require declared primary tests to refer to generated fixtures before done."""
    fixtures_dir = (pref(st, 'fixtures_dir') or "").strip()
    if (changes.get("status_to") != "done" or not fixtures_dir or not k.get("primary")
            or k.get("primary_exempt") or k.get("primary_legacy")):
        return
    test_id = (k.get("primary_check") or {}).get("test")
    if not test_id:
        return lab(st, "fixtures_gate_no_test", task=tid)
    filename, sep, selector = test_id.partition("::")
    if sep and not selector.strip():
        return lab(st, "fixtures_gate_empty_selector")
    root = Path(find_dir()).resolve().parent
    test_path = (root / filename).resolve()
    try:
        test_path.relative_to(root)
        source = test_path.read_text(encoding="utf-8")
    except (ValueError, OSError, UnicodeError):
        return lab(st, "fixtures_gate_no_test", task=tid)
    try:
        import ast
        tree = ast.parse(source)
    except SyntaxError:
        return lab(st, "fixtures_gate_no_test", task=tid)
    if sep:
        try:
            parts = selector.split(".")
            node = tree
            for part in parts:
                node = next(child for child in node.body if getattr(child, "name", None) == part)
        except (SyntaxError, StopIteration, AttributeError):
            return lab(st, "fixtures_gate_no_test", task=tid)
        if not isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
            return lab(st, "fixtures_gate_no_test", task=tid)
    else:
        node = tree

    class FixtureUse(ast.NodeVisitor):
        found = False
        def visit_If(self, branch):
            test = branch.test
            if isinstance(test, ast.Constant) and test.value in (False, 0, None):
                for statement in branch.orelse:
                    self.visit(statement)
                return
            self.generic_visit(branch)
        def visit_Call(self, call):
            name = call.func.id if isinstance(call.func, ast.Name) else getattr(call.func, "attr", "")
            if name in ("sample", "place") or (name in ("Path", "PurePath", "join") and any(map(self.path_segment, call.args))):
                self.found = True
            self.generic_visit(call)
        def visit_Name(self, name):
            if name.id == "fixtures_dir":
                self.found = True
        # A path built by hand also counts: Path(..)/"fixtures"/.., Path("scripts/fixtures/x"), os.path.join(.., "fixtures", ..).
        # Only strings that are path segments count, never a word in a note or message.
        def path_segment(self, value):
            text = value.value.replace("\\", "/").strip("/") if isinstance(value, ast.Constant) and isinstance(value.value, str) else ""
            return bool(text) and (fixtures_name in text.split("/") or text.startswith(fixtures_rel))
        def visit_BinOp(self, op):
            if isinstance(op.op, ast.Div) and (self.path_segment(op.left) or self.path_segment(op.right)):
                self.found = True
            self.generic_visit(op)

    fixtures_rel = fixtures_dir.replace("\\", "/").strip("/")
    fixtures_name = fixtures_rel.rsplit("/", 1)[-1]
    use = FixtureUse()
    use.visit(node)
    if not use.found:
        return lab(st, "fixtures_gate", task=tid, fixtures_dir=fixtures_dir)


TASK_GATES.append(fixtures_gate)


def _done_gate_reason(st, tid, before=None, k=None, changes=None, a=None, said=""):
    """Single done gate; callers may pass no changes to receive the legacy reason string."""
    k = k or st["tasks"][tid]
    changes = changes or {"status_to": "done"}
    if changes.get("status_to") != "done": return
    if not k.get("owner"): return lab(st, "task_owner_done", task=tid)
    rv = k.get("review") or {}
    if rv.get("result") == "blocked-env":
        if not (getattr(a, "skip_review", None) and said.strip()):
            return lab(st, "env_done_blocked", env=lab(st, "review_blocked_env"))
    if k.get("checks") == "fail":
        return lab(st, "task_checks_done", task=tid)
    if rv.get("result") == "skipped":
        return
    if not str(k.get("accept") or "").strip():
        return f"{tid} has no 'done when': set --accept first (a review needs something to check against)"
    if pref(st, 'require_review') and rv.get("result") not in PASSING:
        return lab(st, "task_review_done", task=tid)
    if rv.get("result") in PASSING:
        owners = [k["owner"]] + list(k.get("past_owners") or [])
        if not all(reviewer_independent(rv.get("reviewer") or "", o) for o in owners):
            return f"{tid}: its reviewer {rv.get('reviewer')} owns it; get another review"
        if rv.get("result") == "capped" and k.get("checks") != "pass":
            return f"{tid}: capped at the round limit, which needs `--checks pass`"


def _seat_change_summary(d, st, seat, start):
    events = []
    try:
        for line in (d / "log.jsonl").read_text(encoding="utf-8").splitlines():
            try: row = json.loads(line)
            except ValueError: continue
            if row.get("t", "") >= (start or "") and row.get("ev") in ("prefs", "lead", "thread-set", "task-set"):
                events.append({"at": row.get("t"), "event": row.get("ev"), "mode": row.get("mode"), "set": row.get("set"),
                               "branch": row.get("branch"), "base": row.get("base"), "session": row.get("session")})
    except OSError: pass
    mem = (d / "MEMORY.md").read_text(encoding="utf-8") if (d / "MEMORY.md").exists() else ""
    added = [line[2:] for line in mem.splitlines() if line.startswith("- ") and "_(added" in line and
             (not start or line.split("_(added", 1)[-1][:20] >= start[:10])]
    return events, added


REQ_STATUSES = ["open", "held", "proposed", "dispatched", "delivered", "reported", "waiting_user", "landed", "wont", "remark", "closed", "dropped"]
REQ_END = ("closed", "dropped")
# Request moves the lead may make with `req set` (framework A9). closed/dropped only via close/drop (user action).
REQ_MOVES = {"open": {"held", "proposed", "dispatched", "reported", "waiting_user"}, "held": set(),  # held: back where it paused
             "proposed": {"held", "dispatched", "waiting_user"},
             "dispatched": {"held", "delivered", "waiting_user"}, "delivered": {"reported"}, "reported": {"dispatched", "waiting_user", "landed"},
             "waiting_user": {"open", "proposed", "dispatched"}, "landed": {"dispatched"}, "wont": {"open"}, "remark": {"open"}}
REQ_NEEDS_USER = {("proposed", "dispatched"), ("reported", "dispatched"),  # user said yes / asked for changes
                  ("waiting_user", "dispatched"), ("landed", "dispatched")}  # no side door around the user's yes
# Task moves (framework A9). done needs review first and passes the review gate.
TASK_MOVES = {"planned": {"approved", "dropped"}, "approved": {"dispatched", "dropped"},
              "dispatched": {"working", "recalled"}, "working": {"blocked", "review", "recalled"},
              "blocked": {"working", "recalled"}, "review": {"working", "done"},
              "recalled": {"dispatched", "dropped"}, "done": set(), "dropped": set()}
# Accepted when importing a markdown ledger (status column in either language).
REQ_STATUS_ALIASES = {"待办": "open", "等材料": "held", "等你的材料": "held", "等你定": "waiting_user", "不做": "wont", "已落地": "landed", "已派": "dispatched", "已交付": "delivered", "已回报": "reported",
                      "已关闭": "closed", "已提议": "proposed", "已放弃": "dropped", **{x: x for x in REQ_STATUSES}}


def unreported(st):
    return {r: q for r, q in st.get("requests", {}).items() if q["status"] == "delivered"}


def result_changed(st, q):
    """A gated reported result stays reported while its linked work is redone, with a visible redelivery notice."""
    tasks = live_tasks(st, q)
    return bool(q.get("gate") and q.get("status") == "reported" and tasks and
                not all(st.get("tasks", {}).get(t, {}).get("status") == "done" for t in tasks))


def awaiting_confirm(st, q):
    """Reported and ready for the user's confirmation; a changed result stays in the main list."""
    return q.get("status") == "reported" and not result_changed(st, q)


def render_requests(st, chain=False):
    reqs = [(r, q) for r, q in st.get("requests", {}).items() if q["status"] not in REQ_END and q["status"] != "remark" and not awaiting_confirm(st, q)]
    if not reqs:
        return None
    order = {"delivered": 0, "held": 1, "proposed": 2, "open": 3, "waiting_user": 4, "dispatched": 5, "reported": 6, "landed": 7, "wont": 8}
    reqs.sort(key=lambda x: (order.get(x[1]["status"], 9), int(x[0][1:]) if x[0][1:].isdigit() else 0))
    out = []
    for r, q in reqs:
        line = f"- **{r}** [{lab(st, 'req_' + q['status'])}] {_md(q['text'])}"  # user text: never struck or bolded
        extra = [", ".join(q.get("tasks") or []), _where(q.get("where")) if q.get("where") else ""]
        extra = " · ".join(x for x in extra if x)
        if extra:
            line += f" — {extra}"
        if result_changed(st, q):
            line += f" — {lab(st, 'req_result_changed')}"
        if q.get("followup"):
            line += f" — {lab(st, 'followup')}: {_md(q['followup'])}"
        out.append(line)
        if chain:  # B4: the board shows how far each request has come
            out.append(f"  - {progress_chain(st, q)}")
    return "\n".join(out)


def render_features(st):
    rows = st.get("features", {})
    if not rows:
        return None
    groups = {}
    for fid, f in rows.items():
        groups.setdefault(f.get("phase") or "", []).append((fid, f))
    out = []
    for phase, items in sorted(groups.items(), key=lambda x: (x[0] or "~")):
        out.append("### " + _md(phase or "-"))
        for fid, f in sorted(items, key=lambda x: (re.sub(r'\d+.*', '', x[0]), int(m.group()) if (m := re.search(r'\d+', x[0])) else 0, x[0])):
            moved = lab(st, "feature_moved", phase=f.get("moved_from")) if f.get("moved_from") else ""
            paths = _where_paths(f.get("where"))
            where = lab(st, "feature_where", paths=", ".join(paths)) if paths else ""
            out.append(f"- **{fid}** {_md(f['name'])} [{lab(st, 'feature_' + f['status'])}] — {', '.join(f.get('reqs') or []) or _md(f.get('source') or '-')}" + (f" {where}" if where else "") + (f" {moved}" if moved else ""))
    return "\n".join(out)


def render_feature_needs_location(st):
    unknown = [(fid, feature) for fid, feature in st.get("features", {}).items()
               if feature.get("where_source") == "unknown" or
               (feature.get("status") == "landed" and not _where_paths(feature.get("where")))]
    if not unknown:
        return None
    return "\n".join([f"## {lab(st, 'feature_needs_location')}", "",
                       *(f"- **{fid}** {_md(feature.get('name') or '')}" for fid, feature in unknown)])


def _where_paths(value):
    if isinstance(value, str):
        return [value.strip()] if value.strip() else []
    if isinstance(value, list):
        return list(dict.fromkeys(str(item).strip() for item in value if str(item).strip()))
    return []


def _feature_ids(rows):
    return [f"F{i}" for i in range(1, max([int(x[1:]) for x in rows if re.fullmatch(r"F\d+", x)] or [0]) + 1)]


def _reconcile_rows(st):
    rows = []
    reqs, tasks, features = st.get("requests", {}), st.get("tasks", {}), st.get("features", {})
    for rid, q in reqs.items():
        if q.get("status") in ("open", "dispatched", "held") and not q.get("tasks") and not q.get("features"):
            rows.append({"kind": "unassigned_request", "req": rid})
        for said in q.get("user_said", []) if isinstance(q.get("user_said"), list) else ([{"text": q["user_said"]}] if q.get("user_said") else []):
            rows.append({"kind": "original_pair", "req": rid, "original": said.get("text", ""), "record": q.get("text", "")})
    for fid, f in features.items():
        linked = f.get("reqs") or []
        if not linked:
            rows.append({"kind": "feature_without_request", "feature": fid})
        if f.get("status") == "landed":
            for rid in linked:
                if rid in reqs and reqs[rid].get("status") in ("open", "dispatched"):
                    rows.append({"kind": "landed_request_open", "feature": fid, "req": rid})
    for tid, task in tasks.items():
        if task.get("status") == "done":
            for rid, q in reqs.items():
                if tid in (q.get("tasks") or []) and q.get("status") not in REQ_SETTLED:
                    rows.append({"kind": "done_task_request_unreported", "task": tid, "req": rid})
    if not features and (tasks or re.search(r"\b(app|software|website|webapp|feature|implement|code|build|开发|应用|网站)\b", st.get("goal", ""), re.I)):
        rows.append({"kind": "empty_features"})
    return rows


REQ_SETTLED = ("reported", "landed", "closed", "dropped", "wont", "remark")
RC_KEYS = {"unassigned_request": "rc_unassigned", "original_pair": "rc_pair", "feature_without_request": "rc_no_req",
           "landed_request_open": "rc_landed_open", "done_task_request_unreported": "rc_done_unreported", "empty_features": "rc_empty_features"}


def _rc_line(st, x):
    """One reconcile finding in the user's language."""
    return lab(st, RC_KEYS[x["kind"]], **{k: v for k, v in x.items() if k != "kind"})


def _run_reconcile(st):
    rows = _reconcile_rows(st)
    st["reconcile"] = {"at": now(), "count": sum(1 for x in rows if x["kind"] != "original_pair"), "items": rows}
    return rows


def _thread_on_duty(t):
    return isinstance(t, dict) and t.get("status") in ("working", "starting")


def stuck_threads(st):
    """{thread: minutes since its last report} for working/starting threads silent longer than prefs.stuck_minutes."""
    limit = pref(st, 'stuck_minutes')
    cur = dt.datetime.fromisoformat(now())
    out = {}
    for n, t in st["threads"].items():
        if t["status"] not in ("working", "starting", "waiting"):
            continue
        forced = bool(t.get("stuck_on"))
        if not forced and (not limit or not _thread_on_duty(t)):
            continue
        since = t.get("last_status_at") or t.get("created")
        if not since:
            continue
        mins = int((cur - dt.datetime.fromisoformat(since)).total_seconds() // 60)
        if forced or mins > limit:
            out[n] = mins
    return out


LANG_NAMES = {"zh": "Chinese (中文)", "en": "English", "ja": "Japanese (日本語)", "ko": "Korean (한국어)",
              "fr": "French", "de": "German", "es": "Spanish"}


def language_rule(st):
    """The conversation-language rule, with the project's current language (prefs.language)."""
    code = (pref(st, 'language') or "").strip()
    cur = (f"{LANG_NAMES.get(code.lower(), code)} (prefs.language={code})" if code
           else "not set: use the language of the user's latest message")
    return (
        f"Language (most important rule). Current conversation language: {cur}.\n"
        "- Reply in the language you were asked in. The lead writes to threads, threads answer the lead and talk to "
        "each other in the current conversation language.\n"
        "- If the user talks to a thread directly in another language, that thread answers the user in that language.\n"
        "- The same language runs all the way down: the task brief a thread gives its subagents and the reports they "
        "return are in the current conversation language too.\n"
        "- When the user switches language, the lead runs `tw.py prefs --set language=<code>` and broadcasts a "
        "FOLLOWUP to every thread; the newest one wins.\n"
        f"- Message headers keep their fixed English keywords (`[tw:{tag(st)}] TASK lead -> <thread> T2`); "
        "only the body follows the language.\n"
        "- Files follow what the task says (repo docs are English unless the task says otherwise); conversation "
        "follows the language."
    )


def find_dir(create_at=None):
    if create_at:
        d = Path(create_at).resolve() / ".teamwork"
        d.mkdir(parents=True, exist_ok=True)
        return d
    env = os.environ.get("TEAMWORK_DIR")
    if env:
        return Path(env).resolve()  # set by -C; never fall back to cwd when it was given
    cur = Path.cwd().resolve()
    for p in [cur, *cur.parents]:
        if (p / ".teamwork" / "state.json").exists():
            return p / ".teamwork"
    return None


def need(d):
    if d is None or not (d / "state.json").exists():
        sys.exit(
            "no .teamwork/state.json found from here upward: run `tw.py init <project>` in the project folder, or set TEAMWORK_DIR"
        )
    return d


def load(d):
    data = json.loads((d / "state.json").read_text(encoding="utf-8"))
    if not isinstance(data, dict):
        raise ValueError("state.json must contain an object")
    if not _has_required_ledger_keys(data):
        raise ValueError("state.json missing lead/threads/tasks structure")
    st = State(data)
    for task in st.get("tasks", {}).values():
        if task.get("status") in ("review", "done") and "primary_check" not in task and \
                not task.get("primary_legacy") and not task.get("primary_exempt"):
            task["primary_legacy"] = True
    if not isinstance(st.get("prefs"), dict):
        st["prefs"] = {}
    for key, spec in PREFS.items():
        if key not in st["prefs"]:
            st["prefs"][key] = copy.deepcopy(spec["default"])
    for key, value in DEFAULT_STATE.items():  # any missing key (an older ledger lacks some): in memory only until it changes
        if key not in st:
            st[key] = copy.deepcopy(value)
    st["_rev_loaded"] = st.get("rev", 0)
    return st


def log(d, event):
    with open(d / "log.jsonl", "a", encoding="utf-8") as f:
        f.write(json.dumps({"t": now(), **event}, ensure_ascii=False) + "\n")
        f.flush()
        os.fsync(f.fileno())


@contextlib.contextmanager
def ledger_lock(d, name=".save.lock"):
    save_lock_path = d / name
    if fcntl:
        with open(save_lock_path, "a+") as save_lock:
            fcntl.flock(save_lock.fileno(), fcntl.LOCK_EX)
            yield
        return
    deadline = time.monotonic() + 30
    while True:
        try:
            save_lock_fd = os.open(save_lock_path, os.O_CREAT | os.O_EXCL | os.O_WRONLY, 0o600)
            break
        except FileExistsError:
            if time.monotonic() >= deadline:
                raise RuntimeError(f"timed out acquiring .teamwork/{name}")
            time.sleep(.05)
    try:
        yield
    finally:
        os.close(save_lock_fd)
        save_lock_path.unlink(missing_ok=True)


_SKIP_SAVE = object()
_READY_SAVE_BATCH = None


def update(d, fn, event=None, initial=None):
    try:
        with ledger_lock(d):
            st = load(d) if (d / "state.json").exists() else copy.deepcopy(initial or {})
            result = fn(st)
            if result is _SKIP_SAVE: return None
            _save_locked(d, st, event)
            return result
    except RuntimeError as e:
        if str(e).startswith("timed out acquiring .teamwork/"):
            sys.exit(str(e))
        raise


def save(d, st, event=None):
    """Compatibility wrapper: preserve a caller's in-memory state under the shared lock."""
    if _READY_SAVE_BATCH is not None and d == _READY_SAVE_BATCH["dir"]:
        _READY_SAVE_BATCH["state"] = copy.deepcopy(stored(st))
        _READY_SAVE_BATCH["events"].append(copy.deepcopy(event or {}))
        return
    def replace(latest):
        latest.clear()
        latest.update(st)
        return latest
    latest = update(d, replace, event, initial=st)
    if isinstance(latest, dict):
        st.clear(); st.update(latest)
    return latest


def write_locked(st, cmd=None, ev=None):
    """Return whether writes are locked, or reject commands that write outside save()."""
    direct_writers = {"memory", "log", "worktree", "init"}
    lock = (st or {}).get("write_lock")
    if not lock:
        return False
    event = ev or {}
    if event.get("ev") == "session-start-version" or str(event.get("ev", "")).startswith("succ-"):
        return False
    if cmd is not None:
        direct = (cmd.cmd in direct_writers or
                  (cmd.cmd == "model-log" and not getattr(cmd, "summary", None)) or
                  (cmd.cmd == "rebuild" and getattr(cmd, "apply", False)) or
                  (cmd.cmd == "board" and getattr(cmd, "share", False)))
        if direct:
            sys.exit(lab(st, "lead_write_locked", ho=lock.get("ho")))
    return True


def state_delta(old, new):
    """Describe persisted state changes as changed collection rows or whole values."""
    old, new = stored(old), stored(new)
    delta = {}
    for key in old.keys() | new.keys():
        if key.startswith("_") or key in {"rev", "updated"}:
            continue
        before, after = old.get(key), new.get(key)
        if before == after:
            continue
        if key in DELTA_COLLECTIONS and isinstance(before, dict) and isinstance(after, dict):
            changed = {row: value for row, value in after.items() if before.get(row) != value}
            removed = sorted(before.keys() - after.keys())
            if changed:
                delta[key] = changed
            if removed:
                delta[f"{key}-"] = removed
        elif key not in new:
            delta.setdefault("-", []).append(key)
        else:
            delta[key] = copy.deepcopy(after)
    return delta


def log_delta(d, event, old, new):
    delta = state_delta(old, new)
    log(d, {**event, "delta": delta})
    return delta


def _patch_state(d, path_keys, update_fn, event=None):
    """Apply one narrowly scoped update to the newest ledger."""
    keys = tuple(path_keys) if isinstance(path_keys, (list, tuple)) else (path_keys,)
    def apply(latest):
        node=latest
        for key in keys[:-1]: node=node.setdefault(key,{})
        key=keys[-1]
        current=node.get(key)
        replacement=update_fn(copy.deepcopy(current),latest)
        if replacement is None: return _SKIP_SAVE
        node[key]=replacement
        return True
    for attempt in range(3):
        try:
            return update(d, apply, event)
        except SystemExit as e:
            if str(e) not in (lab(load(d), "ledger_changed"), "ledger changed") or attempt == 2: raise
    return None


def _save_locked(d, st, event=None):
    metadata_only = (event or {}).get("ev") == "session-start-version"
    disk = json.loads((d / "state.json").read_text(encoding="utf-8")) if (d / "state.json").exists() else {}
    for checked in (disk, st):
        if write_locked(checked, ev=event):
            sys.exit(lab(checked, "lead_relead_locked") if checked["write_lock"].get("relead") else
                     lab(checked, "lead_write_locked", ho=checked["write_lock"].get("ho")))
    if disk.get("rev", 0) != st.get("_rev_loaded", 0):
        sys.exit(lab(st, "ledger_changed"))
    log_events = _read_log(d)
    log_rev = log_events[-1].get("rev") if log_events else 0
    state_rev = disk.get("rev", 0)
    if isinstance(log_rev, int) and not isinstance(log_rev, bool) and log_rev > state_rev:
        print(f"log.jsonl is ahead of state.json (log rev {log_rev} > state rev {state_rev}); run `TW rebuild --apply`",
              file=sys.stderr)
    _radar_update(st)
    root_pending = st.pop("_root_pending", [])
    root_reraised = st.pop("_root_reraised", [])
    loaded_rev = st.pop("_rev_loaded", 0)
    prior_event = log_events[-1] if log_events else {}
    retry_rev = loaded_rev + 1
    stamp_keys = ("t", "at", "time", "timestamp")
    event_payload = {k: v for k, v in event.items() if k not in stamp_keys} if event else None
    prior_payload = ({k: prior_event[k] for k in event_payload if k in prior_event}
                     if event_payload is not None else None)
    same_retried_event = (event is not None and log_rev == retry_rev and prior_payload == event_payload)
    st["rev"] = loaded_rev if not event else retry_rev if same_retried_event else max(loaded_rev, log_rev or 0) + 1
    if not metadata_only:
        st["updated"] = now()
    tmp = d / f"state.json.tmp-{os.getpid()}"
    tmp.write_text(json.dumps(stored(st), ensure_ascii=False, indent=2), encoding="utf-8")
    log_event = None
    if event:
        log_event = {**event, "delta": state_delta(disk, st), "rev": st["rev"]}
        if not same_retried_event:
            log(d, log_event)
    for area in root_pending:
        log(d, {"ev": "root-pending", "area": area})
    for area in root_reraised:
        log(d, {"ev": "root-reraise", "area": area})
    if log_event and os.environ.get("TW_TEST_SAVE_CRASH") == "before-state-replace": os._exit(86)
    tmp.replace(d / "state.json")
    st["_rev_loaded"] = st["rev"]
    if log_event and os.environ.get("TW_TEST_SAVE_CRASH") == "after-state-replace": os._exit(87)
    (d / "BOARD.md").write_text(render_board(st), encoding="utf-8")
    for stale in d.glob("state.json.tmp-*"):
        if re.fullmatch(r"state\.json\.tmp-\d+", stale.name) and (stale.is_file() or stale.is_symlink()):
            try:
                stale.unlink()
            except OSError:
                pass



DOC_KINDS = ("board", "ledger", "features", "nav")
CHAIN_STEPS = ("recorded", "dispatched", "accepted", "review", "merged", "reported")


def progress_chain(st, q):
    """B4: how far one request has come: recorded -> dispatched -> accepted -> review -> merged -> reported."""
    tasks = [st.get("tasks", {}).get(t, {}) for t in q.get("tasks") or []]
    steps = (True, any(int(t.get("dispatch_v") or 0) >= 1 for t in tasks),
             any(t.get("status") in ("working", "blocked", "review", "done") for t in tasks),
             any(t.get("status") in ("review", "done") for t in tasks),
             any(t.get("merged_at") for t in tasks), q.get("status") in ("reported", "landed", "closed"))
    return " → ".join(lab(st, "chain_" + name) + ("✓" if yes else "·") for name, yes in zip(CHAIN_STEPS, steps))


def read_file(d, name):
    p = d / name
    return p.read_text(encoding="utf-8") if p.exists() else ""


def csv(s):
    return [x.strip() for x in s.split(",") if x.strip()] if s else []


SHORT_RE = r"[A-Za-z0-9][A-Za-z0-9-]{0,5}"
TITLE_TARGET = 24  # session titles are read in a narrow sidebar


def default_short(project):
    """Short name for a new project: the name itself if it fits in 6 chars, else the initials (TFCC)."""
    if len(project) <= 6:
        return project
    initials = "".join(w[0] for w in project.split("-") if w).upper()
    return initials[:6] if len(initials) >= 2 else project[:6]


def tag(st):
    """Project label used in titles, message headers and tags. Old projects without short_name keep the full name."""
    return (pref(st, 'short_name') or "").strip() or st["project"]


def title_for(st, name):
    t = st["threads"][name]
    focus = t.get("focus") or ""
    return f"[{tag(st)}] {name} · {focus}" if focus else f"[{tag(st)}] {name}"


def lead_title(st):
    return f"[{tag(st)}] ★lead · " + lab(st, "lead_seat_title")


PERMISSION_MODES = ("default", "acceptEdits", "auto", "dontAsk", "bypassPermissions")
# How loose each mode is: create_session refuses a thread looser than its creator (auto needs an auto parent).
PERMISSION_RANK = {"default": 0, "dontAsk": 0, "acceptEdits": 1, "auto": 2, "bypassPermissions": 3}
THREAD_MODE_DEFAULT = "auto"  # threads that do real work; ordinary calls never ask (R44)
STANDING_GRANTS = ("archive", "schedule", "merge")  # what the user may allow once for the lead (IL-30)


def thread_mode(st):
    return (pref(st, 'thread_permission_mode') or "").strip() or THREAD_MODE_DEFAULT


def permission_warning(st):
    """One line for the user when threads cannot get the mode they need, or None. Never a silent downgrade."""
    want = thread_mode(st)
    lead = (st.get("lead", {}).get("permission_mode") or "").strip()
    live = [n for n, t in st["threads"].items() if t.get("status") not in ("archived", "resolved")]
    if not lead:
        return ("the lead's own permission mode is not recorded: check it (get_session, or the mode menu under this "
                f"session's message box) and run `tw.py lead --mode <mode>`; threads are opened with {want}")
    if PERMISSION_RANK.get(lead, 0) >= PERMISSION_RANK.get(want, 0):
        behind = [n for n in live if st["threads"][n].get("session_id") and st["threads"][n].get("permission_mode")
                  and PERMISSION_RANK.get(st["threads"][n]["permission_mode"], 0) < PERMISSION_RANK.get(want, 0)]
        if behind:
            return (f"threads running below {want}: {', '.join(behind)}; they ask for ordinary calls. Tell the user "
                    f"to switch each to {want} in its mode menu, or reseat them with permission_mode={want}")
        return None
    return (f"Tell the user: this lead session runs in {lead} mode, so create_session refuses {want} for threads and "
            f"they would ask before ordinary calls. Switch this session to {want} (claude.ai: the mode menu under the "
            f"message box; or reopen the lead with permission_mode={want}), then run `tw.py lead --mode {want}`. "
            f"Threads affected: {', '.join(live) or 'none yet'}")
# Pre-approved in every thread (create_session extra_allowed_tools) so reporting never stalls on a prompt.
# The lead can only grant what it has pre-approved itself (install.py adds these allow rules).
THREAD_TOOLS = [
    "mcp__claude-code-remote__send_message",
    "mcp__claude-code-remote__get_session",
    "mcp__claude-code-remote__list_events",
]


def worktree_path(st, name):
    """rc thread worktree: <project folder>-worktrees/<thread>, next to the project folder (full name, not short)."""
    repo = Path(st.get("repo", {}).get("path") or ".")
    return repo.parent / f"{repo.name}-worktrees" / name


def worktree_cmd(st, name):
    t = st["threads"][name]
    repo = st.get("repo", {}).get("path") or "."
    base = st.get("repo", {}).get("base") or "main"
    path = t.get("worktree") or str(worktree_path(st, name))
    return f'git -C "{repo}" worktree add -b {branch_of(st, name)} "{path}" {base}'


def session_args(st, name):
    """Extra create_session arguments for a thread: permission mode and pre-approved tools."""
    out = {"extra_allowed_tools": THREAD_TOOLS, "permission_mode": thread_mode(st)}
    if (st["threads"].get(name) or {}).get("model"):
        out["model"] = st["threads"][name]["model"]  # IL-31: the thread's default model
    w = permission_warning(st)
    if w:
        out["permission_warning"] = w
    if st.get("lead", {}).get("permission_mode") == "auto": out["managed_note"] = model_lab(st, "auto_note")
    return out


def title_warning(title):
    if len(title) > TITLE_TARGET + 8:
        return (f"title is {len(title)} chars; aim for about {TITLE_TARGET}: shorten the thread name or --focus")
    return None


# ------------------------------------------------------------------ rendering


def render_roster(st, for_thread=None, board=False, all_threads=False):
    lead = st["lead"]
    lines = [
        f"- lead | rc | session_id={lead.get('session_id') or '(unset)'} | coordinator: plans, routes, merges, talks to the user"
    ]
    if _compact_label(st,"lead"): lines[0] += " | " + _compact_label(st,"lead")
    for name, t in st["threads"].items():
        if not all_threads and (t["status"] == "archived" or (board and (t["status"] == "resolved" or (t["status"] == "planned" and not t.get("session_id"))))):
            continue
        me = "   <- YOU" if name == for_thread else ""
        owns = ", ".join(t.get("owns", [])) or "-"
        line=f"- {name} | {t['kind']} | session_id={t.get('session_id') or '(pending)'} | owns: {owns}{me}"
        if thread_corrections(st,name) >= pref(st, 'root_fresh_at'):
            line += " | " + lab(st,"root_fresh_hint",thread=name)
        lines.append(line)
    return "\n".join(lines)


def render_tasks(st, only_owner=None):
    rows = []
    for tid, k in st["tasks"].items():
        if only_owner and k.get("owner") != only_owner:
            continue
        deps = ",".join(k.get("deps", [])) or "-"
        rv = k.get("review") or {}
        verdict = lab(st, "review_blocked_env") if rv.get("result") == "blocked-env" else rv.get("result")
        review = f"{verdict} ({rv.get('reviewer') or '-'})" if rv else "-"
        if k.get("checks"):
            review += f", checks {k['checks']}"
        primary = task_primary_label(st, k)
        if re.search(r"https?://\S+", (k.get("primary_check") or {}).get("evidence", ""), re.I):
            primary += f" ({lab(st, 'primary_url')})"
        reqs = ",".join([r + {"closed": "✓", "dropped": "✗"}.get(q["status"], "")
                         for r, q in st.get("requests", {}).items() if tid in (q.get("tasks") or [])]
                        + [f"({r})" for r in k.get("from_requests") or []]) or "-"  # (R1): follow-up, not holding it
        rows.append(
        f"| {tid} | {(lab(st,'root_patch_tag') if k.get('fix_kind')=='patch' else lab(st,'root_fix_tag') if k.get('fix_kind')=='root' else '')}{k['title']}" + (f" ({k['route']})" if k.get("route") else "") + f" | {k.get('owner') or '-'} | {deps} | {k['status']} | {k.get('accept') or '-'} "
            f"| {review} | {primary} | {reqs} |"
        )
    if not rows:
        return "(no tasks)"
    return (
        f"| id | task | owner | deps | status | done when | review | {lab(st, 'board_primary_col')} | req |\n|---|---|---|---|---|---|---|---|---|\n"
        + "\n".join(rows)
    )


def _cell(x):
    return str(x).replace("|", "\\|").replace("\n", " ")


def render_reviews(st, only=None):
    """Per task: verdict, rounds, reviewer, G8 test/base record, findings and follow-ups."""
    cap = review_max(st)
    rows = []
    for tid, k in st["tasks"].items():
        if only and tid != only:
            continue
        rv = k.get("review") or {}
        verdict = lab(st, "review_blocked_env") if rv.get("result") == "blocked-env" else rv.get("result")
        n = int(k.get("review_rounds") or 0)
        if not rv and not n and not k.get("past_reviews"):
            continue
        fu = [t + (" (verdict voided)" if x.get("parent_verdict_voided") else "")
              for t, x in st["tasks"].items() if x.get("followup_of") == tid]
        left = "; ".join(rv.get("remaining") or []) or "-"
        test_line = review_tests_line(st, rv) if rv else "-"
        shown_cap = rv.get("cap", cap) if "result" not in rv or "cap" in rv else "?"
        rows.append("| " + " | ".join(_cell(x) for x in (
            tid, k.get("owner") or "-", k["status"], verdict or "-", f"{n}/{shown_cap or '-'}",
            rv.get("reviewer") or "-", k.get("checks") or "-", test_line, left, ",".join(fu) or "-")) + " |")
    if not rows:
        return "(no reviews recorded)"
    return (f"| task | owner | status | verdict | rounds | reviewer | checks | {lab(st, 'reviews_tests_base_col')} | remaining | follow-ups |\n"
            "|---|---|---|---|---|---|---|---|---|---|\n" + "\n".join(rows))


def task_followups(d, st, a):
    """One follow-up task per important finding left at a pass or capped review; dry run unless --apply."""
    if a.id not in st["tasks"]:
        sys.exit(f"unknown task {a.id}")
    k = st["tasks"][a.id]
    rv = k.get("review") or {}
    if rv.get("result") not in PASSING or not rv.get("remaining"):
        sys.exit(f"{a.id} has no passing or capped review with remaining findings (`task set {a.id} --review "
                 "pass|capped --remaining ...` first)")
    done = {x.get("followup_item") for t, x in st["tasks"].items() if x.get("followup_of") == a.id}
    reqs = [r for r, q in st.get("requests", {}).items() if a.id in (q.get("tasks") or [])]
    plan, n = [], 0
    for item in rv["remaining"]:
        if item in done:
            continue
        n += 1
        while True:
            tid = f"{a.id}-f{n}"
            if tid not in st["tasks"]:
                break
            n += 1
        plan.append((tid, item))
    out = []
    for tid, item in plan:
        out.append({"id": tid, "owner": k.get("owner"), "accept": f"fixed, with a test that fails before the fix: {item}",
                    "followup_of": a.id, "requests": reqs})
        if a.apply:
            st["tasks"][tid] = {
                "title": f"follow-up of {a.id}: {item}"[:120],
                "owner": k.get("owner"),
                "deps": [a.id],  # starts from the merged parent, not from unmerged code
                "accept": out[-1]["accept"],
                "touches": list(k.get("touches") or []),
                "topics": list(k.get("topics") or []),
                "status": "approved" if st["plan_approved"] else "planned",
                "notes": "",
                "created": now(),
                "followup_of": a.id,
                "followup_item": item,
                "from_requests": reqs,  # for trace; not linked, so the original request is not held back
            }
    if a.apply and plan:
        save(d, st, {"ev": "task-followups", "task": a.id, "added": [t for t, _ in plan]})
    print(json.dumps({"from": a.id, "apply": bool(a.apply), "tasks": out,
                      "next": ("show them to the user with the plan; dispatch like any task" if a.apply and plan
                               else "re-run with --apply to add them" if plan else "nothing new to add")},
                     ensure_ascii=False, indent=2))


def render_groups(st, board=False, all_threads=False):
    order = ["waiting", "stuck", "review", "working", "starting", "landing", "planned", "idle"]
    stuck = stuck_threads(st)
    out = []
    for g in order:
        if g == "stuck":
            if stuck:
                out.append(f"**{lab(st, 'stuck', n=pref(st, 'stuck_minutes'))}**")
                for n, m in stuck.items():
                    t = st["threads"][n]
                    cause = lab(st, "stuck_" + t["stuck_on"]) if t.get("stuck_on") else lab(st, 'no_report', m=m)
                    waiting = (lab(st, 'waiting_for', why=lab(st, 'wait_' + t['waiting_for'])) + " — ") if t.get("waiting_for") else ""
                    out.append(f"- {t.get('title') or n} ({t['kind']}) — {waiting}{cause} — "
                               f"{t.get('summary') or '-'}")
            continue
        if g == "idle":
            # idle = in its seat, turn ended, can take work (standby); only resolved threads are finished
            for status, key in (("idle", "standby"), ("resolved", "completed")):
                if status == "resolved" and not all_threads:
                    continue
                names = [n for n, t in st["threads"].items() if t["status"] == status]
                if names:
                    details = [f"{n} — {_screen_label(st, n)}" for n in names if _screen_label(st, n)]
                    out.append(lab(st, key, n=len(names), names=", ".join(names)) +
                               (("\n" + "\n".join(f"  {x}" for x in details)) if details else ""))
            continue
        names = [n for n, t in st["threads"].items() if t["status"] == g and n not in stuck and
                 not (board and not all_threads and g == "planned" and not t.get("session_id"))]
        if not names:
            continue
        out.append(f"**{lab(st, g)}**")
        for n in names:
            t = st["threads"][n]
            if g == "waiting" and t.get("waiting_for"):
                out.append(f"- {t.get('title') or n} — {lab(st, 'waiting_for', why=lab(st, 'wait_' + t['waiting_for']))}: "
                           f"{t.get('summary') or '-'}")
                if _screen_label(st, n): out.append(f"  {_screen_label(st, n)}")
                if _compact_label(st,n): out.append(f"  {_compact_label(st,n)}")
                continue
            out.append(
                f"- {t.get('title') or n} ({t['kind']}) — {t.get('summary') or '-'}"
                + (f" — {_screen_label(st, n)}" if _screen_label(st, n) else "")
                + (f" · {_compact_label(st,n)}" if _compact_label(st,n) else "")
            )
    return "\n".join(out) or lab(st, "no_threads")


def render_board(st, all_threads=False):
    approved = (
        "APPROVED"
        if st.get("plan_approved")
        else "DRAFT — waiting for the user's go-ahead"
    )
    r = st.get("repo", {})
    out = [
        f"# teamwork: {st['project']}" + (f" ({tag(st)})" if tag(st) != st["project"] else ""),
        lab(st, "board_as_of", time=(st.get("updated") or now())[11:16], date=(st.get("updated") or now())[:10]) +
        (" — " + lab(st, "possibly_stale") if _ledger_stale(st) else ""),
        "",
    ]
    if st.get("desktop_open_queue"):
        out += [lab(st, "desktop_queued", threads="、".join(st["desktop_open_queue"])), ""]
    if st.get("sprint") and not st["sprint"].get("ended_at"):
        until = _when(st["sprint"].get("until"))
        minutes = max(0, int((until - _when(now())).total_seconds() // 60)) if until else "?"
        out += [lab(st, "sprint_board", until=(st["sprint"].get("until", "?")[11:16] if "T" in st["sprint"].get("until", "") else st["sprint"].get("until", "?")), minutes=minutes), ""]
    if quota_pace_tier(st)[0] != "normal":
        out += [lab(st, "pace_board", checkin=effective_interval(st, "checkin_minutes"),
                    quota=effective_interval(st, "quota_every_minutes")), ""]
    notice = st.get("version_notice") or {}
    if notice.get("release") == running_version()[0] and notice.get("sessions"):
        out += [lab(st, "version_notice", n=len(notice["sessions"]), sessions=", ".join(notice["sessions"])), ""]
    recent = st.get("reconcile") or {}
    docs = [f"- [{lab(st, 'doc_' + key)}]({doc['link']})" + (f" — {_md(doc['note'])}" if doc.get("note") else "") +
            f" — {_age_label(st, doc.get('refreshed_at'))}" + (" (" + lab(st, "d_stale") + ")" if _doc_stale(st, doc) else "")
            for key in DOC_KINDS for doc in [st.get("docs", {}).get(key)] if doc and doc.get("link")]
    if docs:
        out += docs + [""]
    if recent.get("count"):
        out += [lab(st, "reconcile_badge", n=recent["count"]), ""]
    for model, status in st.get("models", {}).items():
        if status.get("down"):
            reason = model_lab(st, "model_reason_" + status.get("why", "other"))
            out += [model_lab(st, "model_down", model=model.upper(), why=reason, until=status.get("until") or "?"), ""]
    current_sids = {t.get("session_id") for t in st.get("threads", {}).values()  # back at work: no longer a failed archive
                    if t.get("session_id") and t.get("status") in ("working", "starting", "waiting", "review", "landing")}
    failed_archives = [(sid, rec) for sid, rec in st.get("archive", {}).items()
                       if rec.get("check") == "failed" and not rec.get("archived_at") and sid not in current_sids]
    if failed_archives:
        out += ["## " + lab(st, "s_issues"), ""]
        out += ["- " + lab(st, "archive_failed_row", sid=sid, seat=rec.get("seat", "?"))
                for sid, rec in failed_archives] + [""]
    roots = [(n,v) for n,v in radar(st).items() if v["state"] != "ok"]
    if roots:
        out += [f"## {lab(st,'root_heading')}", "", f"| {lab(st,'root_area_col')} | {lab(st,'root_state_col')} | {lab(st,'root_symptoms_col')} | {lab(st,'root_rework_col')} | {lab(st,'root_debt_col')} | {lab(st,'root_review_col')} | {lab(st,'root_next_col')} |", "|---|---|---:|---:|---:|---|---|"]
        for area,v in roots:
            rec=st.get("areas",{}).get(area,{})
            state=lab(st,"root_"+v["state"])
            if rec.get("root_pending"): state += lab(st,"root_default_note")
            out.append(f"| {area} | {state} | {len(v['symptoms'])} | {v['rework']} | {len(rec.get('debt',[]))} | {rec.get('rc',0) or '-'} | {root_next(v['state'],area,st)} |")
        out.append("")
    reqs = render_requests(st, chain=True)
    if reqs:
        out += [f"## {lab(st, 'requests')}", "", reqs, ""]
    reported = [(rid, q) for rid, q in st.get("requests", {}).items() if awaiting_confirm(st, q)]
    if reported:
        out += ["<details>", f"<summary>{lab(st, 'req_reported_heading', n=len(reported))}</summary>", ""]
        out += [f"- {rid}: {_md(q.get('text',''))}\n  - {progress_chain(st, q)}" for rid, q in reported[:5]]
        if len(reported) > 5: out += [lab(st, "req_reported_more", n=len(reported)-5)]
        out += ["", "</details>", ""]
    features = render_features(st)
    if features:
        out += [f"## {lab(st, 'features')}", "", features, ""]
    needs_location = render_feature_needs_location(st)
    if needs_location:
        out += [needs_location, ""]
    remarks = [(r, q) for r, q in st.get("requests", {}).items() if q.get("status") == "remark"][-10:]
    if remarks: out += ["## " + lab(st, "remark_heading"), ""] + [f"- {r}: {_md(q['text'])}" for r, q in remarks] + [""]
    defaults = [x for x in st.get("decisions", []) if not x.get("answered") and not x.get("confirmed")]
    if defaults: out += ["## " + lab(st, "default_heading"), ""] + [f"- [{x['question']}] {_md(x['what'])}" for x in defaults] + [""]
    promises = [x for x in st.get("promises", []) if x.get("status") == "open"]
    if promises: out += ["## " + lab(st, "promise_heading"), ""] + [f"- {x['id']}: {_md(x['text'])}" for x in promises] + [""]
    pending = st.get("qa_pending", [])
    if pending:
        out += [f"## {lab(st, 'qa_pending')}", ""]
        out += [f"- {x.get('branch', '?')}@{str(x.get('sha', ''))[:7]}" for x in pending]
        out += ["", "`tw.py qa done` after the regression round", ""]
    out += [
        f"Goal: {st.get('goal') or '-'}",
        f"Plan: {approved}    Updated: {st.get('updated', '-')}",
        f"Folder: {r.get('path') or '-'}    Repo: {r.get('url') or '-'}    Base branch: {r.get('base') or 'main'}",
        f"Prefs: {json.dumps(stored(st).get('prefs', {}), ensure_ascii=False)}",
        "",
        f"## {lab(st, 'overview')}",
        "",
        render_groups(st, board=True, all_threads=all_threads),
    ]
    thread_q = [(i, q) for i, q in enumerate(st.get("questions", [])) if not q.get("answered") and q.get("from") not in ("lead", "user") and not q.get("external")]
    if thread_q:
        out += ["", f"## {lab(st, 'thread_waiting_heading')}", ""]
        out += [f"- [{i + 1}] ({q['from']}) {_md(q['text'])}" + (" — " + lab(st, "default_prefix") + _md(q["defaulted"].get("what", "")) if q.get("defaulted") else "") for i, q in thread_q]
    open_q = [
        (i, q) for i, q in enumerate(st.get("questions", [])) if not q.get("answered") and q not in [x[1] for x in thread_q]
    ]
    waiting = [
        f"- [{i + 1}] ({q['from']}) " + (lab(st, "proposal_prefix") if q.get("kind") == "proposal" else "") + _md(q['text'])
        + (" — " + lab(st, "default_prefix") + _md(q["defaulted"]["what"]) + lab(st, "can_change") if q.get("defaulted")
           else " — " + model_lab(st, "default_due", n=i + 1) if question_default_due(st, q)
           and not q.get("external") and not q.get("beyond") and not DEFAULT_OUTWARD_RE.search(q.get("text", "")) else "")
        for i, q in open_q
    ] + ["- " + model_lab(st, "needs_user") + _md(x.get("text", ""))
         for x in st.get("notices", []) if not x.get("done") and x.get("kind") == "needs-user"] \
      + ["- " + model_lab(st, "parked", seat=x.get("original_owner") or "-", why=x.get("reason") or "-") + _md(x.get("text", ""))
         for x in st.get("notices", []) if not x.get("done") and x.get("kind") == "parked"]
    if waiting:  # one "waiting on the user" section: questions, proposals, steps only they can click, work parked at an archive
        out += ["", f"## {lab(st, 'questions')}", ""] + waiting
    w = merge_waiting(st)
    if w:
        out += ["", lab(st, "merge_waiting", n=len(w), m=w[0]["minutes"] if w[0]["minutes"] is not None else "?",
                        tasks=", ".join(x["task"] for x in w))]
    iss = [i for i in st.get("issues", []) if i.get("status") != "verified"]
    if iss:
        out += ["", f"## {lab(st, 's_issues')}", ""] + [render_issue(i, st) for i in iss]
    deny = [x for x in st.get("model_deny", []) if not x.get("allowed_at")]
    if deny:
        out += ["", f"## {lab(st, 'quota_deny')}", ""] + [f"- {x.get('type')} — {x.get('model')}" for x in deny]
    out += ["", f"## {lab(st, 'roster')}", "", render_roster(st, board=True, all_threads=all_threads), "", f"## {lab(st, 'plan')}", "", render_tasks(st)]
    folded = [n for n, t in st.get("threads", {}).items() if t.get("status") in ("resolved", "archived") or
              (t.get("status") == "planned" and not t.get("session_id"))]
    if folded and not all_threads:
        out += ["", lab(st, "folded_threads", n=len(folded), names=", ".join(folded))]
    elif all_threads and folded:
        out += ["", lab(st, "all_threads") + ":", ""] + [f"- {n} — {t.get('title') or n} — {t.get('status')}" for n, t in st.get("threads", {}).items() if n in folded]
    merges = merge_board_rows(st)
    if merges: out += ["", f"## {lab(st, 'waiting_merge_heading')}", ""] + merges
    collisions = board_collisions(st)
    if collisions: out += ["", f"## {lab(st, 'collision_heading')}", ""] + collisions
    disk = st.get("disk_space") or {}
    if disk.get("summary"): out += ["", f"## {lab(st, 'disk_board')}", "", disk["summary"], ""]
    return "\n".join(out) + "\n"


def merge_board_rows(st):
    rows = []
    for tid, task in st.get("tasks", {}).items():
        if task.get("status") != "review" and not ((task.get("review") or {}).get("result") in PASSING and task.get("status") != "done"):
            continue
        rv = task.get("review") or {}
        owner_branch = (st.get("threads", {}).get(task.get("owner") or "") or {}).get("branch")
        rows.append(f"- {tid}: {task.get('title', tid)} — {task.get('branch') or owner_branch or '-'} — "
                    f"{lab(st, 'review_blocked_env') if rv.get('result') == 'blocked-env' else rv.get('result', 'none')} ({task.get('review_rounds', 0)}), checks {task.get('checks', 'none')}")
    return rows


def board_collisions(st):
    rows, tasks = [], st.get("tasks", {})
    active = [(i, t) for i, t in tasks.items() if t.get("status") not in ("done", "dropped", "recalled")]
    for ix, (tid, task) in enumerate(active):
        for oid, other in active[ix + 1:]:
            if task.get("owner") == other.get("owner"): continue
            clashes = set()
            for a in task.get("touches", []):
                for b in other.get("touches", []):
                    if not paths_overlap(a, b): continue
                    aa, bb = str(a).rstrip("/"), str(b).rstrip("/")
                    clashes.add(min(aa, bb, key=len) if not any(x in aa + bb for x in "*?[]{") and
                                (aa == bb or aa.startswith(bb + "/") or bb.startswith(aa + "/")) else aa)
            for path in sorted(clashes):
                rows.append("- " + lab(st, "collision_tasks", a=tid, owner_a=task.get("owner") or "-", b=oid,
                                         owner_b=other.get("owner") or "-", path=path))
    for tid, task in active:
        for dep in task.get("deps", []):
            other = tasks.get(dep, {})
            if other and other.get("status") not in ("done", "dropped", "recalled") and task.get("owner") != other.get("owner"):
                rows.append("- " + lab(st, "dependency_task", task=tid, owner=task.get("owner") or "-", dep=dep,
                                         dep_owner=other.get("owner") or "-"))
    return rows


ISSUE_STATUSES = ("open", "fixed-on-branch", "merged", "verified")
DELIVERABLE_STATUSES = ("draft", "final")


def render_issue(i, st=None):
    st = st or {}
    return (f"- {i['id']} [{lab(st, 'i_' + i['status'])}] {_md(i['text'])} ({lab(st, 'owner')}: {i.get('owner') or '-'}"
            + (f"; {i['ref']}" if i.get("ref") else "")
            + (f"; {lab(st, 'reporters')}: {', '.join(i.get('reporters', []))}"
               if [x for x in i.get("reporters", []) if x != i.get("owner")] else "") + ")")


def _where(x):
    """A link or path stays as typed (escaping would break it when the text is pasted); other text is escaped."""
    x = " ".join(str(x or "").split())
    return f"<{x}>" if re.fullmatch(r"https?://\S+", x) else f"`{x}`" if x and " " not in x and "`" not in x else _md(x)


def _md(x):
    """User text inside markdown: one line, and ~ * _ ` escaped, so it never strikes, bolds or breaks a list item."""
    return re.sub(r"([~*_`\\])", r"\\\1", " ".join(str(x or "").split()))


def _ledger_stale(st):
    updated = _when(st.get("updated"))
    current = _when(now())
    return bool(updated and current and (current - updated).total_seconds() > int(pref(st, 'stale_minutes')) * 60)


def _doc_stale(st, doc):
    refreshed, updated = _when(doc.get("refreshed_at")), _when(st.get("updated"))
    return bool(updated and (not refreshed or (updated - refreshed).total_seconds() > int(pref(st, 'stale_minutes')) * 60))


def _age_label(st, stamp):
    when = _when(stamp)
    if not when: return lab(st, "doc_age_unknown")
    current = _when(now())
    minutes = max(0, int((current - when).total_seconds() // 60)) if current else 0
    age = lab(st,"doc_age_minutes",n=minutes) if minutes < 60 else lab(st,"doc_age_hours",n=minutes//60) if minutes < 1440 else lab(st,"doc_age_days",n=minutes//1440)
    return lab(st, "doc_refreshed", age=age)


def _current_feature_phase(st):
    phase = pref(st, 'current_phase')
    if phase: return phase
    phases = sorted({f.get("phase") for f in st.get("features", {}).values()
                     if f.get("status") in ("planned", "building") and f.get("phase")})
    return phases[0] if phases else ""


def render_share(st):
    """IL-13, IL-38: what the user opens on a phone, in their language. Deliverables first, then their requests,
    waiting items, issues, then every requirement by phase and category so stale ones can be struck out."""
    L = lambda k, **kw: lab(st, k, **kw)
    saved_at = st.get("updated") or now()
    out = [f"# {st['project']}: {L('s_title')}", "", L("board_as_of", time=saved_at[11:16], date=saved_at[:10]) + (" — " + L("possibly_stale") if _ledger_stale(st) else ""),
           f"{L('s_updated')} {st.get('updated', '-')[:16].replace('T', ' ')}",
           ""]
    dl = [x for x in st.get("deliverables", []) if x.get("status") != "superseded"]
    out += [f"## {L('s_deliverables')}", ""] + ([f"{i + 1}. **{_md(x['name'])}** — {L('d_' + x['status'])}"
                                                 + (f" — {x['link']}" if x.get("link") else "")
                                                 + (f" ({L('s_missing')}: {_md(x['missing'])})" if x.get("missing")
                                                    else "")
                                                 for i, x in enumerate(dl)] or [L("s_none_yet")]) + [""]
    roots=[(n,v) for n,v in radar(st).items() if v["state"]!="ok"]
    if roots: out += [f"## {L('root_heading')}", ""] + [f"- {n}: {L('root_'+v['state'])} ({len(v['symptoms'])} {L('s_symptoms')}, {v['rework']} {L('s_rework')})" for n,v in roots] + [""]
    reqs = st.get("requests", {})
    live = [(r, q) for r, q in reqs.items() if q["status"] not in REQ_END and not awaiting_confirm(st, q)]
    out += [f"## {L('s_requests')}", ""] + ([f"- {r} — {L('req_' + q['status'])}: {_md(q['text'])}"
                                             + (f" → {_where(q['where'])}" if q.get("where") else "")
                                             + (f" ({L('followup')}: {_md(q['followup'])})" if q.get("followup")
                                                else "")
                                             for r, q in live] or [L("s_none_open")]) + [""]
    reported=[(r,q) for r,q in reqs.items() if awaiting_confirm(st, q)]
    if reported:
        out += ["<details>", f"<summary>{L('req_reported_heading',n=len(reported))}</summary>", ""]
        out += [f"- {r} — {_md(q['text'])}" for r,q in reported[:5]]
        if len(reported)>5: out += [L("req_reported_more",n=len(reported)-5)]
        out += ["", "</details>", ""]
    features = render_features(st)
    if features:
        out += [f"## {L('features')}", "", features, ""]
    qs = [q for q in st.get("questions", []) if not q.get("answered")]
    if qs:
        out += [f"## {L('s_waiting')}", ""] + [f"- {_md(q['text'])} ({q['from']})" for q in qs] + [""]
    iss = [i for i in st.get("issues", []) if i.get("status") != "verified"]
    if iss:
        out += [f"## {L('s_issues')}", ""] + [render_issue(i, st) for i in iss] + [""]
    remarks = [(r, q) for r, q in st.get("requests", {}).items() if q.get("status") == "remark"][-10:]
    if remarks: out += ["## " + lab(st, "remark_heading"), ""] + [f"- {r}: {_md(q['text'])}" for r, q in remarks] + [""]
    defaults = [x for x in st.get("decisions", []) if not x.get("answered") and not x.get("confirmed")]
    if defaults: out += ["## " + lab(st, "default_heading"), ""] + [f"- [{x['question']}] {_md(x['what'])}" for x in defaults] + [""]
    promises = [x for x in st.get("promises", []) if x.get("status") == "open"]
    if promises: out += ["## " + lab(st, "promise_heading"), ""] + [f"- {x['id']}: {_md(x['text'])}" for x in promises] + [""]
    pending = st.get("qa_pending", [])
    if pending:
        out += [f"## {L('qa_pending')}", ""]
        out += [f"- {x.get('branch', '?')}@{str(x.get('sha', ''))[:7]}" for x in pending]
        out += [""]
    if reqs:
        out += [f"## {L('s_all')}", ""]
        groups = {}
        for r, q in reqs.items():  # phases in the order the user first used them
            groups.setdefault((q.get("phase") or "", q.get("category") or ""), []).append((r, q))
        for (ph, cat), items in groups.items():
            out += [f"### {_md(ph or '-')} / {_md(cat or '-')}" if ph or cat else f"### {L('s_ungrouped')}"]
            for r, q in items:
                body = f"{r}: {_md(q['text'])}"
                out.append(f"- {'~~' + body + '~~' if q['status'] in REQ_END else body} — {L('req_' + q['status'])}")
            out.append("")
    return "\n".join(out).rstrip() + "\n"


# ------------------------------------------------------------------ commands


def detect_base(folder):
    """The repo's default branch: origin/HEAD, else the current branch, else main."""
    g = lambda *x: subprocess.run(["git", "-C", str(folder), *x], capture_output=True, text=True)
    r = g("symbolic-ref", "--quiet", "--short", "refs/remotes/origin/HEAD")
    if r.returncode == 0 and r.stdout.strip().startswith("origin/"):
        return r.stdout.strip()[len("origin/"):]
    r = g("symbolic-ref", "--quiet", "--short", "HEAD")
    if r.returncode == 0 and r.stdout.strip() and not r.stdout.strip().startswith("tw/"):
        return r.stdout.strip()
    return "main"


def cmd_init(a):
    d = find_dir(create_at=a.path)
    if (d / "state.json").exists() and not a.force:
        sys.exit(f"{d}/state.json already exists (use --force to overwrite)")
    if a.force and (d / "state.json").exists():
        if not (getattr(a, "user_said", None) or "").strip():
            sys.exit("init --force requires --user-said: overwriting project state is the user's decision")
        shutil.copy2(d / "state.json", d / "state.json.bak")
    if not re.fullmatch(NAME_RE, a.project):
        sys.exit("project name: lowercase letters/digits/hyphen, max 24 chars")
    short = a.short or default_short(a.project)
    if not re.fullmatch(SHORT_RE, short):
        sys.exit("short name: letters/digits/hyphen, max 6 chars (e.g. TFCC, shop)")
    st = _new_state(a.project, a.goal or "", now(), a.repo_url, str(Path(a.path).resolve()),
                    a.base or detect_base(Path(a.path)), short)
    if not (d / "INSTRUCTIONS.md").exists():
        (d / "INSTRUCTIONS.md").write_text(
            f"# {a.project}: project instructions\n\n"
            "Standing instructions for the lead and every thread: coding style, what not to touch, how to report.\n"
            "New threads get this file at creation. Running threads only see changes when the lead re-broadcasts.\n\n",
            encoding="utf-8",
        )
    if not (d / "MEMORY.md").exists():
        (d / "MEMORY.md").write_text(
            f"# {a.project}: project memory\n\n"
            "Facts, decisions and conventions every thread must respect. Only the lead edits this file;\n"
            "threads propose additions with a MEMORY message. Keep it short: it is pasted into every new thread.\n\n"
            + "".join(f"{h}\n\n" for h in MEMORY_SECTIONS.values()),
            encoding="utf-8",
        )
    gi = d / ".gitignore"
    need_ig = ["state.json.tmp", "state.json.rebuilt", "state.json.bak", "state.json.bak-*", "PRIVATE.md", "private/"]
    have = gi.read_text(encoding="utf-8").splitlines() if gi.exists() else []
    if any(x not in have for x in need_ig):
        gi.write_text("\n".join(have + [x for x in need_ig if x not in have]) + "\n", encoding="utf-8")
    if not (d / "PRIVATE.md").exists():
        (d / "PRIVATE.md").write_text(PRIVATE_HELP, encoding="utf-8")
    (d / "private").mkdir(exist_ok=True)
    try:
        disk_state = json.loads((d / "state.json").read_text(encoding="utf-8")) if (d / "state.json").exists() else {}
    except (OSError, ValueError, TypeError):
        disk_state = {}
    st["_rev_loaded"] = disk_state.get("rev", 0)
    save(d, st, {"ev": "init", "project": a.project})
    print(f"initialised {d}")


def cmd_lead(a):
    d = need(find_dir())
    st = load(d)
    if a.session is not None and any(x.get("seat") == "lead" and _ho_open(x) for x in st.get("handovers", {}).values()):
        sys.exit(lab(st,"succ_handover_lock_hint"))
    old = st["lead"].get("session_id")
    old_permission_mode = st["lead"].get("permission_mode")
    relead = bool(getattr(a, "relead", False))
    if relead:  # a new lead after a failed opening screen (screen relead holds the ledger for it)
        lock = st.get("write_lock") or {}
        if not lock.get("relead"): sys.exit(lab(st, "relead_no_lock"))
        if not (a.session or "").strip(): sys.exit(lab(st, "relead_session_required"))
        a.session = a.session.strip()
        tried = {x.get("session") for x in st.get("lead_trials", [])}
        if a.session in (lock.get("old_session"), old) or a.session in tried or _screen_failed(st, a.session):
            sys.exit(lab(st, "relead_same_session"))
        a.force, a.reason = True, "relead after failed opening screen"
        st["lead"]["permission_mode"] = old_permission_mode or "auto"
        if st["lead"]["permission_mode"] != "auto":
            print(lab(st, "lead_mode_inherited"), file=sys.stderr)
    elif st.get("write_lock") and a.session is not None:
        sys.exit(lab(st, "lead_relead_locked") if st["write_lock"].get("relead") else
                 lab(st, "lead_write_locked", ho=st["write_lock"].get("ho")))
    if a.session is not None:
        a.session = a.session.strip()
    if a.session and old != a.session and _screen_failed(st, a.session):
        sys.exit(lab(st, "critical_screen_block"))
    if a.session and a.force and not getattr(a, "relead", False) and any(x.get("session") == a.session for x in st.get("lead_trials") or []):
        sys.exit(lab(st, "relead_same_session"))
    if a.session and old and old != a.session and a.force:
        latest = next((x for x in reversed(list(st.get("screens", {}).values())) if x.get("seat") == "lead" and x.get("session_id") == a.session), None)
        if latest and latest.get("verdict") != "pass":
            print(lab(st, "screen_gate_warning", seat="lead", verdict=_verdict_word(st, latest.get("verdict"))), file=sys.stderr)
    if a.session and not_a_session(a.session, st):
        sys.exit(not_a_session(a.session, st).split(": a thread is")[0] + ": the lead is the user's own Remote "
                 "Control session; pass its id from get_session")
    if a.session and old and old != a.session and not a.force:
        sys.exit(f"project {st['project']} already has lead {old}. One lead per project: check that session with "
                 "get_session; if it is archived or the user says to take over, re-run with --force.")
    if a.session and any(c.get("session_id")==a.session for h in st.get("handovers",{}).values() if _ho_open(h) for c in h.get("candidates",[])):
        sys.exit(lab(st,"succ_candidate_busy"))
    if a.session:
        holder = next((n for n, t in st["threads"].items() if t.get("session_id") == a.session
                       and t.get("status") != "archived"), None)
        if holder:
            sys.exit(f"session {a.session} holds the {holder} seat; the lead needs its own session")
        if a.session != old:
            bump_roster(st)  # the roster names the lead: every thread needs the new id
            _close_archived(st, a.session, "the lead", now())
        if old != a.session:
            hist = st["lead"].setdefault("sessions", [])
            if not hist and old:
                hist.append({"session_id": old, "from": st.get("created") or now(), "to": now(), "reason": "legacy lead"})
            if hist and hist[-1].get("session_id") == old and not hist[-1].get("to"):
                hist[-1].update(to=now(), reason=getattr(a, "reason", None) or "lead changed")
            hist.append({"session_id": a.session, "from": now(), "to": None, "reason": getattr(a, "reason", None) or "lead changed"})
        st["lead"]["session_id"] = a.session
    if a.mode:
        st["lead"]["permission_mode"] = a.mode
    if getattr(a, "opened_by", None): st["lead"]["opened_by"] = a.opened_by
    if getattr(a, "spawn_probe", None):
        st["lead"]["spawn_probe"] = {"result": a.spawn_probe, "note": getattr(a, "note", None) or "", "at": now()}
    if a.rc_env:
        st["envs"]["rc"] = a.rc_env
    if a.cloud_env:
        st["envs"]["cloud"] = a.cloud_env
    if a.repo_url:
        st["repo"]["url"] = a.repo_url
    if a.base:
        st["repo"]["base"] = a.base
    if getattr(a, "desktop", False): st["lead"]["desktop"] = True
    readonly = a.session is None and not (a.mode or a.rc_env or a.cloud_env or a.repo_url or a.base or getattr(a, "desktop", False) or getattr(a, "opened_by", None) or getattr(a, "spawn_probe", None))
    if relead:
        st.pop("write_lock", None)
    if not readonly:
        save(d, st, {"ev": "succ-relead-seat" if relead else "lead", "session": a.session, "envs": st["envs"],
                 **({"lead_change":{"from":old,"to":a.session,"history":st["lead"].get("sessions",[])[-2:]}} if a.session and old and old != a.session else {}),
                 **({"mode": a.mode} if a.mode else {}), **({"desktop": True} if getattr(a, "desktop", False) else {})})
    out = {"lead": st["lead"], "envs": st["envs"], "repo": st["repo"], "thread_permission_mode": thread_mode(st),
           "title": lead_title(st), "tags": [f"teamwork:{tag(st)}", "teamwork-thread:lead"],
           "set_up": "set_session_title and set_session_tags on your own session with these (IL-34)"}
    w = permission_warning(st)
    if w:
        out["permission_warning"] = w
    print(json.dumps(out, ensure_ascii=False))


def _after(a, b):
    """ISO time a is later than b (offsets compared properly; missing a = never)."""
    left, right = _utc_timestamp(a), _utc_timestamp(b)
    if left is None or (b and right is None):
        return bool(a) and (not b or (a or "") > (b or ""))
    return right is None or left > right


def _utc_timestamp(value):
    """Convert an ISO timestamp to UTC epoch seconds; a missing timezone means UTC."""
    from datetime import datetime, timezone
    try:
        parsed = datetime.fromisoformat(value.replace("Z", "+00:00"))
        return (parsed if parsed.tzinfo else parsed.replace(tzinfo=timezone.utc)).timestamp()
    except (AttributeError, TypeError, ValueError, OSError, OverflowError):
        return None


def _close_archived(st, sid, me, ts):
    """An archived seat that still lists this session: its stint is over (the session moved to `me`)."""
    for n2, t2 in st["threads"].items():
        if n2 != me and t2.get("status") == "archived" and t2.get("session_id") == sid:
            for h in t2.get("sessions", []):
                if h.get("session_id") == sid and not h.get("to"):
                    end = ts if not h.get("from") or _after(ts, h["from"]) else now()  # never before its start
                    h["to"], h["reason"] = end, f"session moved to {me}"


def _session_taken(st, sid, me, handover=None):
    """Another live seat already holds this session: two seats would share one inbox."""
    other=next((n for n, t in st["threads"].items()
                 if n != me and t.get("session_id") == sid and t.get("status") not in ("archived", "resolved", "planned")), None)
    if other: return other
    for hid,ho in st.get("handovers",{}).items():
        if hid==handover or ho.get("phase") in ("aborted","retired"): continue
        occupied={x.get("session_id") for x in ho.get("candidates",[])}|{ho.get("successor")}
        if sid in occupied: return f"handover {hid}"
    return None


def _succ_handover_gate(st, hid, seat, sid):
    ho=st.get("handovers",{}).get(hid) or {}
    candidate=next((x for x in ho.get("candidates",[]) if x.get("session_id")==sid),None)
    missing=[]
    if ho.get("seat")!=seat or ho.get("phase") in ("aborted","retired"): missing.append("handover")
    if not candidate: missing.append("candidate")
    if (ho.get("verify") or {}).get("candidate")!=sid or not (ho.get("verify") or {}).get("passed"): missing.append("verify")
    if (ho.get("quiz") or {}).get("candidate")!=sid or not (ho.get("quiz") or {}).get("passed"): missing.append("quiz")
    steps=ho.get("steps",{}); freeze=_when(steps.get("freeze")); pack=_when(steps.get("pack")); verify=_when(steps.get("verify")); quiz=_when(steps.get("quiz")); grade=_when(steps.get("grade"))
    if not (freeze and pack and verify and freeze<pack<verify): missing.append("freeze < pack < verify")
    if not (pack and quiz and grade and pack<quiz<grade): missing.append("pack < quiz < grade")
    if _succ_pack_gate(ho.get("pack_dir") or ""): missing.append("pack")
    thread=st.get("threads",{}).get(seat) or {}
    snap=_succ_git_snapshot(st,thread.get("branch"),thread.get("worktree"))
    if snap.get("fingerprint")!=(ho.get("freeze") or {}).get("dirty_fingerprint"): missing.append("freeze fingerprint")
    return list(dict.fromkeys(missing))


_SUCC_RECEIPT_SECTIONS = ("Rules", "Only-known-after-reading fact", "Unresolved")


def _succ_receipt_sections_ok(text):
    headings=list(re.finditer(r"(?im)^#{1,4} (.+?)\s*$",str(text or "")))
    names=[m.group(1).strip() for m in headings]
    positions=[]
    for wanted in _SUCC_RECEIPT_SECTIONS:
        idx=next((i for i,name in enumerate(names) if wanted.casefold() in name.casefold()),None)
        if idx is None: return False
        body=str(text)[headings[idx].end():headings[idx+1].start() if idx+1<len(headings) else len(str(text))]
        if not body.strip() or re.search(r"(?i)\bTODO\b|待填|待定|FIXME|XXX",body): return False
        positions.append(idx)
    return positions==sorted(positions)


def _thread_change_seat(st, name, sid, reason, ts=None, status=None):
    """End the current seat stint and start a fresh one; used by set, reseat, and accepted succession."""
    t=st["threads"][name]; ts=ts or now(); previous=t.get("session_id")
    t.pop("disconnected",None)
    hist=t.setdefault("sessions",[])
    if previous and not any(h.get("session_id")==previous for h in hist):
        hist.append({"session_id":previous,"from":t.get("created")})
    for stint in hist:
        if stint.get("session_id")==previous and not stint.get("to"):
            stint["to"]=ts; stint["reason"]=reason
    hist.append({"session_id":sid,"from":ts})
    t["session_id"]=sid
    _close_archived(st,sid,name,ts)
    t.pop("stuck_on",None); t.pop("waiting_for",None); t.pop("nudges",None)
    t["status"]=status or "starting"; t["last_status_at"]=ts
    return previous,ts


def _ho_open(rec):
    return rec.get("phase") not in ("aborted", "seated", "retired")


SUBAGENT_ID_RE = r"(?i)a[0-9a-f]{8,}|(agent|subagent|task|toolu|reviewer|helper)([ :._-].*|\d*)|general_purpose|toolu\d+[A-Z0-9]+"


def not_a_session(sid, st=None):
    """Why sid cannot be a thread's session (an Agent-tool subagent id or name, not a create_session id), or None.
    A heuristic: real ids (session_..., cse_...) pass; subagent-shaped ids and thread or role names do not."""
    sid = (sid or "").strip()
    names = {"lead", "all", "user", "explore", "plan", "general-purpose", "worker", "explorer"} | {n.lower() for n in ((st or {}).get("threads") or {})}
    if sid and (re.fullmatch(SUBAGENT_ID_RE, sid) or sid.lower() in names):
        what = "is a thread or role name" if sid.lower() in names else "looks like a subagent id or is not a recognised session id"
        return (f"{sid} {what}, not a session id: a thread is a remote session made with create_session (its id "
                "starts with session_). Subagents are helpers inside one session and never hold a seat. If "
                "create_session is not available, stop and tell the user; do not fall back to a subagent")
    return None


def _remotes(st):
    """The repo's remote names (`upstream/x` is as much a remote branch as `origin/x`); none outside git."""
    repo = st.get("repo", {}).get("path")
    if not repo:
        return ()
    try:
        r = subprocess.run(["git", "-C", repo, "remote"], capture_output=True, text=True, timeout=10)
    except (OSError, subprocess.SubprocessError):
        return ()
    return tuple(x for x in r.stdout.split() if x) if r.returncode == 0 else ()


def branch_of(st, name):
    """A thread's branch; a hand-edited ledger without the field falls back to the default name."""
    return st["threads"][name].get("branch") or f"tw/{st['project']}/{name}"


def _branch_problem(st, name, b):
    """Why b cannot be thread `name`'s branch, or None. Shell-safe characters only (the branch goes into printed
    git commands), git's ref rules, never the base, and no clash with another thread's branch: same name in any
    case (macOS refs ignore case) or one inside the other (`x` and `x/y` cannot both exist)."""
    if not b or re.fullmatch(r"[A-Za-z0-9._/+-]+", b) is None:
        return f"--branch {b!r}: use only letters, digits and . _ / + - (it goes into shell commands)"
    parts = b.split("/")
    if b.startswith("-") or b in ("@", "HEAD") or any(not c or c.startswith(".") or c.endswith((".", ".lock"))
                                                       for c in parts) or ".." in b:
        return f"--branch {b!r} is not a valid git branch name"
    base = st.get("repo", {}).get("base") or "main"
    lb, lbase = b.lower(), base.lower()
    ns = f"tw/{st.get('project', '')}".lower()  # the namespace of the default thread branches
    remote = parts[0].lower() in ("origin", "refs", "remotes") or (
        not lb.startswith(ns + "/") and parts[0].lower() in {x.lower() for x in _remotes(st)})
    if lb == lbase or lb.startswith(lbase + "/") or lbase.startswith(lb + "/") or remote:
        return f"--branch {b!r}: a thread works on its own branch, never the base (or one inside it) or a remote one"
    if ns.startswith(lb + "/") or lb == ns:
        return f"--branch {b!r}: holds every thread's default branch ({ns}/<thread>); no new thread could be added"
    if lb.startswith(ns + "/") and lb != f"{ns}/{name}".lower():
        return (f"--branch {b!r}: {ns}/<name> is the default branch of thread <name> (rebuild reads it that way); "
                f"use {ns}/{name} or a name outside {ns}/")
    for n, o in st["threads"].items():
        ob = (o.get("branch") or "").lower()
        if n != name and ob and (ob == lb or ob.startswith(lb + "/") or lb.startswith(ob + "/")):
            return f"--branch {b}: clashes with {n}'s branch {o['branch']}; one branch per thread"
    return None

def cmd_thread(a):
    d = need(find_dir())
    st = load(d)
    name = a.name
    if a.action == "set" and a.kind is not None and a.session is not None:
        sys.exit("thread set accepts only one of --session and --kind at a time")
    if a.action != "add" and not (a.action == "set" and name == "all" and a.roster_sent) and name not in st["threads"]:
        sys.exit(f"unknown thread {name}; known: {', '.join(st['threads']) or '-'}")
    if a.action == "reseat" and any(hid != getattr(a, "handover", None) and x.get("seat") == name and _ho_open(x) for hid, x in st.get("handovers", {}).items()):
        sys.exit(lab(st, "seat_handover_open_hint"))

    if a.session is not None:
        a.session = a.session.strip()
    if getattr(a,"handover",None) is not None:
        missing=_succ_handover_gate(st,a.handover,name,a.session)
        if missing: sys.exit("--handover blocked: "+", ".join(missing))
    if a.session and not_a_session(a.session, {"threads": dict(st["threads"], **{name: {}})}):
        sys.exit(not_a_session(a.session, {"threads": dict(st["threads"], **{name: {}})}))
    if a.action == "add" and a.cloud_reason is not None and (a.kind or "rc") != "cloud":
        sys.exit("--cloud-reason goes with --kind cloud; an rc thread needs no reason")
    if a.action == "add" and (a.kind or "rc") == "cloud" and not (a.cloud_reason or "").strip():
        sys.exit("a cloud thread needs --cloud-reason \"<why>\": rc is the default. Use cloud only when the thread never "
                 "touches the project folder AND never needs to message rc threads (a cloud thread cannot message rc "
                 "sessions, and once its trust card is approved rc sessions, the lead included, can no longer message "
                 "it or read its event log). If rc seats are full, ask "
                 "the user instead of switching to cloud")
    if a.branch is not None:
        a.branch = a.branch.strip()
    if a.action != "add" and a.branch is not None and a.branch == (st["threads"].get(name) or {}).get("branch"):
        a.branch = None  # already its branch: nothing to change
    if a.action == "add" and name in st["threads"]:
        pass  # "taken" below
    elif a.action == "add" or a.branch is not None:
        why = _branch_problem(st, name, a.branch if a.branch is not None else f"tw/{st['project']}/{name}")
        if why:
            sys.exit(why)
    if a.action != "add" and a.branch is not None:
        t0 = st["threads"].get(name) or {}
        if a.action == "set" and t0 and t0.get("worktree") and Path(t0["worktree"]).exists():
            sys.exit(f"--branch: {name}'s worktree {t0['worktree']} already exists on {branch_of(st, name)}; the "
                     "branch is fixed once its worktree is made")
        if a.action != "set" or not t0 or t0.get("session_id") or t0.get("sessions") or t0.get("status") != "planned":
            sys.exit("--branch changes only while the thread is planned and has never had a session (the user editing "
                     "the plan); after that the branch is fixed: leases and trace follow it, so work there would stop "
                     "counting. Add a new thread for a new branch")
        repo, old = st.get("repo", {}).get("path"), branch_of(st, name)
        held = [ref for ref in (f"refs/heads/{old}", f"refs/remotes/origin/{old}") if repo and subprocess.run(
            ["git", "-C", repo, "show-ref", "--verify", "--quiet", ref], capture_output=True).returncode == 0]
        if held:
            sys.exit(f"--branch: {old} already exists in the repo ({', '.join(held)}; its worktree was removed); "
                     f"renaming the thread's branch would orphan that work. Rename the git branch yourself "
                     f"(`git branch -m {old} {a.branch}`, and the pushed copy) and then set it here, or keep it")
    if a.action != "add" and (a.kind is not None or a.cloud_reason is not None):
        t0 = st["threads"].get(name) or {}
        if a.action != "set" or not t0 or t0.get("session_id") or t0.get("sessions") or t0.get("status") != "planned":
            sys.exit("--kind and --cloud-reason change only while the thread is planned and has never had a session "
                     "(the user editing the plan); after that its kind is fixed: add a new thread")
        kind = a.kind or t0["kind"]
        if kind == "cloud" and t0.get("kind") == "rc" and t0.get("worktree") and Path(t0["worktree"]).exists():
            sys.exit(f"cannot change {name} from rc to cloud while its worktree exists: {t0['worktree']}")
        if kind == "cloud" and not (a.cloud_reason or t0.get("cloud_reason") if a.kind is None else a.cloud_reason or "").strip():
            sys.exit("a cloud thread needs --cloud-reason \"<why>\" (see thread add)")
        if kind == "cloud" and a.cloud_reason is not None and not a.cloud_reason.strip():
            sys.exit("a cloud thread needs a non-empty --cloud-reason")
        if kind == "rc" and a.cloud_reason is not None:
            sys.exit("--cloud-reason goes with --kind cloud; an rc thread needs no reason")
        if kind == "rc" and t0.get("kind") == "cloud":
            print(f"{name}: now rc; run `tw.py worktree {name}` before starting its session", file=sys.stderr)
    if a.session and a.action in ("add", "set", "reseat"):
        if a.action in ("set","reseat") and getattr(a,"handover",None) is None and any(
                h.get("seat")==name and _ho_open(h) for h in st.get("handovers",{}).values()):
            sys.exit(lab(st,"seat_handover_open_hint"))
        critical_target = a.action == "add" and bool(a.critical) or a.action == "set" and (bool(a.critical) or bool((st["threads"].get(name) or {}).get("critical"))) or a.action == "reseat" and bool((st["threads"].get(name) or {}).get("critical"))
        if critical_target and _screen_failed(st, a.session):
            sys.exit(lab(st, "critical_screen_block"))
        if a.action == "reseat":
            latest = next((x for x in reversed(list(st.get("screens", {}).values())) if x.get("seat") == name and x.get("session_id") == a.session), None)
            if latest and (st["threads"].get(name) or {}).get("critical") and latest.get("verdict") == "fail":
                sys.exit(lab(st, "critical_screen_block"))
            if latest and latest.get("verdict") != "pass":
                print(lab(st, "screen_gate_warning", seat=name, verdict=_verdict_word(st, latest.get("verdict"))), file=sys.stderr)
        other = _session_taken(st, a.session, name, getattr(a,"handover",None))
        if other:
            sys.exit(f"session {a.session} already holds the {other} seat; one session holds one seat")
        if a.session == (st.get("lead") or {}).get("session_id"):
            sys.exit(f"session {a.session} is the lead; a thread needs its own session")
    if a.action == "add":
        added_status = a.status if a.session else "planned"
        if a.waiting_for and added_status != "waiting":
            sys.exit("--waiting-for requires an added session with --status waiting")
        if a.stuck_on and a.stuck_on != "none" and added_status not in ("working", "waiting"):
            sys.exit("--stuck-on requires an added session with --status working or waiting")
        if not re.fullmatch(NAME_RE, name):
            sys.exit(
                "thread name: lowercase letters/digits/hyphen, max 24 chars (e.g. ui, api, research-2)"
            )
        if name in ("lead", "all") or name in st["threads"]:
            sys.exit(f"thread name {name} is taken")
        a.kind = a.kind or "rc"
        st["threads"][name] = new_thread(
            st, name, a.kind, focus=a.focus or "", owns=csv(a.owns), session_id=a.session,
            status="planned" if not a.session else (a.status or "idle"),
            branch=a.branch or f"tw/{st['project']}/{name}", created=now(), summary=a.summary or "",
            sessions=[{"session_id": a.session, "from": now()}] if a.session else [])
        if a.critical: st["threads"][name]["critical"] = True
        if a.waiting_for is not None: st["threads"][name]["waiting_for"] = a.waiting_for
        if a.stuck_on and a.stuck_on != "none": st["threads"][name]["stuck_on"] = a.stuck_on
        if a.session:
            _close_archived(st, a.session, name, now())
        if a.kind == "cloud":
            st["threads"][name]["cloud_reason"] = a.cloud_reason.strip()
        if a.mode:
            st["threads"][name]["permission_mode"] = a.mode
        if (a.model or "").strip():
            st["threads"][name]["model"] = a.model.strip()
        if a.kind == "rc":
            st["threads"][name]["worktree"] = str(worktree_path(st, name))
        st["threads"][name]["title"] = title_for(st, name)
        bump_roster(st, name)
        save(
            d,
            st,
            {"ev": "thread-add", "thread": name, "kind": a.kind, "session": a.session},
        )
        t = st["threads"][name]
        out = {
            "name": name,
            "title": t["title"],
            "branch": branch_of(st, name),
            "tags": [f"teamwork:{tag(st)}", f"teamwork-thread:{name}"],
            "environment_id": st["envs"].get(a.kind),
            "create_session": session_args(st, name),
        }
        if t.get("worktree"):
            out["worktree"] = t["worktree"]
            out["next"] = f"tw.py worktree {name}  (before create_session)"
        if title_warning(t["title"]):
            out["warning"] = title_warning(t["title"])
        print(json.dumps(out, ensure_ascii=False))
        return
    if a.action == "set" and a.roster_sent and name == "all":
        if any(getattr(a, x, None) for x in ("status", "summary", "owns", "focus", "session", "from_status")):
            sys.exit("`thread set all --roster-sent` takes no other options; set threads one by one")
        for n in roster_stale(st):
            st["threads"][n]["roster_seen"] = st.get("roster_version", 0)
        save(d, st, {"ev": "roster-sent", "to": "all", "version": st.get("roster_version", 0)})
        print(json.dumps({"roster_version": st.get("roster_version", 0), "not_sent": roster_stale(st)}))
        return
    t = st["threads"][name]
    if a.waiting_for and (a.action not in ("set", "add") or (a.status or t.get("status")) != "waiting"):
        sys.exit("--waiting-for applies only to a thread in waiting status")
    if a.stuck_on and a.stuck_on != "none" and (a.action not in ("set", "add") or (a.status or t.get("status")) not in ("working", "waiting")):
        sys.exit("--stuck-on applies only to a working or waiting thread")
    if a.action == "set" and t.get("status") == "archived" and a.status and a.status != "archived" and not a.session:
        sys.exit(f"{name} is archived; restore it through the seat-change path with --session <new session id>")
    if a.kind is not None or a.cloud_reason is not None:  # planned seat, checked above: the user edited the plan
        t["kind"] = a.kind or t["kind"]
        if t["kind"] == "cloud":
            t["cloud_reason"] = (a.cloud_reason if a.cloud_reason is not None else t.get("cloud_reason") or "").strip()
            t.pop("worktree", None)
        else:
            t.pop("cloud_reason", None)
            t["worktree"] = str(worktree_path(st, name))
    roster_before = (t.get("session_id"), t.get("owns"), t["status"] == "archived")
    if a.action == "reseat":
        if not a.session:
            sys.exit("reseat needs --session <new session id> (create the new session first)")
        if a.session == t.get("session_id") and t.get("status") != "archived":
            sys.exit(f"{a.session} already holds the {name} seat")
    reason = a.reason or ("reseated" if a.action == "reseat" else "session changed")
    prev_session = t.get("session_id")
    session_change = bool(a.session and (a.session != t.get("session_id") or t.get("status") == "archived"))
    if session_change:
        if a.status and a.status not in SESSION_CHANGE_STATUSES:
            sys.exit(f"status must be one of {sorted(SESSION_CHANGE_STATUSES)}")
        prev_session,ts=_thread_change_seat(st,name,a.session,reason,status=a.status)
    if a.status and not session_change:
        if a.status not in THREAD_STATUSES:
            sys.exit(f"status must be one of {list(THREAD_STATUSES)}")
        if t.get("status") == "resolved" and a.status in ("starting", "working", "waiting", "review", "landing"):
            print(lab(st, "thread_resolved_active", thread=name, status=a.status), file=sys.stderr)
        t["status"] = a.status
        t.pop("disconnected", None)
    if a.disconnected:
        if a.action != "set":
            sys.exit("--disconnected applies to thread set")
        t["disconnected"] = True
    if getattr(a, "critical", None) is not None:
        if a.action != "set": sys.exit("--critical applies to thread set")
        if a.critical and _screen_failed(st, t.get("session_id")):
            sys.exit(lab(st, "critical_screen_reassign"))
        t["critical"] = a.critical
    if a.waiting_for is not None:
        t["waiting_for"] = a.waiting_for
    if a.status and a.status != "waiting":
        t.pop("waiting_for", None)
    if a.stuck_on is not None:
        if a.stuck_on == "none": t.pop("stuck_on", None)
        else: t["stuck_on"] = a.stuck_on
    if a.status and a.status not in ("working", "waiting"):
        t.pop("stuck_on", None)
    if a.summary is not None:
        t["summary"] = a.summary
    if a.mode:
        t["permission_mode"] = a.mode
    if a.model is not None:
        t["model"] = a.model.strip()  # IL-31; empty = the lead's model
    if a.from_status:
        t.pop("stuck_on", None)
        t["last_status_at"] = now()
        t["last_report_session"] = t.get("session_id")
        t["report_count"] = int(t.get("report_count") or 0) + 1
        t.pop("disconnected", None)
    if a.owns is not None:
        t["owns"] = csv(a.owns)
    if a.focus is not None:
        t["focus"] = a.focus
        t["title"] = title_for(st, name)
    if a.branch is not None and a.branch != t.get("branch"):
        t["branch"] = a.branch
        bump_roster(st)  # the roster and worker prompt name the branch
    if (t.get("session_id"), t.get("owns"), t["status"] == "archived") != roster_before:
        bump_roster(st)  # peers need a new ROSTER; t itself learns it with the same broadcast
    if a.roster_sent:
        t["roster_seen"] = st.get("roster_version", 0)
    if a.action == "reseat" and getattr(a,"handover",None):
        ho=st.get("handovers",{}).get(a.handover)
        if ho:
            ho.update(successor=a.session,phase="seated")
            _succ_save(d,st,ho,"seat")
    t["last_seen"] = now()
    save(
        d,
        st,
        {
            "ev": "thread-reseat" if session_change and prev_session else "thread-set",
            "thread": name,
            "status": t["status"],
            "summary": t["summary"],
            **({"waiting_for": t.get("waiting_for")} if t.get("waiting_for") else {}),
            **({"session": t["session_id"], "prev_session": prev_session, "reason": reason}
               if session_change else {}),
        },
    )
    print(json.dumps({name: t}, ensure_ascii=False, indent=2))
    if session_change:
        print("send the updated ROSTER to the new session before dispatching work", file=sys.stderr)
        print(lab(st, "handover_prompt_hint"), file=sys.stderr)


PATCHY_RE = re.compile(r"又(?:坏|错|出(?:问题|错|bug))|还是没(?:好|修好|解决|用)|补丁|治标|没解决根本|根本没解决|still (?:broken|wrong|failing|not working)", re.I)
URGENT_RE = re.compile(r"先修一下|先修好|先修复|紧急|很急|急修|赶紧修|立刻修|马上修|urgent|asap", re.I)

def urgent_words(text):
    clean=re.sub(r"(?:不太急|不怎么急|不是很急|不急|别急|不用急|不着急|not urgent)", "", text or "", flags=re.I)
    return bool(URGENT_RE.search(clean))

def patchy_text(text):
    value=text or ""
    if PATCHY_RE.search(value): return True
    return any(re.search(r"\bagain\b",part,re.I) and re.search(r"\b(?:broken|fail(?:ed|ing)?|wrong|bug)\b",part,re.I)
               for part in re.split(r"[.!?。！？\n]+",value))

def _norm_category(value):
    if not value: return value
    key=value.strip().lower()
    return {"纠正":"correction","修正":"correction","问题":"bug","缺陷":"bug","bug":"bug"}.get(key,key)

def area_of_task(st, task):
    areas = st.get("areas", {})
    names = {str(x).lower(): x for x in areas}
    for name, rec in areas.items():
        for aka in rec.get("aka", []): names[str(aka).lower()] = name
    for topic in task.get("topics", []):
        if topic.lower() in names: return names[topic.lower()]
    for name, rec in areas.items():
        if any(fnmatch.fnmatch(path, pat) for path in task.get("touches", []) for pat in rec.get("paths", [])):
            return name
    return (task.get("topics") or [None])[0]


def new_area(state="ok", baseline=None, rc=0, implicit=None):
    row = {"paths": [], "aka": [], "state": state, "baseline": now() if baseline is None else baseline,
           "rc": rc, "debt": [], "asked": None, "question": None, "dismissed": [], "history": []}
    if implicit is not None:
        row["implicit"] = implicit
    return row

def _area_records(st, task_areas=None):
    areas = st.get("areas", {})
    out = dict(areas)
    for k, task in st.get("tasks", {}).items():
        name = (task_areas or {}).get(k) if task_areas is not None else area_of_task(st, task)
        if name and name not in out:
            out[name] = {"paths": [], "aka": [], "state": "ok", "baseline": "", "rc": 0,
                         "debt": [], "asked": None, "question": None, "dismissed": [], "history": [], "implicit": True}
    for rid, q in st.get("requests", {}).items():
        name = q.get("area")
        if name and name not in out:
            out[name] = {"paths": [], "aka": [], "state": "ok", "baseline": "", "rc": 0,
                         "debt": [], "asked": None, "question": None, "dismissed": [], "history": [], "implicit": True}
    return out

def _area_reqs(st, area, rec):
    aliases = {area, *rec.get("aka", [])}
    return [(rid, q) for rid, q in st.get("requests", {}).items()
            if (q.get("area") == area if q.get("area") else
                any(x and x.lower() == (q.get("where") or "").lower() for x in aliases))]

def radar(st):
    if pref(st, "root_mode") == "off": return {}
    result = {}
    task_areas={tid:area_of_task(st,task) for tid,task in st.get("tasks",{}).items()}
    tasks_by_area={}
    for tid,task in st.get("tasks",{}).items():
        if task_areas[tid]: tasks_by_area.setdefault(task_areas[tid],[]).append(task)
    records = _area_records(st,task_areas)
    if records:
        areas = st["areas"]
        if not st.get("root_since"):
            st["root_since"] = now()
        for area, rec in records.items():
            if area not in areas:
                rec = dict(rec); rec["baseline"] = now(); rec["implicit"] = True
                areas[area] = rec
        records = areas
    for area, rec in records.items():
        baseline = rec.get("baseline") or ""
        dismissed = set(rec.get("dismissed", []))
        symptoms = [rid for rid, q in _area_reqs(st, area, rec)
                    if rid not in dismissed and q.get("status") not in REQ_END + ("wont",)
                    and (q.get("created") or "") >= baseline
                    and (q.get("category") in ("bug", "correction") or q.get("patchy"))]
        tasks = tasks_by_area.get(area, [])
        rework = sum(sum((x or "") >= baseline for x in t.get("rework_at", [])) for t in tasks)
        patchy = any(st.get("requests", {}).get(r, {}).get("patchy") for r in symptoms)
        pending = rec.get("state", "ok") in ("ok", "pending") and (len(symptoms) >= pref(st, "root_symptoms_at")
                   or rework >= pref(st, "root_rework_at") or patchy)
        debt_since = rec.get("answered_at") or rec.get("asked") or ""
        patched_debt = sum(x.get("kind") in ("hotfix", "patch") and x.get("at", "") > debt_since for x in rec.get("debt", []))
        reraised = rec.get("reraised") or (rec.get("state") == "patched" and rec.get("asked") and patched_debt >= pref(st, "root_debt_at"))
        pending = pending or reraised
        result[area] = {"symptoms": symptoms, "rework": rework, "patchy": patchy,
                        "state": "pending" if pending else ("ok" if rec.get("state") == "pending" else rec.get("state", "ok")),
                        "level": "full" if rec.get("level") == "full" or len(symptoms) >= pref(st, "root_full_at") else "light"}
    return result

def _radar_update(st):
    if pref(st, 'root_mode') == "off": return
    entered=[]
    for area, data in radar(st).items():
        old = st.get("areas", {}).get(area, {}).get("state", "ok")
        if data["state"] == "pending" and old in ("ok", "patched"):
            st["areas"].setdefault(area, new_area(implicit=area not in st.get("areas", {})))["state"] = "pending"
            entered.append(area)
            if old == "patched":
                st["areas"][area]["reraised"] = True
                st.setdefault("_root_reraised", []).append(area)
        elif old == "pending" and data["state"] != "pending" and not st.get("areas", {}).get(area, {}).get("reraised"):
            st["areas"][area]["state"] = "ok"
    if entered: st.setdefault("_root_pending", []).extend(entered)

def cmd_area(a):
    d = need(find_dir()); st = load(d); areas = st["areas"]
    if a.action == "list":
        print(json.dumps(areas, ensure_ascii=False, indent=2)); return
    name = norm_topics(a.name)
    if not name: sys.exit(lab(st,"root_area_required"))
    name = name[0]
    if a.action == "merge":
        src, dst = a.name, a.to
        if src not in areas or dst not in areas: sys.exit(lab(st,"root_area_unknown"))
        for rid, q in st.get("requests", {}).items():
            if q.get("area") == src: q["area"] = dst
            if (q.get("where") or "").lower() == src.lower(): q["area"] = dst
        areas[dst]["paths"] = list(dict.fromkeys((areas[dst].get("paths") or []) + (areas[src].get("paths") or [])))
        areas[dst]["aka"] = list(dict.fromkeys((areas[dst].get("aka") or []) + [src] + (areas[src].get("aka") or [])))
        areas[dst].setdefault("history", []).append({"kind":"merge", "from":src, "at":now(), "debt":areas[src].get("debt",[])})
        areas[dst].setdefault("debt", []).extend(areas[src].get("debt", []))
        areas.pop(src); save(d, st, {"ev":"area-merge", "from":src, "to":dst}); return
    rec = areas.setdefault(name, new_area())
    rec.pop("implicit",None)
    st.setdefault("root_since", now())
    if a.paths is not None: rec["paths"] = csv(a.paths)
    if a.aka is not None: rec["aka"] = csv(a.aka)
    save(d, st, {"ev":"area-"+a.action, "area":name})

def _root_path(d, area, rc): return d / "roots" / f"{area}-RC{rc}.md"

ROOT_ROUND_FIELDS = ("asked", "question", "checked_at", "answer", "user_said", "level", "spec_checked_at",
                     "root_pending", "defaulted_at", "patch_first", "reraised", "answered_at")

def _archive_root_round(rec, kind):
    old = {k: rec.pop(k) for k in ROOT_ROUND_FIELDS if k in rec}
    if old:
        rec.setdefault("history", []).append({"kind": kind, "at": now(), **old})

def _withdraw_root_questions(st, area):
    for q in st.get("questions", []):
        if q.get("kind") != "root" or q.get("answered"): continue
        qareas = q.get("areas") or [q.get("area")]
        if area not in qareas: continue
        answers = q.setdefault("area_answers", {})
        answers.setdefault(area, "withdrawn")
        if all(x in answers for x in qareas if x):
            q.update(withdrawn=True, answered=True, answer="withdrawn")

def _root_corrections(st, area, rec):
    corr=[]
    baseline=rec.get("baseline") or ""
    for rid,q in _area_reqs(st,area,rec):
        if (q.get("created") or "") < baseline: continue
        corr.append((rid,q.get("text","")))
        said=q.get("user_said",[])
        if isinstance(said,list): corr.extend((rid,x.get("text","") if isinstance(x,dict) else str(x)) for x in said if x)
    return [(rid,str(original).replace("|",r"\|").replace("\r"," ").replace("\n"," ")) for rid,original in corr]

def _unmapped_root_corrections(text, st, area, rec):
    mapped=set()
    for line in text.splitlines():
        cols=_md_table_cols(line)
        if len(cols)>=5 and re.fullmatch(r"C\d+",cols[0]): mapped.add((cols[1],cols[2]))
    return [(rid,original) for rid,original in _root_corrections(st,area,rec)
            if (rid,original.replace(r"\|","|")) not in mapped]

def _area_key(st, value):
    norm = norm_topics(value)
    key = norm[0] if norm else ""
    for name, rec in st.get("areas", {}).items():
        if key == name.lower() or key in {str(x).lower() for x in rec.get("aka", [])}:
            return name
    return key

def _root_blank(st):
    return lab(st, "root_blank")

def _root_placeholder(value):
    normalized = str(value).strip().lower().translate(str.maketrans({"＜": "<", "＞": ">"}))
    return normalized in {"", "-", "x", "无", "none", "n/a", "na", "tbd", "待定", "todo", "<填>", "<fill>"}

def _root_found_placeholder(text):
    match = re.search(r"<填>|<fill>|＜填＞|＜fill＞", text, flags=re.IGNORECASE)
    return match.group(0) if match else None

def _root_sections(text, headings):
    matches = list(re.finditer(r"(?m)^##\s+([^\n]+)\s*$", text))
    found = []
    for i, match in enumerate(matches):
        if match.group(1).strip() not in headings: continue
        end = matches[i + 1].start() if i + 1 < len(matches) else len(text)
        found.append(text[match.end():end])
    return found

def _root_scenario_check(body, ids):
    headings = ("故障场景与测试", "故障场景全表", "Failure scenarios and tests", "All failure scenarios")
    sections = _root_sections(body, headings)
    if not sections: return "root_scenario_missing"
    data = []
    for scenarios in sections:
        section_data = []
        for line in scenarios.splitlines():
            if not line.strip().startswith("|"): continue
            cols = _md_table_cols(line)
            if len(cols) > 1 and re.fullmatch(r"S\d+", cols[1]): section_data.append(cols)
        if not section_data: return "root_scenario_empty"
        data.extend(section_data)
    for i in range(1, len(ids) + 1):
        if not any(row[1] == f"S{i}" for row in data): return ("root_scenario_symptom_missing", f"S{i}")
    for row in data:
        if len(row) < 4: return "root_scenario_columns"
        if _root_placeholder(row[3]): return "root_scenario_test_missing"
    return None

def _md_table_cols(line):
    return [x.replace(r"\|", "|").strip() for x in re.split(r"(?<!\\)\|", line.strip().strip("|"))]

def cmd_root(a):
    d = need(find_dir()); st = load(d); areas = st["areas"]
    view = radar(st)
    if a.action == "scan":
        print("\n".join(lab(st,"root_scan_line",area=x,n=len(v['symptoms'])) for x,v in view.items() if v["state"] == "pending") or "-" ); return
    if a.action in ("list", "show"):
        names = [a.area] if a.action == "show" else [x for x,v in view.items() if a.all_areas or v["state"] != "ok"]
        for area in names:
            rec = areas.get(area, {"state":"ok", "debt":[]}); v=view.get(area, {"state":rec.get("state","ok"),"symptoms":[],"rework":0})
            print(lab(st,"root_list_line",area=area,implicit=' '+lab(st,'root_implicit') if rec.get('implicit') else '',state=lab(st,'root_'+v['state']),symptoms=len(v['symptoms']),rework=v['rework'],debt=len(rec.get('debt',[])),next=root_next(v['state'],area,st)))
            if a.action == "show":
                for rid in v["symptoms"]: print(f"  {rid} [{st['requests'][rid].get('category','')}] {st['requests'][rid].get('text','')}")
                for tid,task in st.get("tasks",{}).items():
                    if area_of_task(st,task)==area and task.get("rework_at"): print(f"  {tid} {lab(st,'root_s_rework')}={len(task['rework_at'])}")
                for issue in st.get("issues",[]):
                    text=" ".join(str(issue.get(k,"")) for k in ("title","text","note"))
                    if any(alias.lower() in text.lower() for alias in [area,*rec.get("aka",[])]): print(f"  issue {issue.get('id','')}: {text}")
                for rid,q in _area_reqs(st,area,rec):
                    for said in q.get("user_said",[]) if isinstance(q.get("user_said"),list) else []:
                        print(f"  {rid} user: {said.get('text','') if isinstance(said,dict) else said}")
        return
    if a.action == "ask" and getattr(a,"all_areas",False):
        if not all((a.recommend,a.why,a.cost,a.root)): sys.exit(lab(st,"root_ask_args"))
        eligible=[]
        for n,r in areas.items():
            path=_root_path(d,n,r.get("rc",0)); body=path.read_text(encoding="utf-8") if path.exists() else ""
            debt=sum(x.get("kind") in ("hotfix","patch") and x.get("at","") > (r.get("answered_at") or r.get("asked") or "") for x in r.get("debt",[]))
            if r.get("state") not in ("reviewing","patched","pending") or not r.get("checked_at") or "<填>" in body or "<fill>" in body or (r.get("asked") and debt < pref(st, 'root_debt_at')):
                print(lab(st,"root_ask_skip",area=n),file=sys.stderr); continue
            eligible.append(n)
        if not eligible: sys.exit(lab(st,"root_ask_none"))
        texts=[]
        for n in eligible:
            texts.append(lab(st,"root_question",area=n,n=len(view.get(n,{}).get("symptoms",[])),root=a.root or "<fill>",
                             cost=a.cost or "<fill>",rec=a.recommend or "A",why=a.why or "<fill>"))
            areas[n].update(asked=now(),question=len(st.get("questions",[]))+1,state="asked")
        body="\n".join(texts)
        st["questions"].append({"from":"lead","text":body,"t":now(),"answered":False,"kind":"root","areas":eligible})
        save(d,st,{"ev":"root-ask-all","areas":eligible}); print(body); return
    area = _area_key(st, a.area) if a.action not in ("move",) else a.area
    if a.action not in ("move","fresh") and area not in areas:
        if area not in view: sys.exit(lab(st,"root_unknown_area"))
        areas[area] = new_area(baseline=st.get("created") or "", implicit=True)
    rec = areas.get(area,{})
    if a.action == "start":
        if rec.get("state") == "reviewing" and rec.get("rc",0) and _root_path(d,area,rec["rc"]).exists():
            sys.exit(lab(st,"root_started"))
        if rec.get("state") not in ("ok", "pending"):
            shown_state=lab(st,"root_"+rec.get('state','ok'))
            sys.exit(lab(st,"root_start_refused",state=shown_state,next=root_next(rec.get("state"),area,st)))
        rc=rec.get("rc",0)+1; path=_root_path(d,area,rc); path.parent.mkdir(parents=True,exist_ok=True)
        if path.exists(): sys.exit(lab(st,"root_started"))
        _archive_root_round(rec, "next-round")
        _withdraw_root_questions(st, area)
        rec["rc"]=rc; rec["state"]="reviewing"; rec["checked_at"]=None; rec["reraised"]=False
        v=view.get(area,{}); ids=v.get("symptoms",[]); level=v.get("level","light")
        rec["level"]=level
        rows="\n".join(f"| S{i} | {rid} | {st['requests'][rid].get('text','').replace('|',r'\\|').replace(chr(10),' ')} |" for i,rid in enumerate(ids,1)) or "| S1 | - | <填> |"
        fields=["root_symptoms_col", "root_root_heading", "root_invariant_heading", "root_scenario_heading", "root_solution_heading"] if level=="light" else ["root_symptoms_col", "root_root_heading", "root_code_heading", "root_reference_heading", "root_guarantee_heading", "root_full_scenario_heading", "root_scenario_state_heading", "root_plan_heading", "root_compat_heading"]
        symptom_heading=lab(st,"root_symptoms_col"); scenario_heading=lab(st,"root_scenario_heading" if level=="light" else "root_full_scenario_heading")
        symptom_header=" | ".join(lab(st,key) for key in ("root_symptom_id_col", "root_symptom_source_col", "root_symptom_words_col"))
        body=f"# {area} RC{rec['rc']}\n\n{lab(st,'root_level')}: {level}\n\n## {symptom_heading}\n{symptom_header}\n---|---|---\n{rows}\n"
        for field in fields[1:]:
            heading=lab(st,field)
            if field in ("root_scenario_heading","root_full_scenario_heading"):
                blank=_root_blank(st)
                body += f"\n## {heading}\n\n| {lab(st,'root_scenario_col')} | {lab(st,'root_scenario_symptom')} | {lab(st,'root_scenario_current')} | {lab(st,'root_scenario_test')} |\n|---|---|---|---|\n"
                body += "\n".join(f"| {blank} | S{i} | {blank} | {blank} |" for i in range(1,len(ids)+1)) or f"| {blank} | {lab(st,'root_extra')} | {blank} | {blank} |"
            else:
                body += f"\n## {heading}\n\n" + _root_blank(st) + "\n"
        path.write_text(body,encoding="utf-8"); save(d,st,{"ev":"root-start","area":area}); print(path); return
    if a.action == "check":
        path=_root_path(d,area,rec.get("rc",0)); body=path.read_text(encoding="utf-8") if path.exists() else ""
        if rec.get("rc",0) < 1 or not path.exists() or not (rec.get("state") == "reviewing" or (rec.get("state")=="rooting" and rec.get("level")=="full")): sys.exit(lab(st,"root_check_active"))
        fill = _root_found_placeholder(body)
        if fill: sys.exit(lab(st,"root_check_fill",fill=fill))
        ids=view.get(area,{}).get("symptoms",[])
        error=_root_scenario_check(body,ids)
        if error:
            if isinstance(error,tuple): sys.exit(lab(st,error[0],symptom=error[1]))
            sys.exit(lab(st,error))
        rec["checked_at"]=now(); save(d,st,{"ev":"root-check","area":area}); return
    if a.action == "ask":
        path=_root_path(d,area,rec.get("rc",0)); body=path.read_text(encoding="utf-8") if path.exists() else ""
        if not all((a.recommend,a.why,a.cost,a.root)): sys.exit(lab(st,"root_ask_args"))
        if rec.get("state") not in ("reviewing", "patched", "pending"): sys.exit(lab(st,"root_ask_state"))
        if not rec.get("checked_at") or _root_found_placeholder(body): sys.exit(lab(st,"root_check_before_ask"))
        if rec.get("asked") and sum(x.get("kind") in ("hotfix", "patch") and x.get("at","") > (rec.get("answered_at") or rec["asked"]) for x in rec.get("debt",[])) < pref(st, 'root_debt_at'): sys.exit(lab(st,"root_already_asked"))
        n=len(view.get(area,{}).get("symptoms",[])); text=lab(st,"root_question",area=area,n=n,root=a.root,cost=a.cost,rec=a.recommend,why=a.why)
        if rec.get("question") and isinstance(rec["question"],int) and 1 <= rec["question"] <= len(st.get("questions",[])):
            previous=st["questions"][rec["question"]-1]
            if not previous.get("answered"):
                previous.update(answered=True,answer="superseded",superseded_by=len(st["questions"])+1,by_default=True)
        st["questions"].append({"from":"lead","text":text,"t":now(),"answered":False,"kind":"root","area":area})
        rec.update(state="asked",asked=now(),question=len(st["questions"]),reraised=False); save(d,st,{"ev":"root-ask","area":area}); print(text); return
    if a.action == "answer":
        if a.choice not in ("A", "B", "C"): sys.exit(lab(st,"root_answer_choice"))
        if not (a.user_said or "").strip(): sys.exit(lab(st,"root_answer_user_said"))
        if not rec.get("question"): sys.exit(lab(st,"root_answer_question"))
        if rec.get("state") not in ("asked", "patched", "pending") and not rec.get("root_pending"):
            sys.exit(lab(st,"root_answer_state"))
        qn=rec["question"]
        if not isinstance(qn,int) or not 1 <= qn <= len(st.get("questions",[])): sys.exit(lab(st,"root_answer_missing"))
        q=st["questions"][qn-1]
        qareas=q.get("areas") or [q.get("area")]
        answers=q.setdefault("area_answers",{})
        if q.get("kind")!="root" or area not in qareas or area in answers: sys.exit(lab(st,"root_answer_mismatch"))
        answers[area]=a.user_said
        if set(answers) >= set(x for x in qareas if x): q.update(answered=True,answer=a.user_said)
        for older in st.get("questions",[]):
            if older is q: continue
            if older.get("kind")=="root" and area in (older.get("areas") or [older.get("area")]) and not older.get("answered"):
                older.update(answered=True,answer="superseded",superseded_by=qn,by_default=True)
        rec.update(answer=a.choice,user_said=a.user_said,answered_at=now())
        rec.pop("root_pending",None)
        rec["state"]="patched" if a.choice=="B" else "rooting"
        if a.choice=="A":
            rec["level"]="full"
            rcpath=_root_path(d,area,rec.get("rc",0)); oldbody=rcpath.read_text(encoding="utf-8") if rcpath.exists() else ""
            lights=[f"{LABELS[x]['root_level']}: light" for x in ("en","zh")]
            if any(x in oldbody for x in lights):
                existing={line[3:] for line in oldbody.splitlines() if line.startswith("## ")}
                extras=["root_code_heading","root_reference_heading","root_scenario_state_heading","root_compat_heading"]
                blank=_root_blank(st)
                for key in extras:
                    heading=lab(st,key)
                    if heading not in existing: oldbody += f"\n## {heading}\n\n{blank}\n"
                for x in lights: oldbody=oldbody.replace(x,f"{lab(st,'root_level')}: full",1)
                rcpath.write_text(oldbody,encoding="utf-8")
                rec["checked_at"]=None
        if a.choice=="C": rec["patch_first"]=True
        if a.choice=="B": rec.setdefault("debt",[]).append({"kind":"choice-B","at":now()})
        save(d,st,{"ev":"root-answer","area":area,"choice":a.choice}); return
    if a.action == "dismiss":
        if not (a.why or "").strip(): sys.exit(lab(st,"root_dismiss_why"))
        if a.req:
            rec.setdefault("dismissed",[]).append(a.req)
        else:
            _withdraw_root_questions(st, area)
            _archive_root_round(rec,"dismissed")
            rec.update(state="ok",baseline=now(),reraised=False); rec.setdefault("history",[]).append({"kind":"dismissed","why":a.why,"at":now()})
        save(d,st,{"ev":"root-dismiss","area":area}); return
    if a.action == "move":
        rid=area
        if rid not in st.get("requests",{}) or not a.move_area: sys.exit(lab(st,"root_move_usage"))
        st["requests"][rid]["area"]=_area_key(st,a.move_area); save(d,st,{"ev":"root-move","req":rid,"area":st["requests"][rid]["area"]}); return
    if a.action == "done":
        task=st.get("tasks",{}).get(a.task)
        if rec.get("state")!="rooting" or not task or area_of_task(st,task)!=area or task.get("fix_kind")!="root" or task.get("status")!="done" or not (task.get("merged_sha") or task.get("merged_at")): sys.exit(lab(st,"root_done_gate"))
        _withdraw_root_questions(st, area); _archive_root_round(rec,"done")
        rec.setdefault("history",[]).append({"kind":"done","debt":rec.get("debt",[]),"rc":rec.get("rc"),"at":now()}); rec.update(state="ok",baseline=now(),debt=[],reraised=False)
        save(d,st,{"ev":"root-done","area":area,"task":a.task}); return
    if a.action == "handoff":
        task=st.get("tasks",{}).get(a.task or "")
        if rec.get("state")!="rooting" or not rec.get("spec_checked_at") or rec.get("root_pending"):
            sys.exit(lab(st,"root_handoff_gate"))
        specpath=_root_path(d,area,rec.get("rc",0)); specpath=specpath.with_name(specpath.stem+"-spec.md")
        specbody=specpath.read_text(encoding="utf-8") if specpath.exists() else ""
        missing=_unmapped_root_corrections(specbody,st,area,rec)
        if missing: sys.exit(lab(st,"root_unmapped",items=", ".join(f"{rid}: {original}" for rid,original in missing)))
        if not task or area_of_task(st,task)!=area or not a.to or a.to not in st.get("threads",{}): sys.exit(lab(st,"root_handoff_args"))
        task["fix_kind"]="root"; task["root_spec"]=str(_root_path(d,area,rec.get("rc",0)).with_name(_root_path(d,area,rec.get("rc",0)).stem+"-spec.md"))
        save(d,st,{"ev":"root-handoff","area":area,"task":a.task})
        ns=argparse.Namespace(thread=a.to,prompt=True,leaving=None,reason=None); capture=io.StringIO()
        with contextlib.redirect_stdout(capture): cmd_handover(ns)
        spec_body=Path(task["root_spec"]).read_text(encoding="utf-8")
        print(capture.getvalue().rstrip()+f"\n\n{lab(st,'root_spec_header',path=task['root_spec'])}\n\n{spec_body}")
        return
    if a.action == "fresh":
        thread=a.area
        linked=[(tid,t) for tid,t in st.get("tasks",{}).items() if t.get("owner")==thread and t.get("status") not in ("done","dropped")]
        specs=[]
        for tid,t in linked:
            ar=area_of_task(st,t)
            arec=st.get("areas",{}).get(ar,{})
            if ar and arec.get("state")=="rooting":
                if not arec.get("spec_checked_at"): sys.exit(lab(st,"root_fresh_check",area=ar))
                path=_root_path(d,ar,arec.get("rc",0)).with_name(_root_path(d,ar,arec.get("rc",0)).stem+"-spec.md")
                if not path.exists(): sys.exit(lab(st,"root_fresh_spec",area=ar))
                specs.append((str(path),path.read_text(encoding="utf-8")))
        capture=io.StringIO()
        with contextlib.redirect_stdout(capture): cmd_handover(argparse.Namespace(thread=thread,prompt=True,leaving=None,reason=None))
        print(capture.getvalue().rstrip()+("\n\n"+lab(st,"root_specs_header")+"\n"+"\n\n".join(f"{path}\n{body}" for path,body in specs) if specs else "")); return
    if a.action == "spec":
        path=_root_path(d,area,rec.get("rc",0)); spec=path.with_name(path.stem+"-spec.md")
        if a.check:
            text=spec.read_text(encoding="utf-8") if spec.exists() else ""; bad=[]
            spec_sections = _root_sections(text, ("规格", "Specification"))
            correction_sections = _root_sections(text, ("用户纠正映射", "User correction mapping"))
            if not spec.exists() or not spec_sections or not correction_sections: sys.exit(lab(st,"root_spec_sections"))
            spec_lines=set()
            for specbody in spec_sections:
                marker=_root_found_placeholder(specbody)
                if marker: sys.exit(lab(st,"root_spec_fill",fill=marker))
                lines=set(re.findall(r"(?m)^\s*(L\d+)\s*[.:]\s*(\S.*)$",specbody))
                if not any(not _root_placeholder(value) for _,value in lines): sys.exit(lab(st,"root_spec_line"))
                spec_lines.update((key,value) for key,value in lines if not _root_placeholder(value))
            found=set(); mapped_corrections=set()
            for line in text.splitlines():
                cols=_md_table_cols(line)
                if cols and re.fullmatch(r"C\d+",cols[0]) and len(cols)<5:
                    bad.append(cols[0]); continue
                if len(cols)>=5 and re.fullmatch(r"C\d+",cols[0]):
                    found.add(cols[0])
                    mapped_corrections.add((cols[1],cols[2]))
                    mapped=re.search(r"\b(L\d+)\b",cols[3])
                    reason=re.match(r"^(?:用户|User)[:：:]\s*(\S.*)$",cols[4])
                    has_line=bool(mapped and any(x[0]==mapped.group(1) for x in spec_lines))
                    has_reason=bool(reason and not _root_placeholder(reason.group(1)))
                    if not (has_line or has_reason): bad.append(cols[0])
            missing=set(rec.get("spec_rows",[]))-found
            bad.extend(sorted(missing))
            unmapped=_unmapped_root_corrections(text,st,area,rec)
            if bad or unmapped:
                detail=[f"{rid}: {original}" for rid,original in unmapped]
                sys.exit(lab(st,"root_spec_unmapped",items=", ".join(bad+detail)))
            rec["spec_checked_at"]=now(); save(d,st,{"ev":"root-spec-check","area":area}); return
        if a.append:
            if not spec.exists(): sys.exit(lab(st,"root_spec_append"))
            text=spec.read_text(encoding="utf-8"); known=set()
            for line in text.splitlines():
                cols=_md_table_cols(line)
                if len(cols)>=5 and re.fullmatch(r"C\d+",cols[0]): known.add((cols[1],cols[2]))
            additions=[(rid,original) for rid,original in _root_corrections(st,area,rec) if (rid,original) not in known]
            if not additions: sys.exit(lab(st,"root_spec_no_new"))
            nums=[int(m.group(1)) for m in re.finditer(r"(?m)^\|\s*C(\d+)\s*\|",text)]
            start=max(nums,default=0)+1
            blank=_root_blank(st)
            rows="\n".join(f"| C{i} | {rid} | {original} | {blank} | {blank} |" for i,(rid,original) in enumerate(additions,start))
            marker="|---|---|---|---|---|"
            if marker not in text: sys.exit(lab(st,"root_spec_no_table"))
            text=text.replace(marker,marker+"\n"+rows,1); spec.write_text(text,encoding="utf-8")
            rec["spec_rows"]=[f"C{i}" for i in range(1,max(nums,default=0)+len(additions)+1)]
            rec.pop("spec_checked_at",None); save(d,st,{"ev":"root-spec-append","area":area}); print(spec); return
        if not rec.get("checked_at"): sys.exit(lab(st,"root_spec_check_first"))
        if spec.exists(): sys.exit(lab(st,"root_spec_exists"))
        rc=path.read_text(encoding="utf-8") if path.exists() else ""
        corr=_root_corrections(st,area,rec)
        rec["spec_rows"]=[f"C{i}" for i in range(1,len(corr)+1)]
        blank=_root_blank(st)
        rows="\n".join(f"| C{i} | {rid} | {original} | {blank} | {blank} |" for i,(rid,original) in enumerate(corr,1))
        if not rec.get("checked_at"): sys.exit(lab(st,"root_spec_check_first"))
        summary=lab(st,"root_retro_heading"); spec_heading=lab(st,"root_spec_heading"); corr_heading=lab(st,"root_correction_heading")
        headers=" | ".join(lab(st,k) for k in ("root_spec_col_no","root_spec_col_req","root_spec_col_original","root_spec_col_line","root_spec_col_reason"))
        spec.write_text(f"## {summary}\n\n"+"\n".join(x for x in rc.splitlines() if x.startswith("## ") or (x.strip() and x not in ("<填>","<fill>")))+f"\n\n## {spec_heading}\n\nL1. {blank}\n\n## {corr_heading}\n\n| {headers} |\n|---|---|---|---|---|\n"+rows+"\n",encoding="utf-8")
        save(d,st,{"ev":"root-spec","area":area}); print(spec); return

def root_next(state, area, st=None):
    key={"pending":"root_next_pending","reviewing":"root_next_reviewing","asked":"root_next_asked",
         "rooting":"root_next_rooting","patched":"root_next_patched"}.get(state,"root_next_unknown")
    if st is None:
        d=find_dir(); st=load(d) if d else {"prefs":{"language":"en"}}
    return lab(st,key,area=area)

def task_verify(d, st, a):
    """`task verify`: record a primary-outcome check on the real artifact (R71)."""
    if a.id not in st["tasks"]: sys.exit(f"unknown task {a.id}")
    k = st["tasks"][a.id]
    before = json.loads(json.dumps(k))
    changes = {"verify": True}
    if sum(bool(x) for x in (a.seen, a.not_seen, a.pending_real)) != 1:
        sys.exit(lab(st, "pv_one"))
    result = "seen" if a.seen else "not-seen" if a.not_seen else "pending-real"
    if not (a.how or "").strip() or not (a.evidence or "").strip():
        sys.exit(lab(st, "pv_how"))
    if result == "pending-real" and not (a.why or "").strip():
        sys.exit(lab(st, "pv_why"))
    if a.sha and not re.fullmatch(r"[0-9a-fA-F]{7,40}", a.sha.strip()):
        sys.exit(lab(st, "pv_sha"))
    if not k.get("primary"):
        sys.exit(lab(st, "primary_verify_no_primary", task=a.id))
    if k.get("status") == "done":
        sys.exit(lab(st, "primary_verify_done", task=a.id))
    if not _primary_evidence_specific(d, a.evidence):
        sys.exit(lab(st, "primary_evidence_weak"))
    invalidate(k, ["verify"], st)
    check = {"result": result, "how": a.how.strip(), "evidence": a.evidence.strip(), "sha": a.sha,
             "by": getattr(a, "by", None) or "lead", "at": now()}
    if getattr(a, "test", None): check["test"] = a.test.strip()
    if a.why: check["why"] = a.why.strip()
    k["primary_check"] = check
    if _primary_suspect(d, a.how, a.evidence):
        k["primary_suspect"] = True
        print(lab(st, "primary_suspect_warning"), file=sys.stderr)
    else:
        k.pop("primary_suspect", None)
    if result == "not-seen" and k.get("status") == "review":
        return_to_working(k, "primary outcome not seen", st)
        k["primary_check"] = check
        changes["status_to"] = "working"
    check_task_invariants(st, a.id, before, k, a, (getattr(a, "user_said", None) or "").strip(), changes)
    save(d, st, {"ev": "task-primary-verify", "task": a.id, "result": result})
    return


def cmd_task(a):
    d = need(find_dir())
    st = load(d)
    if a.action == "reviews":
        if a.id != "-" and a.id not in st["tasks"]:
            sys.exit(f"unknown task {a.id}")
        print(render_reviews(st, None if a.id == "-" else a.id))
        return
    if a.id == "-":
        sys.exit(f"task {a.action} needs a task id")
    if a.action == "verify":
        return task_verify(d, st, a)
    if a.action == "followups":
        return task_followups(d, st, a)
    if getattr(a, "urgent_minutes", None) is not None and a.urgent_minutes < 1:
        sys.exit("--urgent-minutes: positive whole minutes")
    if a.action == "add":
        if not re.fullmatch(r"[A-Za-z0-9][A-Za-z0-9._-]*", a.id) or ".." in a.id:
            sys.exit(f"bad task id {a.id!r}: use letters, digits, '.', '_' or '-' (e.g. T12)")
        if a.id in st["tasks"]:
            sys.exit(f"task {a.id} exists")
        if a.owner and a.owner not in st["threads"]:
            sys.exit(f"unknown owner {a.owner} (add the thread first)")
        if getattr(a, "primary", None) and not _primary_text_valid(a.primary):
            sys.exit(lab(st, "primary_weak"))
        if getattr(a, "req", None):
            q = st.get("requests", {}).get(a.req)
            if not q: sys.exit(f"unknown request {a.req}")
            if q.get("kind", "request") != "request": sys.exit(lab(st, "req_not_request"))
            q.setdefault("tasks", []).append(a.id)
        said = (getattr(a, "user_said", None) or (q.get("text", "") if getattr(a, "req", None) else "")).strip()
        check_never_raise(d, " ".join(x for x in (a.title or a.id, said, getattr(a, "brief", None), a.accept, getattr(a, "beyond", None) or "") if x),
                          getattr(a, "override", None))
        st["tasks"][a.id] = {
            "title": a.title or a.id,
            **({"brief": a.brief} if getattr(a, "brief", None) else {}),
            **({"kind": a.work_kind} if getattr(a, "work_kind", None) else {}),
            **({"primary": a.primary.strip()} if getattr(a, "primary", None) else {}),
            **({"user_said": said} if said else {}),
            "owner": a.owner,
            "deps": csv(a.deps),
            "accept": a.accept or "",
            "touches": check_touches(a.touches, st.get("repo", {}).get("path")),
            "topics": norm_topics(a.topics),
            **({"model": a.model.strip()} if (a.model or "").strip() else {}),
            **({"route": a.route} if a.route else {}),
            **({"no_scripts": True} if a.no_scripts else {}),
            **({"beyond": a.beyond, "needs_ask": True} if getattr(a, "beyond", None) else {}),
            "status": "approved" if st["plan_approved"] else "planned",
            "notes": "",
            "created": now(),
            **({"urgent": True, "urgent_minutes": a.urgent_minutes if a.urgent_minutes is not None else pref(st, 'urgent_ack_minutes')}
               if getattr(a, "urgent", False) or getattr(a, "urgent_minutes", None) is not None else {}),
        }
        area = area_of_task(st, st["tasks"][a.id])
        task_dir = d / "tasks"; task_dir.mkdir(exist_ok=True)
        (task_dir / f"{a.id}.md").write_text(f"# {a.id}\n\nGoal: {a.title or a.id}\n" + (f"Brief: {a.brief}\n" if getattr(a, "brief", None) else "") + f"Done when: {a.accept or '-'}\n" + (f"\n{lab(st, 'original_words')}: {said}\n" if said else ""), encoding="utf-8")
        beyond_text = None
        if getattr(a, "beyond", None):
            beyond_text = lab(st, "beyond_task", task=a.id, text=a.beyond)
            st["questions"].append({"from": "lead", "text": beyond_text, "kind": "beyond", "task": a.id,
                                    "answered": False, "t": now()})
        save(d, st, {"ev": "task-add", "task": a.id, "owner": a.owner})
        if getattr(a, "work_kind", None) in ("code", "test") and not getattr(a, "primary", None):
            print(lab(st, "primary_missing_hint"), file=sys.stderr)
        if getattr(a, "primary", None) and any(w in a.primary.lower() for w in PRIMARY_INTERNAL_WORDS):
            print(lab(st, "primary_internal"), file=sys.stderr)
        warn = topic_mismatch(st, a.owner, a.title)  # no --title: nothing to compare yet
        if warn:
            print(warn, file=sys.stderr)
        task = st.get("tasks", {}).get(a.id)
        if task and task.get("topics"):
            area = area_of_task(st, task)
            related = any(q.get("category") in ("bug", "correction") and q.get("status") not in REQ_END + ("wont",)
                          and q.get("area") == area for q in st.get("requests", {}).values()) or any(
                              area_of_task(st, other) == area and other.get("rework_at")
                              for other in st.get("tasks", {}).values())
            if related and (area not in st.get("areas", {}) or st.get("areas",{}).get(area,{}).get("implicit")):
                print(lab(st,"root_suggest",topic=task["topics"][0],paths=",".join(task.get("touches",[])) or "<paths>"),file=sys.stderr)
    else:
        if a.id not in st["tasks"]:
            sys.exit(f"unknown task {a.id}")
        k = st["tasks"][a.id]
        before = json.loads(json.dumps(k))
        changes = {"status_to": None}
        if a.status == "review" and a.dispatch_v is not None:
            current_v = int(k.get("dispatch_v") or 0)
            if a.dispatch_v < current_v:
                sys.exit(lab(st, "late_dispatch", task=a.id, got=a.dispatch_v, current=current_v))
            if a.dispatch_v > current_v:
                sys.exit(f"{a.id}: dispatch v{a.dispatch_v} is newer than current v{current_v}")
        if getattr(a, "urgent", False) or getattr(a, "urgent_minutes", None) is not None:
            if a.urgent_minutes is not None and a.urgent_minutes < 1: sys.exit("--urgent-minutes: positive whole minutes")
            k["urgent"] = True
            k["urgent_minutes"] = a.urgent_minutes if a.urgent_minutes is not None else pref(st, 'urgent_ack_minutes')
        cur = k["status"]
        said = (a.user_said or "").strip()
        stale = {}  # follow-up tasks opened from a verdict that is now void (T23-c)

        def void(why, restart=False, change="accept"):
            old = invalidate(k, [change], st)
            if old:
                k["past_reviews"][-1]["voided"] = why
                for t, x in st["tasks"].items():
                    if x.get("followup_of") == a.id and x.get("followup_item") in (old.get("remaining") or []) \
                            and x.get("status") not in ("done", "dropped") and not x.get("parent_verdict_voided"):
                        x["parent_verdict_voided"] = why
                        stale[t] = x
            if restart and k.get("review_rounds"):  # a new criterion or a new owner: the round count starts over
                k.setdefault("past_reviews", []).append({"rounds_reset": k.pop("review_rounds"), "why": why,
                                                         "at": now()})
        # 0. the move itself must be legal before anything is changed
        if a.status and a.status != cur:
            if a.status not in TASK_STATUSES:
                sys.exit(f"status must be one of {TASK_STATUSES}")
            allowed = TASK_MOVES.get(cur, set())
            if a.status not in allowed:
                sys.exit(f"{a.id} is {cur}: it can move to {', '.join(sorted(allowed)) or 'nothing (it has ended)'}"
                         + (" (done only from review)" if a.status == "done" else ""))
            if a.status == "dispatched" and pref(st, 'root_mode') == "on":
                proposed = dict(k)
                if a.topics is not None: proposed["topics"] = norm_topics(a.topics)
                if a.touches is not None: proposed["touches"] = check_touches(a.touches)
                area = area_of_task(st, proposed); state = radar(st).get(area, {}).get("state", "ok")
                if state in ("pending", "reviewing", "asked"):
                    said=(getattr(a,"user_said",None) or "").strip()
                    urgent=urgent_words(said)
                    if not getattr(a,"hotfix",None) and not urgent: sys.exit(lab(st,"root_gate",task=a.id,area=area,state=lab(st,"root_"+state),next=root_next(state,area)))
                    why=said if urgent else a.hotfix
                    if not urgent: print("hotfix dispatched; debt recorded",file=sys.stderr)
                    st["areas"].setdefault(area,new_area(state=state)).setdefault("debt",[]).append({"task":a.id,"why":why,"at":now(),"user_said":said or None,"kind":"hotfix"})
                    k["fix_kind"]="patch"
                elif state == "patched":
                    k["fix_kind"]="patch"
                    rec=st["areas"].setdefault(area, new_area(state="patched", baseline=""))
                    rec.setdefault("debt", []).append({"task":a.id,"at":_later_than(now(),rec.get("answered_at") or rec.get("asked")),"kind":"patch"})
                elif state == "rooting" and k.get("fix_kind") != "root": k["fix_kind"]="patch"
        if cur in ("done", "dropped") and any(x is not None for x in (a.owner, a.accept, a.deps)):
            sys.exit(f"{a.id} has ended ({cur}): its owner, 'done when' and deps are final")
        # 1. field edits first, so every check below sees the task as it will be stored
        if a.owner is not None:
            if a.owner and a.owner not in st["threads"]:
                sys.exit(f"unknown owner {a.owner}")
            if (a.owner or None) != k.get("owner"):
                # A new owner changes neither the artifact nor the reviewed diff, so the primary check
                # stays. Only the old rules apply (T23): the reviewer becoming the owner voids a pass,
                # a capped verdict stood on the old owner's rounds, and the round count starts over.
                rv = k.get("review") or {}
                if rv.get("result") in PASSING and not reviewer_independent(rv.get("reviewer") or "", a.owner or ""):
                    void("its reviewer became the owner")
                if (k.get("review") or {}).get("result") == "capped":  # capped stood on the old owner's rounds
                    void("owner changed: capped stood on the old owner's rounds")
                    print(f"{a.id}: capped verdict voided by the owner change; review again", file=sys.stderr)
                if k.get("review_rounds"):  # the rounds were the old owner's: a new owner starts over
                    k.setdefault("past_reviews", []).append({"rounds_reset": k.pop("review_rounds"),
                                                             "why": "owner changed", "at": now()})
                if k.get("owner") and k["owner"] not in k.setdefault("past_owners", []):
                    k["past_owners"].append(k["owner"])  # wrote part of the work: never its reviewer
                k["owner"] = a.owner or None
        if a.accept is not None and a.accept != k.get("accept"):
            void("'done when' changed", restart=True)  # the verdict was against the old criterion
            k["accept"] = a.accept
            changes["accept"] = True
        old_deps = list(k.get("deps") or [])
        if a.deps is not None:
            k["deps"] = csv(a.deps)
        if a.title or getattr(a, "brief", None) or a.accept:
            check_never_raise(d, " ".join(x for x in (a.title, getattr(a, "brief", None), a.accept) if x), getattr(a, "override", None))
        if getattr(a, "req", None) and st.get("requests", {}).get(a.req, {}).get("kind", "request") != "request":
            sys.exit(lab(st, "req_not_request"))
        if a.title:
            k["title"] = a.title
        if getattr(a, "brief", None):
            k["brief"] = a.brief
        if getattr(a, "work_kind", None):
            k["kind"] = a.work_kind
        if getattr(a, "primary", None) is not None:
            old_primary = k.get("primary")
            if a.primary.strip() and not _primary_text_valid(a.primary): sys.exit(lab(st, "primary_weak"))
            if a.primary.strip(): k["primary"] = a.primary.strip()
            else: k.pop("primary", None)
            if old_primary != k.get("primary"):
                changes["primary"] = True
                if k.get("review"):
                    void("primary outcome changed", change="primary")
                else:
                    invalidate(k, ["primary"], st)
                if cur == "review":
                    return_to_working(k, "primary outcome changed", st)
            if a.primary.strip() and any(w in a.primary.lower() for w in PRIMARY_INTERNAL_WORDS):
                print(lab(st, "primary_internal"), file=sys.stderr)
        if a.touches is not None:
            k["touches"] = check_touches(a.touches, st.get("repo", {}).get("path"))
        if a.model is not None:
            if a.model.strip():
                k["model"] = a.model.strip()
            else:
                k.pop("model", None)
        if a.route is not None:
            if a.route.strip():
                k["route"] = a.route.strip()
            else:
                k.pop("route", None)
        if a.no_scripts:
            k["no_scripts"] = True
        if a.scripts_ok:
            k.pop("no_scripts", None)
        if a.topics is not None:
            k["topics"] = norm_topics(a.topics)
        if a.notes is not None:
            k["notes"] = a.notes
        if getattr(a, "merged", None) is not None:  # B4: the board's progress chain reads this mark
            if (a.status or cur) not in ("review", "done"):
                sys.exit("--merged: only a task in review or done has merged work")
            if not re.fullmatch(r"[0-9a-fA-F]{7,40}", a.merged.strip()):
                sys.exit("--merged: the merge commit (7 to 40 hex characters)")
            k["merged_at"], k["merged_sha"] = now(), a.merged.strip().lower()
        if a.checks:
            if cur == "done" and a.checks != k.get("checks"):  # T23-a: a done task's verdict and checks are final
                sys.exit(f"{a.id} is done: its checks and verdict are final. A regression is new work: add a new task for it"
                         )
            if k.get("checks") == "fail" and a.checks == "none":
                sys.exit(f"{a.id}: checks failed; only `--checks pass` clears that")
            if a.checks != "pass" and (k.get("review") or {}).get("result") == "capped":
                void("checks no longer passing", change="checks")  # capped stood on green checks
            k["checks"] = a.checks
        if getattr(a, "base", None) and not a.review and (k.get("review") or {}).get("base") != a.base.strip().lower():
            invalidate(k, ["base"], st)
            changes["base"] = True
        owner = k.get("owner") or ""
        # 2. a review verdict, only on work that is in review, by someone independent of the owner
        if a.rounds is not None and not a.review:
            sys.exit("--rounds goes with --review (the number of review rounds the thread reported)")
        if a.rounds is not None and not 1 <= a.rounds <= 99:
            sys.exit("--rounds: 1 to 99")
        if a.review:
            if a.review == "fail" and a.status not in (None, "working"):
                sys.exit("--review fail permits only an omitted --status or --status working")
            if not a.tests:
                sys.exit(lab(st, "g8_tests"))
            if a.tests == "not-run" and not (a.tests_why or "").strip():
                sys.exit(lab(st, "g8_tests_why"))
            if not re.fullmatch(r"[0-9a-fA-F]{7,40}", (a.base or "").strip()):
                sys.exit(lab(st, "g8_base"))
            if a.reviewed and not re.fullmatch(r"[0-9a-fA-F]{7,40}", a.reviewed.strip()):
                sys.exit(lab(st, "g8_reviewed"))
            expected_reviewed = k.get("merged_sha") or ((k.get("review") or {}).get("reviewed"))
            if expected_reviewed and a.base.strip().lower() != expected_reviewed.lower():
                print(lab(st, "g8_base_mismatch", base=a.base.strip(), expected=expected_reviewed), file=sys.stderr)
            verify_sha = ((k.get("primary_check") or {}).get("sha") or "").lower()
            if verify_sha and ((a.base or "").strip().lower() != verify_sha or
                               (a.reviewed or "").strip().lower() != verify_sha):
                print(lab(st, "g8_verify_sha_mismatch", sha=verify_sha), file=sys.stderr)
            if a.env_down and not a.env_down.strip():
                sys.exit(lab(st, "g8_env_why"))
            if a.env_down and a.review != "fail":
                sys.exit(lab(st, "g8_env_fail"))
            if not (a.reviewer or "").strip():
                sys.exit("--review needs --reviewer (a fresh subagent of the owner, a review thread, ...)")
            if cur != "review" and a.status != "review":
                sys.exit(f"{a.id} is {cur}: record a review only while it is in review "
                         f"(`task set {a.id} --status review` once the work is there)")
            if not owner:
                sys.exit(f"{a.id} has no owner: an independent review needs to know whose work it is")
            past = next((o for o in k.get("past_owners") or [] if not reviewer_independent(a.reviewer, o)), None)
            if past:
                sys.exit(f"{a.reviewer} owned {a.id} before and wrote part of it: get a reviewer without its context")
            if not reviewer_independent(a.reviewer, owner):
                sys.exit(f"{a.reviewer} owns {a.id}: the reviewer must be someone without its context "
                         f"(e.g. {owner}/subagent, a fresh subagent the owner starts)")
            if getattr(a, "outside", False):
                participants = {owner, *(k.get("past_owners") or [])}
                for event in _read_log(d):
                    if event.get("task") != a.id: continue
                    if str(event.get("type", event.get("message_type", ""))).upper() == "HANDOFF" or event.get("ev") in ("task-msg", "route"):
                        participants.update(x for x in (event.get("from"), event.get("to"), event.get("sender"), event.get("receiver"), event.get("thread"), event.get("owner")) if x)
                if not reviewer_independent(a.reviewer, "user") and a.reviewer.strip().lower() == "user":
                    participants.discard("user")
                if any(not reviewer_independent(a.reviewer, participant) for participant in participants):
                    sys.exit(f"{a.reviewer} participated in {a.id}; outside review requires a reviewer with no task history")
            prev = int(k.get("review_rounds") or 0)
            if a.rounds is not None and a.rounds < max(prev, 1):
                sys.exit(f"{a.id}: {prev} review rounds are already recorded; --rounds only goes up "
                         "(the thread's own count, from its DONE)")
            if a.rounds is not None and a.rounds > prev + 1:
                print(f"{a.id}: --rounds advanced by {a.rounds - prev}; confirm the thread's reported count",
                      file=sys.stderr)
            rounds = a.rounds if a.rounds is not None else prev + 1
            remaining = list(dict.fromkeys(x.strip() for x in re.split(r"\s*;\s*|\n", a.remaining or "") if x.strip()))
            if a.remaining is not None and a.review not in PASSING:
                sys.exit("--remaining goes with --review pass or capped (important findings left for follow-up tasks)")
            if a.no_blocking and not (a.review == "capped" or (a.review == "pass" and remaining)):
                sys.exit("--no-blocking goes with --review capped, or pass with --remaining")
            if a.review == "pass" and remaining:  # T23-b: the protocol's "two rounds without a new important one"
                if rounds < 2:
                    sys.exit(f"{a.id}: pass with --remaining needs at least 2 review rounds (two in a row without a "
                             "new important finding); with one round, fix them or record fail")
                if k.get("checks") != "pass":
                    sys.exit(f"{a.id}: pass with --remaining needs the checks green: record `--checks pass`")
                if not a.no_blocking:
                    sys.exit(f"{a.id}: pass with --remaining needs --no-blocking (no blocking finding left open)")
            if a.review == "capped":
                cap = review_max(st)
                if not cap or rounds < cap:
                    sys.exit(f"{a.id}: review round {rounds} of {cap or 'unlimited'}; `capped` is only for the last "
                             "allowed round (prefs review_max_rounds). Pass the thread's own round count from its DONE "
                             "with --rounds N; otherwise fix blocking and important findings and review again")
                if k.get("checks") != "pass":
                    sys.exit(f"{a.id}: capped needs the checks green: record `--checks pass` (in the same call is fine)")
                if not a.no_blocking:
                    sys.exit(f"{a.id}: capped needs --no-blocking: the last round left no blocking finding "
                             "(a blocking one is a fail)")
                if not remaining:
                    sys.exit(f"{a.id}: capped needs --remaining \"<finding>; <finding>\" (the important findings left "
                             "for follow-up tasks); with none left, record pass")
            if a.review in PASSING and a.tests == "not-run" and k.get("checks") != "pass" and not a.recheck_evidence:
                sys.exit(lab(st, "g8_notrun_pass"))
            if a.env_down:
                invalidate(k, ["env-down"], st)
                k["review"] = {"result": "blocked-env", "reviewer": a.reviewer.strip(), "note": a.env_down.strip(),
                               "tests": a.tests, "tests_why": a.tests_why or "", "base": a.base.strip().lower(), "at": now()}
                print(lab(st, "review_blocked_env"), file=sys.stderr)
                changes["review_recorded"] = True
            else:
                changes["review_recorded"] = True
            if not a.env_down:
                if k.get("review"):
                    void(f"replaced by a {a.review} verdict", change="replace")
                k["review_rounds"] = rounds
                k["review"] = {"result": a.review, "reviewer": a.reviewer.strip(), "note": a.review_note or "",
                               **({"outside": True} if getattr(a, "outside", False) else {}),
                               "round": rounds, "cap": review_max(st), "at": now(),
                               "tests": a.tests, "tests_why": a.tests_why or "", "base": a.base.strip().lower(),
                               "reviewed": (a.reviewed or "").strip().lower(),
                               "recheck_how": a.recheck_how, "recheck_evidence": a.recheck_evidence,
                               **({"suspect_cleared": True} if getattr(a, "suspect_cleared", False) else {}),
                               **({"remaining": remaining} if remaining else {})}
                if a.review in PASSING:
                    for t, x in st["tasks"].items():
                        if x.get("followup_of") == a.id and x.get("parent_verdict_voided") \
                                and x.get("followup_item") in remaining:
                            x.pop("parent_verdict_voided")
                            stale[t] = x
                if a.review == "capped":
                    print(f"{a.id}: capped at round {rounds}; open its follow-ups with `tw.py task followups {a.id} --apply`",
                          file=sys.stderr)
                if a.review == "fail" and not a.status:
                    void("review failed; task returned to working", change="review-fail")
                    return_to_working(k, "review failed", st)
                    print(f"{a.id} back to working: send its owner a FOLLOWUP with the review findings", file=sys.stderr)
        # 3. preconditions of the status move, against the edited task
        if a.status and a.status != k["status"]:
            if a.status == "approved" and not st.get("plan_approved"):
                sys.exit(f"{a.id}: tasks are approved with the plan: `plan approve --user-said ...` once the user agrees")
            if a.status == "dispatched" and k.get("needs_ask") and any(not q.get("answered") and q.get("task") == a.id for q in st.get("questions", [])):
                sys.exit(lab(st, "beyond_wait", task=a.id))
            if a.status == "dispatched":
                offered, blocked_lease, blocked_topic = plan_ready(st, [a.id])
                if a.id in blocked_lease:
                    reason = (getattr(a, "lease_reason", None) or "").strip()
                    if not (getattr(a, "force_lease", False) and reason):
                        conflict = blocked_lease[a.id]
                        sys.exit(f"{a.id}: dispatch blocked by active work {conflict}; use --force-lease --lease-reason \"<reason>\" to override")
                    k.setdefault("lease_overrides", []).append({"at": now(), "reason": reason})
                    print(f"{a.id}: lease conflict overridden: {reason}", file=sys.stderr)
                if cur == "recalled":
                    invalidate(k, ["redispatch"], st)
                deps = list(dict.fromkeys(old_deps + (k.get("deps") or [])))  # clearing deps here skips nothing
                open_deps = [x for x in deps if st["tasks"].get(x, {}).get("status") != "done"]
                if open_deps:
                    sys.exit(f"{a.id} waits for {', '.join(open_deps)} (deps not done)")
                if not st.get("plan_approved"):
                    sys.exit(f"{a.id}: the plan is reopened; `plan approve` again before dispatching")
                if not owner:
                    sys.exit(f"{a.id} has no owner: `task set {a.id} --owner <thread>` first")
            if a.status == "dropped" and not said:
                sys.exit(f"dropping {a.id} is the user's decision: add --user-said \"<their words>\"")
            if a.skip_review and (not said or not a.skip_review.strip()):
                sys.exit("--skip-review \"<reason>\" needs --user-said \"<the user's words>\": skipping review is "
                         "their call")
            if a.status == "done":
                rv = k.get("review") or {}
                if rv.get("result") == "fail":
                    print(lab(st, "task_done_fail_review", task=a.id), file=sys.stderr)
                remaining = rv.get("remaining") or []
                opened = {x.get("followup_item") for x in st.get("tasks", {}).values()
                          if x.get("followup_of") == a.id and x.get("status") not in ("dropped", "done")}
                orphaned = [item for item in remaining if item not in opened]
                if orphaned:
                    print(lab(st, "task_done_orphan_findings", task=a.id, findings="; ".join(orphaned)), file=sys.stderr)
                if (k.get("primary_check") or {}).get("result") == "pending-real" and said.strip():
                    k.setdefault("primary_waivers", []).append({"why": said.strip(), "at": now(), "kind": "pending-real-done"})
                if a.skip_review:
                    void("review skipped", change="replace")
                    k["review"] = {"result": "skipped", "note": a.skip_review.strip(), "user_said": said, "at": now()}
            if a.status == "working" and cur in ("review", "done"):
                if k.get("review"):
                    void("rework after review", change="working")
                else:
                    invalidate(k, ["working"], st)
                return_to_working(k, "explicit status working", st)
            changes["status_to"] = k.get("status") if a.status else None
            k["status"] = a.status
            k["updated"] = _later_than(now(), k.get("updated"))
            if a.status == "dispatched":
                k["dispatch_v"] = int(k.get("dispatch_v") or 0) + 1
                k["dispatched_at"] = now()
        if a.status == "review" and a.dispatch_v is not None:
            k["review_dispatch_v"] = a.dispatch_v
        if a.status in ("review", "done", "dropped"):  # dropping the last open task can deliver the rest
            for r in deliver_ready(st):
                print(f"request {r} delivered (all its tasks are in review or done): report it to the user, then "
                      f"`tw.py req set {r} --status reported`", file=sys.stderr)
        marked = sorted(t for t, x in stale.items() if x.get("parent_verdict_voided"))
        if marked:
            print(f"{a.id}: follow-ups {', '.join(marked)} came from a voided verdict; after the next review keep them "
                  "(a pass or capped that lists the same finding clears the mark) or drop them with the user's OK",
                  file=sys.stderr)
        if k["status"] not in ("review", "done"):
            for r in undeliver(st):
                print(f"request {r} back to dispatched: {a.id} is {k['status']} again", file=sys.stderr)
        if k.get("status") != before.get("status"):
            changes["status_to"] = k.get("status")
        check_task_invariants(st, a.id, before, k, a, said, changes)
        save(
            d,
            st,
            {
                "ev": "task-set",
                "task": a.id,
                "status": k["status"],
                "owner": k["owner"],
                **({"user_said": said} if said else {}),
            },
        )
        if a.owner or a.title:  # after the save: warn only about what was stored
            warn = topic_mismatch(st, k.get("owner"), k.get("title") if k.get("title") != a.id else None)
            if warn:
                print(warn, file=sys.stderr)
    print(render_tasks(st))


def cmd_plan(a):
    d = need(find_dir())
    st = load(d)
    if a.action == "approve":
        if not (a.user_said or "").strip():
            sys.exit("approving the plan is the user's decision: `plan approve --user-said \"<their words>\"`")
        st.setdefault("plan_user_said", []).append({"t": now(), "text": a.user_said.strip()})
        st["plan_approved"] = True
        for k in st["tasks"].values():
            if k["status"] == "planned":
                k["status"] = "approved"
        save(d, st, {"ev": "plan-approved", "user_said": a.user_said.strip()})
    elif a.action == "reopen":
        st["plan_approved"] = False
        save(d, st, {"ev": "plan-reopened"})
    print(render_board(st))


LEASE_ACTIVE = ("dispatched", "working", "blocked", "review")


def _norm_path(x):
    """'./web//a/../b/' -> 'web/b/' (trailing slash kept: it marks a folder); '.' or '/' -> '**' (everything)."""
    import posixpath
    x = x.strip().replace("\\", "/")
    if not x:
        return ""
    folder = x.endswith("/")
    x = posixpath.normpath(x.lstrip("/") or ".")
    if x in (".", ""):
        return "**"
    return x + "/" if folder and not x.endswith("/") else x


_GLOB = "*?["
_GLOB_TOK = re.compile(r"\*|\?|\[!?\]?[^\]]*\]")  # glob tokens as fnmatch reads them ('[' alone is literal)


def _expand_braces(p, limit=64):
    """'web/{a,b}.py' -> ['web/a.py', 'web/b.py'] (nested groups too). Past `limit` names the pattern is widened:
    the folder part from the first brace on becomes '**' (a superset across folders, so still conservative)."""
    if p.count("{") != p.count("}"):
        return ["**"]  # malformed syntax is uncertain; widen to avoid missing a lease collision

    def group(x):
        depth, start = 0, None
        for i, ch in enumerate(x):
            if ch == "{":
                if depth == 0:
                    start = i
                depth += 1
            elif ch == "}" and depth:
                depth -= 1
                if depth == 0:
                    body = x[start + 1:i]
                    parts, at, inner = [], 0, 0
                    for j, c in enumerate(body):
                        if c == "{": inner += 1
                        elif c == "}" and inner: inner -= 1
                        elif c == "," and not inner:
                            parts.append(body[at:j]); at = j + 1
                    if parts:
                        parts.append(body[at:])
                        return start, i + 1, parts
                    nested = group(body)
                    if nested:
                        a, b, alts = nested
                        return start + 1 + a, start + 1 + b, alts
                    nested = group(x[i + 1:])
                    if nested:
                        a, b, alts = nested
                        return i + 1 + a, i + 1 + b, alts
                    return None
        return None

    def count(x, depth=0):
        g = group(x)
        if not g or depth > 12:
            return 1 if not g else limit + 1
        n = 0
        for alt in g[2]:
            n += count(x[:g[0]] + alt + x[g[1]:], depth + 1)
            if n > limit:
                return n
        return n
    if count(p) > limit:
        head = p[:p.index("{")]
        return [head[:head.rfind("/") + 1] + "**"]
    g = group(p)
    if not g:
        return [p]
    out = []
    for alt in g[2]:
        out += _expand_braces(p[:g[0]] + alt + p[g[1]:], limit)
    return out


def _seg_meet(x, y):
    """Can one path segment match both glob segments? Exact for literals; for two wildcards a conservative check
    on their literal head and tail (may say yes when unsure, never no when they can meet)."""
    import fnmatch
    if x == y:
        return True
    gx, gy = any(c in x for c in _GLOB), any(c in y for c in _GLOB)
    if not gx and not gy:
        return False
    if not gx:
        return fnmatch.fnmatchcase(x, y)
    if not gy:
        return fnmatch.fnmatchcase(y, x)
    mx, my = list(_GLOB_TOK.finditer(x)), list(_GLOB_TOK.finditer(y))
    if not mx or not my:  # only an unclosed '[': fnmatch reads it literally
        return fnmatch.fnmatchcase(x, y) if not mx else fnmatch.fnmatchcase(y, x) if not my else x == y
    hx, hy = x[:mx[0].start()], y[:my[0].start()]
    tx, ty = x[mx[-1].end():], y[my[-1].end():]
    return (hx.startswith(hy) or hy.startswith(hx)) and (tx.endswith(ty) or ty.endswith(tx))


def _globs_meet(a, b):
    """Is there a path that matches both segment lists? '**' matches zero or more segments."""
    from functools import lru_cache
    A, B = tuple(a), tuple(b)

    @lru_cache(maxsize=None)
    def go(i, j):
        if i == len(A) and j == len(B):
            return True
        if i < len(A) and A[i] == "**":
            return go(i + 1, j) or (j < len(B) and go(i, j + 1)) or (j < len(B) and B[j] == "**" and go(i + 1, j + 1))
        if j < len(B) and B[j] == "**":
            return go(i, j + 1) or (i < len(A) and go(i + 1, j))
        if i == len(A) or j == len(B):
            return False
        return _seg_meet(A[i], B[j]) and go(i + 1, j + 1)

    return go(0, 0)


@functools.lru_cache(maxsize=4096)
def _lease_forms_cached(p):
    return tuple(tuple(x) for x in _lease_forms_raw(p))


def _lease_forms(p):
    return _lease_forms_cached(p)


def _lease_forms_raw(p):
    """Segment lists a lease covers: a folder ('web/', or a literal 'web' that may be one) covers all below it;
    a glob without '/' ('*.py') matches in any folder.
    Case-folded: on a case-insensitive disk Web/App.py and web/app.py are one file."""
    out = []
    import unicodedata
    for q in _expand_braces(unicodedata.normalize("NFC", _norm_path(p)).casefold()):
        folder = q.endswith("/")
        segs = [x for x in q.strip("/").split("/") if x]
        if not segs:
            continue
        out.append(segs + ["**"] if folder else segs)
        if len(segs) == 1 and any(c in segs[0] for c in _GLOB) and segs[0] != "**":
            out.append(["**"] + out[-1])  # '*.py' means .py files in any folder, as in .gitignore
            if not folder:
                out.append(["**"] + segs + ["**"])  # ... or a folder of that name at any depth
        if not folder and segs[-1] != "**":
            out.append(segs + ["**"])  # 'web' or 'web/*' may name a folder: cover what is below it
    return out


def _split_touches(s):
    """'web/{a,b}.js, api/x.py' -> ['web/{a,b}.js', 'api/x.py']: commas inside {...} belong to the brace."""
    out, cur, depth = [], "", 0
    for ch in s or "":
        if ch == "," and depth == 0:
            out.append(cur)
            cur = ""
            continue
        depth += (ch == "{") - (ch == "}" and depth > 0)
        cur += ch
    out.append(cur)
    return [x.strip() for x in out if x.strip()]


def check_touches(s, project=None):
    depth = 0
    for ch in s or "":
        depth += (ch == "{") - (ch == "}")
        if depth < 0:
            break
    if depth != 0:
        sys.exit(f"--touches has unbalanced braces: {s}")
    out = _split_touches(s)
    if project:
        root = Path(project).resolve()
        normalized = []
        for x in out:
            if Path(x).is_absolute():
                p = Path(x).resolve()
                try:
                    x = p.relative_to(root).as_posix()
                except ValueError:
                    sys.exit(f"--touches must stay inside the project: {x}")
            elif (root / x).resolve() == root:
                sys.exit("--touches cannot name the project root")
            for alt in _expand_braces(x):
                if Path(alt).is_absolute():
                    sys.exit(f"--touches brace alternatives must be relative to the project: {alt}")
            if Path(x).resolve() == root:
                sys.exit("--touches cannot name the project root")
            normalized.append(x)
        out = normalized
    bad_class = [x for x in out if any("/" in m.group(0) for m in re.finditer(r"\[[^\]]*\]", x))]
    if bad_class:
        sys.exit(f"--touches glob character classes cannot contain '/': {', '.join(bad_class)}")
    bad = [x for x in out for y in _expand_braces(x) if _norm_path(y).startswith("../") or _norm_path(y) == ".."]
    if bad:
        sys.exit(f"--touches must stay inside the repo: {', '.join(bad)}")
    return out


class RealFile(str):
    """A file name from git (a real file, never a folder, never a glob: '*', '[', '\\' and braces are literal)."""


def _file_segs(f):
    import unicodedata
    return tuple(x for x in unicodedata.normalize("NFC", f).casefold().split("/") if x)


@functools.lru_cache(maxsize=65536)
def _lit_meet(f, g):
    """Does the literal path f (segments) match the glob g (segments, '**' spans folders)?"""
    import fnmatch
    if not g:
        return not f
    if g[0] == "**":
        return any(_lit_meet(f[i:], g[1:]) for i in range(len(f) + 1))
    return bool(f) and (f[0] == g[0] or fnmatch.fnmatchcase(f[0], g[0])) and _lit_meet(f[1:], g[1:])  # 'app/[id]/' is
    # also a literal folder name (Next.js, SvelteKit), as git pathspecs read it


def paths_overlap(a, b):
    """True if some file could match both path globs (or a glob and a real path). Conservative when unsure."""
    if isinstance(a, RealFile) or isinstance(b, RealFile):
        f, other = (a, b) if isinstance(a, RealFile) else (b, a)
        if isinstance(other, RealFile):
            return _file_segs(f) == _file_segs(other)
        fs = _file_segs(f)
        raw = _file_segs(_norm_path(other))  # the lease read literally too: a real file named '{a,b}.py'
        return any(_lit_meet(fs, g) for g in {raw, raw + ("**",)} | {tuple(g) for g in _lease_forms(other)})
    return any(_globs_meet(x, y) for x in _lease_forms(a) for y in _lease_forms(b))


def _base_ref(st, git):
    """origin/<base> or <base>, whichever is newer (a stale origin would count merged work as unmerged)."""
    base = st.get("repo", {}).get("base") or "main"
    have = [b for b in (f"origin/{base}", base)
            if git("rev-parse", "--verify", "--quiet", b + "^{commit}").returncode == 0]
    if len(have) == 2 and git("merge-base", "--is-ancestor", have[0], have[1]).returncode == 0:
        return have[1]  # local base has everything origin has, and maybe more (merged but not pushed yet)
    return have[0] if have else None


_GIT_CACHE = {}


def _git_cached(repo):
    """git runner for one repo; identical read-only calls within one tw.py run are answered from memory."""
    def git(*x):
        key = (repo, x)
        if key not in _GIT_CACHE:
            try:
                _GIT_CACHE[key] = subprocess.run(["git", "-c", "core.quotePath=false", "-C", repo, *x],
                                                 capture_output=True, text=True)
            except OSError as e:  # no git program: same as "not a git repo" (declared paths only)
                _GIT_CACHE[key] = subprocess.CompletedProcess(x, 127, "", str(e))
        return _GIT_CACHE[key]
    return git


def _z(out):
    """NUL-separated git name list (-z): names with quotes, tabs, newlines or backslashes stay whole."""
    return [n for n in out.split("\x00") if n]


_ID_RX = lambda tid: re.compile(rf"(^|[^A-Za-z0-9_]){re.escape(tid)}(?![0-9A-Za-z_]|[.-][0-9A-Za-z])")


def _subject_leads_with(subj, tids, rxs=None):
    """True when a commit subject starts with one of the task ids (`T3: ...`, `[T3] ...`, `fix(T3): ...`)."""
    rxs = rxs or [_ID_RX(t) for t in tids]
    head = re.match(r"\s*(?:\[([^\]]+)\]|\w+\(([^)]+)\)|([^\s:]+))", subj)
    lead = head and next((g for g in head.groups() if g), "")
    lead = (lead or "").strip()
    candidates = {x.casefold() for x in tids}
    parsed = [v.casefold() for v in re.split(r"\s*,\s*", lead.strip("[] "))]
    bracket = bool(re.match(r"\s*\[", subj))
    return bool(lead) and (any(rx.fullmatch(lead) for rx in rxs) or lead in candidates or
                           (bracket and len(parsed) > 1 and bool(candidates.intersection(parsed))))


_TOKEN_RX = re.compile(r"[A-Za-z0-9_]+(?:[.-][0-9A-Za-z]+)*")  # one id-like word, as _ID_RX delimits task ids
_TOUCHES_CACHE = {}


def _branch_touches(git, base, br):
    """{file: [(lead id, words in the subject, plain)]} for the commits on br since base, parsed once per run.
    lead: the subject's leading id (`T5: ...`, `[T5] ...`, `fix(T5): ...`); words: lowercased, each also cut
    at its first `-` or `.` (`T29-related` names T29: a near miss holds); plain: an add / modify / delete in a
    one-parent commit. Renames git detects (both names) and every file a merge brought in (first parent) are
    never plain, whatever the subject says. Copies are not looked for (`--find-copies-harder` is too slow), and
    a rename git sees as delete + add counts as plain."""
    args = ("-z", "-M", "--relative", "--name-status", "--format=%x01%P%x02%s", f"{base}..{br}")
    r = git("log", "--diff-merges=first-parent", *args)  # a merge lists what it brought in (git >= 2.31) ...
    log = (r if r.returncode == 0 else git("log", "-m", *args)).stdout  # ... older git: against every parent
    key = log  # git calls are cached per run; the parse is shared by every task that reads this branch
    if key not in _TOUCHES_CACHE:
        touches = {}
        for chunk in log.split("\x01")[1:]:
            subj, _, names = chunk.partition("\x00")
            parents, _, subj = subj.partition("\x02")
            merge = len(parents.split()) > 1
            head = re.match(r"\s*(?:\[([^\]]+)\]|\w+\(([^)]+)\)|([^\s:]+))", subj)
            lead = ((head and next((g for g in head.groups() if g), "")) or "").strip()
            words = {w.lower() for w in _TOKEN_RX.findall(subj)}
            words = frozenset(words | {re.split(r"[.-]", w, 1)[0] for w in words})
            tok, i = _z(names[1:] if names.startswith("\n") else names), 0
            while i < len(tok):
                two = tok[i].strip()[:1] in ("R", "C")
                paths = tok[i + 1:i + 3] if two else tok[i + 1:i + 2]
                for f in paths:
                    touches.setdefault(f, []).append((lead, words, not (two or merge)))
                i += 1 + len(paths)
        _TOUCHES_CACHE[key] = touches
    return _TOUCHES_CACHE[key]


def _other_tasks_only(git, base, br, task, ids, files):
    """The files (of `files`) that only other tasks' commits on br changed: every commit touching them leads with
    another task's id (`T5: ...`), does not name `task` anywhere, and is a plain one-parent change (see
    _branch_touches). Everything else holds: this task's commits, commits naming no task (`WIP: ...`, `fixup! ...`),
    renames and merges, so unclear work is never dropped from the lease."""
    touches = _branch_touches(git, base, br)
    return {f for f in files if touches.get(f) and all(plain and lead != task and lead in ids and task.lower() not in words
                                                         for lead, words, plain in touches[f])}


def _landed_files(git, base, br, files, tids):
    """The subset of a done branch's files that has reached the base, by any kind of merge:
    - merging the branch into the base would change nothing at all (git merge-tree, git >= 2.38): all of them;
    - the base has the same content now (plain squash/rebase);
    - a base commit since the fork changed that file and names the task id in its subject (squash or rebase that the
      base edited again later; SKILL step 7 keeps the id in the subject). Reverts and mere mentions do not count."""
    mt = git("merge-tree", "--write-tree", base, br)
    bt = git("rev-parse", f"{base}^{{tree}}")
    if mt.returncode == 0 and mt.stdout.split() and bt.stdout.strip() == mt.stdout.split()[0]:
        return set(files)
    same = set(files) - set(_z(git("diff", "-z", "--relative", "--name-only", "--no-renames", base, br, "--").stdout))
    tids = [tids] if isinstance(tids, str) else list(tids or [])
    if tids:
        fork = git("merge-base", base, br).stdout.strip()
        if fork:
            rxs = [_ID_RX(t) for t in tids]
            log = git("log", "-z", "--relative", "--no-renames", "--name-only",
                      "--format=%x01%H %s%x02%B%x03",
                      f"{fork}..{base}").stdout
            chunks = log.split("\x01")[1:]
            parsed = []
            for chunk in chunks:
                header, _, content = chunk.partition("\x02")
                body, _, names = content.partition("\x03")
                sha, _, subj = header.partition(" ")
                parsed.append((sha, subj, body, names))
            for chunk_index, chunk in enumerate(chunks):
                sha, subj, body, names = parsed[chunk_index]
                later = "\n".join(row[2] for row in parsed[:chunk_index])
                # GitHub's `Reverts owner/repo#N` form has no commit SHA and is intentionally not inferred here.
                if _subject_leads_with(subj, tids, rxs) and not re.search(
                        rf"(?im)^This reverts commit {re.escape(sha[:7])}[0-9a-f]{{0,33}}\b.*$", later):
                    names = names[2:] if names.startswith("\x00\n") else names[1:] if names.startswith("\n") else names
                    todo = (set(files) - same) & set(_z(names))
                    if not todo:
                        continue
                    at_c, at_br = _blobs_at(git, sha, todo), _blobs_at(git, br, todo)
                    mt = git("merge-tree", "--write-tree", f"{sha}^", br)  # the branch merged onto the squash's parent
                    at_m = _blobs_at(git, mt.stdout.split()[0], todo) if mt.returncode == 0 and mt.stdout.split() \
                        else {}
                    for f in todo:
                        # landed if the commit has the branch's content, or merging the branch where the squash was
                        # made gives exactly what it committed (the base's own edits to other lines folded in).
                        # Anything the branch changed beyond it (later work, an unpushed or amended fix) stays held.
                        if at_c.get(f) and (at_c[f] == at_br.get(f) or at_c[f] == at_m.get(f)):
                            same.add(f)
    return same


def _blobs_at(git, rev, files):
    """{file: blob id} at rev for the given project-relative files (one git call)."""
    out = {}
    for e in git("ls-tree", "-r", "-z", rev, "--", *[f"./{f}" for f in sorted(files)]).stdout.split("\x00"):
        meta, _, path = e.partition("\t")
        if path and len(meta.split()) == 3:
            out[path] = meta.split()[2]
    return out


def branch_changes(st, k, warnings=None, unmerged_only=False, tid=None, task=None):
    """tid: a task id or a list of them whose squash commits count as landed (see _landed_files).
    task: this task's id. An earlier owner's branch then does not hold files that only commits for other tasks
    changed (subject starts with another task's id): that thread's other work is not this task's (T29).
    Files changed on the owner's branch vs base ([] when not a git repo or no branch). Problems go to warnings.
    unmerged_only: leave out files that have already landed on the base (done or recalled tasks)."""
    # the current owner's branch, and every earlier owner's: work a handed-over task left unmerged there still counts
    seats = [{**st["threads"][n], "name": n, "branch": branch_of(st, n)}
             for n in dict.fromkeys([k.get("owner") or ""] + list(k.get("past_owners") or [])) if n in st["threads"]]
    repo = st.get("repo", {}).get("path")
    if not seats or not repo:
        return []
    git = _git_cached(repo)
    git_dir = git("rev-parse", "--git-dir")
    if git_dir.returncode != 0:
        if warnings is not None and git_dir.returncode == 127:
            warnings.append("git is not available: real branch diffs are not checked")
        return []
    base = _base_ref(st, git)
    if base is None:
        if warnings is not None:
            warnings.append(f"base branch {st.get('repo', {}).get('base') or 'main'} not found: real branch diffs "
                            "are not checked (fix repo.base)")
        return []
    files, refs, past, current_owner_refs = [], [], set(), set()
    for owner in seats:
        two = [b for b in (owner["branch"], f"origin/{owner['branch']}")
               if git("rev-parse", "--verify", "--quiet", b).returncode == 0]
        if len(two) == 2:  # one is behind the other (pushed WIP, or a stale local copy): only the newer one counts
            if git("merge-base", "--is-ancestor", two[0], two[1]).returncode == 0:
                two = [two[1]]
            elif git("merge-base", "--is-ancestor", two[1], two[0]).returncode == 0:
                two = [two[0]]
            # diverged (rebased, amended, force-pushed, or two sessions each holding work): both copies hold, so
            # work on either side is never dropped; a stale copy stops once it lands, is deleted or pruned
        if task and owner["name"] != k.get("owner") and not set(two) & set(refs):
            past |= set(two)  # the current owner comes first, so a branch it shares is never filtered
        elif task and owner["name"] == k.get("owner"):
            current_owner_refs |= set(two)
        refs += [r for r in two if r not in refs]
    if task:
        lease_ids = {tid for tid, item in st.get("tasks", {}).items()
                     if item.get("status") in LEASE_ACTIVE or item.get("status") in ("done", "recalled")}
    for br in refs:
        r = git("diff", "-z", "--relative", "--name-only", "--no-renames", f"{base}...{br}")  # a rename holds old and new
        if r.returncode != 0 and warnings is not None:
            warnings.append(f"git diff {base}...{br} failed: {r.stderr.strip()[:120]}")
        got = [RealFile(f) for f in _z(r.stdout)]
        if br in past:
            theirs = _other_tasks_only(git, base, br, task, st["tasks"], got)
            got = [f for f in got if f not in theirs]
        elif br in current_owner_refs:
            theirs = _other_tasks_only(git, base, br, task, lease_ids, got)
            got = [f for f in got if f not in theirs]
        if unmerged_only and got:
            gone = _landed_files(git, base, br, got, tid)
            got = [f for f in got if f not in gone]
        files += got
    return [RealFile(f) for f in sorted(set(files))]


def _held_paths(st, warnings=None):
    """{task: paths} held by active tasks (declared + real diff) and by done/recalled tasks (unlanded diff)."""
    held = {}
    for t, k in st["tasks"].items():
        # one branch per thread: what the owner's earlier tasks already landed (merge or squash with their id)
        # is not this task's to hold
        seats = {k.get("owner")} | set(k.get("past_owners") or [])
        landed_ids = [x for x, kx in st["tasks"].items() if kx.get("owner") and kx.get("owner") in seats
                      and kx.get("status") == "done"]
        if k["status"] in LEASE_ACTIVE:
            held[t] = (k.get("touches") or []) + branch_changes(st, k, warnings, unmerged_only=True, tid=landed_ids, task=t)
        elif k["status"] in ("done", "recalled"):
            changed = branch_changes(st, k, warnings, unmerged_only=True, tid=landed_ids, task=t)
            if changed:
                held[t] = changed
    if warnings is not None:
        warnings[:] = list(dict.fromkeys(warnings))
    return held


def plan_ready(st, ready, warnings=None):
    """One pass over the ready tasks in order. A task is held back if its paths overlap what is held (active,
    unlanded, or an earlier task offered in this pass) or it shares a topic with an active task or an earlier
    offered one, always of another owner. Only offered tasks hold paths and topics, so the result is consistent:
    no two offered tasks collide, and nothing held back blocks anyone.
    Returns (offered, blocked_by_lease, blocked_by_topic)."""
    held = _held_paths(st, warnings)
    topics = [(t, k) for t, k in st["tasks"].items() if k["status"] in LEASE_ACTIVE]
    offered, by_lease, by_topic = [], {}, {}
    for t in ready:
        k = st["tasks"][t]
        owner = k.get("owner")
        mine = k.get("touches") or []
        for other, paths in held.items():
            if owner and st["tasks"][other].get("owner") == owner:
                continue  # same thread works sequentially on its own branch
            clash = sorted({p for p in paths for m in mine if paths_overlap(m, p)})
            if clash:
                by_lease.setdefault(t, []).append({"with": other, "owner": st["tasks"][other].get("owner"),
                                                   "status": st["tasks"][other]["status"], "paths": clash})
        mt = set(k.get("topics") or [])
        for other, ko in topics:
            if owner and ko.get("owner") == owner:
                continue
            shared = sorted(mt & set(ko.get("topics") or []))
            if shared:
                by_topic.setdefault(t, []).append({"with": other, "owner": ko.get("owner"), "topics": shared})
        if t in by_lease:
            by_topic.pop(t, None)  # report one reason: the lease
        elif t not in by_topic:
            offered.append(t)
            if mine:
                held[t] = mine
            if mt:
                topics.append((t, k))
    return offered, by_lease, by_topic


def lease_conflicts(st, ready, warnings=None):
    """blocked_by_lease part of plan_ready (kept for callers that only need leases)."""
    return plan_ready(st, ready, warnings)[1]


def norm_topics(s):
    """'Request Ledger, request_ledger , mechanism' -> ['request-ledger', 'mechanism']"""
    return list(dict.fromkeys(re.sub(r"[\s_]+", "-", x.strip().lower()) for x in csv(s) if x.strip()))


PASSING = ("pass", "capped")  # capped: the round limit was reached with no blocking finding and checks passing

# Central invalidation matrix: the event that changed task validity and the records it voids.
INVALIDATION_MATRIX = {
    "working": ("primary", "review"), "review-fail": ("primary",),
    # owner: not here on purpose. A new owner changes neither the artifact nor the reviewed diff;
    # the existing rule (void only when the reviewer becomes the owner, T23) stays in cmd_task.
    "verify": ("review",), "primary": ("primary", "review"), "env-down": ("review",),
    "redispatch": ("primary", "review"),
    "base": ("review",), "accept": ("review",), "replace": ("review",), "checks": ("review",),
}


def invalidate(k, changes, st):
    """Apply all evidence/review invalidations from the module-level matrix."""
    invalid = {record for change in changes for record in INVALIDATION_MATRIX.get(change, ())}
    why = {"working": lab(st, "invalidate_working"), "review-fail": lab(st, "invalidate_review_fail"),
           "verify": lab(st, "invalidate_verify"), "primary": lab(st, "invalidate_primary"),
           "owner": lab(st, "invalidate_owner"), "base": lab(st, "invalidate_base"), "accept": lab(st, "invalidate_accept"),
           "replace": lab(st, "invalidate_replace"), "checks": lab(st, "invalidate_checks"),
           "env-down": lab(st, "invalidate_env_down"), "redispatch": lab(st, "invalidate_redispatch")}
    if "primary" in invalid and k.get("primary_check"):
        k.setdefault("past_primary_checks", []).append(k.pop("primary_check"))
    if "review" in invalid and k.get("review"):
        old = k.pop("review")
        k.setdefault("past_reviews", []).append({**old, "voided": "; ".join(why[x] for x in changes if x in why)})
        return old
    return None


def return_to_working(k, why, st):
    """Apply the shared rework transition and invalidate the evidence tied to the old artifact."""
    failed_review = k.pop("review", None) if (k.get("review") or {}).get("result") == "fail" else None
    k["status"] = "working"
    k["checks"] = "none"
    k.pop("merged_at", None)
    k.pop("merged_sha", None)
    k["rework"] = k.get("rework", 0) + 1
    k.setdefault("rework_at", []).append(now())
    k["rework_reason"] = why
    invalidate(k, ["working"], st)
    if failed_review:
        k["review"] = failed_review


def check_task_invariants(st, tid, before, k, a, said, changes):
    """Run registered gates for the operation's actual changes, once before save."""
    for gate in TASK_GATES:
        reason = gate(st, tid, before, k, changes, a, said)
        if reason: sys.exit(reason)
    return changes.get("primary_waivers", [])


def review_max(st):
    v = pref(st, 'review_max_rounds')
    return v if isinstance(v, int) and not isinstance(v, bool) and 0 <= v <= 99 else PREFS["review_max_rounds"]["default"]


def accept_gate(st, tid, before=None, k=None, changes=None, a=None, said=""):
    reason = _done_gate_reason(st, tid, before, k, changes, a, said)
    if reason:
        if before is None and k is None and changes is None and a is None:
            for text, legacy in (("checks failed;", "has failing checks"), ("has no owner:", "has no owner"),
                                 ("no passing review yet.", "has no passing independent review yet"),
                                 ("capped at the round limit,", "was capped at the round limit, which needs checks passing")):
                if text in reason: return legacy
            if " reviewer " in reason and " owns it" in reason:
                return f"was reviewed by its own owner ({(k or st['tasks'][tid]).get('review', {}).get('reviewer')})"
        return reason
    if (changes or {}).get("status_to") == "done":
        rv = (k or st["tasks"][tid]).get("review") or {}
        if (k or st["tasks"][tid]).get("primary_suspect") and rv.get("result") in PASSING and not rv.get("suspect_cleared"):
            return lab(st, "primary_suspect_gate")


TASK_GATES.append(accept_gate)


def reviewer_independent(reviewer, owner):
    """The owner itself (any spelling: 'UI', './ui/', 'ui thread') is not independent; 'ui/subagent' is."""
    rv, ow = norm_reviewer(reviewer), (owner or "").strip().lower()
    if not ow:
        return True
    if rv in ("", ".", "self") or rv == ow:
        return False
    if "/" in rv:
        return True
    tok = lambda x: [w for w in re.split(r"[^a-z0-9]+", x) if w]
    rt, ot = tok(rv), tok(ow)  # 'ui-thread', 'the ui', 'research-2:self' = the owner (its words as one run)
    return not ot or not any(rt[i:i + len(ot)] == ot for i in range(len(rt) - len(ot) + 1))


def norm_reviewer(x):
    import posixpath
    value = (x or "").strip().lower()
    if "/" in value:
        base, suffix = value.split("/", 1)
        suffix = suffix.strip("/")
        if suffix not in {"subagent", "review"}:
            value = base
    normalized = posixpath.normpath(value or ".").strip("/")
    return "" if normalized in ("", ".", "self") else normalized


def roster_stale(st):
    """Live threads that have not been sent the newest ROSTER."""
    v = st.get("roster_version", 0)
    return [n for n, t in st["threads"].items()
            if t.get("session_id") and t["status"] not in ("planned", "resolved", "archived")
            and t.get("roster_seen", 0) < v]


def bump_roster(st, name=None):
    st["roster_version"] = st.get("roster_version", 0) + 1
    if name:  # a thread created now gets the current roster in its worker prompt
        st["threads"][name]["roster_seen"] = st["roster_version"]


def _minutes_since(ts):
    try:
        t = dt.datetime.fromisoformat(ts)
        cur = _now_dt()
        if t.tzinfo is None:  # an old or hand-edited stamp: read it in the clock's zone
            t = t.replace(tzinfo=cur.tzinfo)
        return max(0, int((cur - t).total_seconds() // 60))
    except (TypeError, ValueError):
        return None


def merge_waiting(st):
    """IL-3: tasks in review with a passing or capped verdict, not merged yet, oldest first."""
    out = []
    for t, k in st["tasks"].items():
        rv = k.get("review") or {}
        if k.get("status") == "review" and rv.get("result") in PASSING:
            out.append({"task": t, "owner": k.get("owner"), "branch": (st["threads"].get(k.get("owner") or "") or {})
                        .get("branch"), "minutes": _minutes_since(rv.get("at") or k.get("created"))})
    return sorted(out, key=lambda x: -(x["minutes"] or 0))


def merge_overdue(st):
    limit = pref(st, 'stuck_minutes')
    w = merge_waiting(st)
    return bool(limit and w and (w[0]["minutes"] or 0) > limit)


def task_model(st, t):
    k = st["tasks"][t]
    m = k.get("model") or (st["threads"].get(k.get("owner") or "") or {}).get("model") or ""
    return " ".join(x for x in (m, "(by hand, no scripts)" if k.get("no_scripts") else "") if x)


def urgent_unacked(st):
    """E8: urgent tasks still not acked (status dispatched) past their minutes: recall and reassign."""
    limit = pref(st, 'urgent_ack_minutes')
    return [{"task": tid, "minutes": _minutes_since(k.get("dispatched_at")), "advice": lab(st, "urgent_advice")}
            for tid, k in st.get("tasks", {}).items()
            if k.get("urgent") and k.get("status") == "dispatched" and k.get("dispatched_at")
            and (_minutes_since(k.get("dispatched_at")) or 0) > k.get("urgent_minutes", limit)]


def _cmd_ready(a):
    d = need(find_dir())
    st = load(d)
    pending_hints=st.pop("screen_pending_hints",[])
    for hint in pending_hints: print(hint.get("line", ""), file=sys.stderr)
    if pending_hints: save(d,st,{"ev":"screen-hints-shown"})
    sprint = st.get("sprint") or {}
    if sprint and not sprint.get("ended_at") and _when(sprint.get("until")) and _when(sprint.get("until")) <= _when(now()):
        cmd_sprint(argparse.Namespace(action="end", since=None, json=False, until=None, goal=None, _from_ready=True))
        st = copy.deepcopy(_READY_SAVE_BATCH["state"])
    if apply_thread_defaults(st): save(d, st, {"ev": "thread-defaults"})
    urgent = urgent_unacked(st)
    ack_missing = []
    for name, thread in st.get("threads", {}).items():
        if thread.get("status") in ("working", "starting") and thread.get("session_id"):
            ackline = str(thread.get("ack_line") or "")
            current_tasks = [tid for tid, task in st.get("tasks", {}).items()
                             if task.get("owner") == name and task.get("status") in ("dispatched", "working", "blocked", "review")]
            ack_task = re.search(r"\bACK\s+\S+\s*->\s*\S+\s+(T\d+(?:-f\d+)*)", ackline, re.I) or re.search(r"(?im)^\s*task:\s*(T\d+(?:-f\d+)*)", ackline)
            if not ackline or not re.search(r"已有\s*[：:]", ackline) or current_tasks and (not ack_task or ack_task.group(1) not in current_tasks):
                ack_missing.append(name)
    if ack_missing: print(lab(st, "ready_ack_missing", threads=", ".join(ack_missing)), file=sys.stderr)
    done = {t for t, k in st["tasks"].items() if k["status"] == "done"}
    busy = sum(
        1 for t in st["threads"].values() if t["status"] in ("starting", "working")
    )
    ready = [
        t
        for t, k in st["tasks"].items()
        if k["status"] == "approved" and set(k.get("deps", [])) <= done
    ]
    lease_warnings = []
    ready, blocked, by_topic = plan_ready(st, ready, lease_warnings)
    route_status = {t: _task_dispatch_model(st, t) for t in ready}
    for task, info in route_status.items():
        if info and info.get("status"):
            lease_warnings.append(f"{task}: {info['status']}")
    to_open = {st["tasks"][tid].get("owner") for tid in ready
               if st["tasks"][tid].get("owner") and not (st.get("threads", {}).get(st["tasks"][tid].get("owner"), {}).get("session_id"))}
    desktop_line = None
    if st.get("lead", {}).get("desktop") and to_open:
        queued = sorted(set(st.get("desktop_open_queue", [])) | to_open)
        if queued != st.get("desktop_open_queue", []):
            st["desktop_open_queue"] = queued
            save(d, st, {"ev": "desktop-open-queue", "threads": queued})
        desktop_line = lab(st, "desktop_open", threads=", ".join(sorted(to_open)))
        print(desktop_line, file=sys.stderr)
    notice = (model_lab(st, "ready_notice", n=len(to_open)) if len(to_open) >= 2 else None)
    if notice:
        print(notice, file=sys.stderr)
    pending_screens = [(sid,x) for sid,x in st.get("screens", {}).items() if x.get("status") in ("asked", "unscored") and not x.get("graded_at")]
    local_screens=[]; cloud_screens=[]
    for sid,rec in pending_screens:
        _, found = _session_rows(rec.get("session_id")) if rec.get("session_id") else ([],False)
        (local_screens if found else cloud_screens).append((sid,rec))
    pending_compacts=[(seat,rec) for seat,rec in (st.get("compactions") or {}).items() if not (st.get("signals",{}).get(seat) or {}).get("compact_check",{}).get("answered")]
    local_compacts=[(seat,rec) for seat,rec in pending_compacts if rec.get("session") and _session_rows(rec.get("session"))[1]]
    waiting_screens = len(local_screens)+len(local_compacts)
    if pref(st, 'screen_autograde'):
        for sid,rec in cloud_screens:
            print(lab(st,"signals_cloud_grade",screen=sid,seat=rec.get("seat")),file=sys.stderr)
    if waiting_screens and pref(st, 'screen_autograde'):
        private_tmp=d/"private"/"lead"/"tmp"; private_tmp.mkdir(parents=True,exist_ok=True)
        logfile=(private_tmp/"screen-sweep.log").open("ab")
        try:
            subprocess.Popen([sys.executable,str(Path(__file__).resolve()),"screen","sweep"],cwd=d,
                             stdin=subprocess.DEVNULL,stdout=logfile,stderr=logfile,start_new_session=True)
            print(lab(st,"signal_waiting_grades",n=waiting_screens),file=sys.stderr)
        except OSError:
            logfile.close()
            raise
        else: logfile.close()
    trigger = quota_trigger_hint(st)
    if trigger:
        print(quota_trigger_line(st, trigger), file=sys.stderr)
    nested_sessions, nested_gaps = _nested_session_report(d, st)
    for row in nested_sessions:
        relation = ("lead" if row.get("parent_is_lead") else
                    "former lead" if row.get("parent_was_lead") else
                    str(row.get("parent_session_id") or "unknown parent"))
        print(f"nested desktop child session: {row.get('session_id')} (parent: {relation})", file=sys.stderr)
    if any(row.get("parent_is_lead") for row in nested_sessions):
        print("这些子会话挂在 lead 下面：别归档 lead；改用 create_session 重开对应线程 / "
              "These child sessions are nested under the lead: do not archive the lead; reopen their threads with create_session",
              file=sys.stderr)
    if any(row.get("parent_was_lead") for row in nested_sessions):
        print("这些子会话挂在前任 lead 下面 / These child sessions are nested under a former lead",
              file=sys.stderr)
    if nested_gaps:
        print(f"嵌套会话检查缺口：{nested_gaps} 份桌面会话元数据 JSON 无法读取 / "
              f"Nested-session scan gap: skipped {nested_gaps} unreadable desktop session metadata file(s)", file=sys.stderr)
    sweep_trigger = sweep_trigger_hint(st, bool(ready))
    if sweep_trigger:
        print(lab(st, "sweep_trigger_" + sweep_trigger, id=st["prefs"]["sweep_trigger_id"]), file=sys.stderr)
    pace_tier = quota_pace_tier(st)[0]
