def _disk_fixture():
    path = os.environ.get("TEAMWORK_HEALTH_FIXTURE")
    if not path: return {}
    try: return json.loads(Path(path).read_text(encoding="utf-8"))
    except (OSError, ValueError): return {}


def _disk_blocks(info): return int(getattr(info, "st_blocks", 0)) * 512


def _disk_stamp(): return dt.datetime.now().astimezone().isoformat(timespec="microseconds")


def _disk_frame(path): return {"path": str(path), "names": [], "index": 0, "listing_offset": 0, "listed": False}


def _disk_seed(path, deadline=None):
    """Start with the root block; directory contents are enumerated incrementally."""
    root = Path(path)
    try:
        info = root.lstat()
        if stat.S_ISLNK(info.st_mode) or not stat.S_ISDIR(info.st_mode): return None
    except OSError: return None
    row = {"bytes": _disk_blocks(info), "complete": False, "measured_at": None, "updated_at": _disk_stamp(), "device": int(info.st_dev), "stack": [], "signature_chain": hashlib.sha256(f"{root}\0{info.st_mode}\0{info.st_size}\0{info.st_mtime_ns}\0{info.st_ino}".encode()).hexdigest()}
    row["stack"].append(_disk_frame(root)); return row


def _disk_measure_step(path, row, deadline):
    """Advance one persistent scandir frame; return true when this tree is complete."""
    deadline = _DiskDeadline(deadline)
    if row.get('complete'): return True
    stack = row.setdefault("stack", []); processed = 0
    while stack and not deadline.over():
        frame = stack[-1]
        if not frame.get("listed"):
            try:
                with os.scandir(frame['path']) as entries: frame["names"] = sorted(entry.name for entry in entries); frame["listing_offset"] = len(frame["names"]); frame["listed"] = True
            except OSError: row["unreadable"] = True; stack.pop()
            if not frame.get('listed'): break
            if deadline.over(): break
        if frame['index'] >= len(frame['names']): stack.pop(); continue
        name = frame["names"][frame["index"]]; frame["index"] += 1; processed += 1; child = Path(frame["path"]) / name
        try:
            info = child.lstat()
            if info.st_dev != int(row['device']) or stat.S_ISLNK(info.st_mode): row["updated_at"] = _disk_stamp(); break
            row["bytes"] = int(row.get("bytes", 0)) + _disk_blocks(info); prior=row.get("signature_chain",""); row["signature_chain"]=hashlib.sha256(f"{prior}\0{child}\0{info.st_mode}\0{info.st_size}\0{info.st_mtime_ns}\0{info.st_ino}".encode()).hexdigest()
            if stat.S_ISDIR(info.st_mode): stack.append(_disk_frame(child))
        except OSError: row["updated_at"] = _disk_stamp(); break
        row["updated_at"] = _disk_stamp()
        if processed >= 1: break
    if not stack and (not row.get('unreadable')): row["complete"] = True; row["measured_at"] = _disk_stamp(); row["updated_at"] = row["measured_at"]; row["cached_bytes"] = int(row.get("bytes", 0)); row["cached_at"] = row["measured_at"]
    return bool(row.get("complete"))


def _disk_cached_value(row):
    if not isinstance(row, dict): return None, None
    if row.get('complete'): return int(row.get("bytes", 0)), row.get("measured_at")
    if row.get('cached_bytes') is not None: return int(row["cached_bytes"]), row.get("cached_at")
    if row.get('bytes') is not None: return int(row["bytes"]), row.get("updated_at")
    return None, None


def _disk_refresh(paths, cache, budget_s, seed_paths=(), priority_paths=()):
    deadline = _DiskDeadline.after(budget_s)
    """Round-robin the oldest measurements until the wall-clock budget is consumed."""
    deadline = _DiskDeadline.after(budget_s); wanted=[]; seen=set()
    for path in paths:
        if deadline.over(): break
        key=str(Path(path))
        if key not in seen: seen.add(key); wanted.append(key)
    seeds=set(); priority={}
    for path in seed_paths:
        if deadline.over(): break
        seeds.add(str(Path(path)))
    for index,path in enumerate(priority_paths):
        if deadline.over(): break
        priority[str(Path(path))]=index
    for key in wanted:
        if deadline.over(): break
        path = Path(key)
        if not path.exists() or path.is_symlink(): continue
        row = cache.get(key)
        if not isinstance(row, dict):
            row = _disk_seed(path, deadline) if key in seeds else None
            if row is None:
                try: info = path.lstat(); row = {"bytes": _disk_blocks(info), "complete": False, "measured_at": None, "updated_at": _disk_stamp(), "device": int(info.st_dev), "stack": [], "signature_chain": hashlib.sha256(f"{path}\0{info.st_mode}\0{info.st_size}\0{info.st_mtime_ns}\0{info.st_ino}".encode()).hexdigest()}; row["stack"].append(_disk_frame(path))
                except OSError: continue
            cache[key] = row
        elif row.get("complete"):
            try:
                if row.get('measured_at') and time.time() - dt.datetime.fromisoformat(row['measured_at']).timestamp() < 300: continue
            except (ValueError, TypeError): pass
            seeded = _disk_seed(path, deadline); row["cached_bytes"] = int(row.get("bytes", 0)); row["cached_at"] = row.get("measured_at"); row["stack"] = seeded.get("stack", []) if seeded else []; row["bytes"] = int(seeded.get("bytes", 0)) if seeded else 0; row["complete"] = False
            if seeded: row["device"] = int(seeded["device"]); row["signature_chain"] = seeded.get("signature_chain")
            row["updated_at"] = _disk_stamp()
    keys=[]
    for key in wanted:
        if deadline.over(): break
        if isinstance(cache.get(key), dict) and (not cache[key].get('complete')) and (cache[key].get('stack') or not cache[key].get('unreadable')): keys.append(key)
    while keys and not deadline.over():
        keys.sort(key=lambda key: (0 if _disk_cached_value(cache[key])[0] is None else 1, priority.get(key, len(priority)), cache[key].get("measured_at") or cache[key].get("cached_at") or cache[key].get("updated_at") or ""))
        advanced = False
        for key in keys[:]:
            if deadline.over(): break
            _disk_measure_step(key, cache[key], deadline); advanced = True
            if cache[key].get('complete'): keys.remove(key)
        if not advanced: break
    return cache



def _disk_rank(home, cache, count, budget_s, deadline=None, du_budget=None, known_paths=()):
    if deadline is not None: deadline = _DiskDeadline(deadline)
    home = Path(home); library = home / "Library"; scratch = home / ".dev-scratch"; known = [scratch / name for name in ("backups", "tmp", "cache")]
    known += [library / "Caches", home / "Library/Developer/CoreSimulator/Devices", home / "Library/Developer/Xcode/DerivedData", home / "Library/Developer/Xcode/iOS DeviceSupport", home / ".npm", home / ".codex"]
    for path in home.glob(".claude*"):
        if deadline is not None and deadline.over(): break
        known.append(path)
    for path in known_paths:
        if deadline is not None and deadline.over(): break
        known.append(path)
    try:
        for p in home.iterdir():
            if deadline is not None and deadline.over(): break
            if p.is_dir() and (not p.is_symlink()) and (p.name.endswith('-worktrees') or any(p in Path(k).parents for k in known_paths)): known.append(p)
    except OSError: pass
    valid=[]; seen=set()
    for value in known:
        if deadline is not None and deadline.over(): break
        path=Path(value)
        if path != Path('/') and str(path) not in seen and path.is_dir() and (not path.is_symlink()): seen.add(str(path)); valid.append(path)
    known=valid; seed_paths = set(str(p) for p in known); _disk_refresh(known, cache, budget_s, seed_paths, known); rows=[]
    for path,row in cache.items():
        if isinstance(row,dict) and Path(path).exists() and not Path(path).is_symlink():
            value,_stamp=_disk_cached_value(row)
            if value is not None: rows.append((value,path))
    present={path for _size,path in rows}; rows.extend((None,str(path)) for path in known if str(path) not in present and path.exists() and not path.is_symlink()); rows.sort(key=lambda item:(item[0] is not None,item[0] if item[0] is not None else -1,item[1]),reverse=True); partial = any(not cache[str(p)].get("complete") for p in known if str(p) in cache)
    if deadline is not None and deadline.over(): partial = True
    if du_budget is not None: du_budget["rank_measured"] = [str(p) for p in known if cache.get(str(p), {}).get("complete")]; du_budget["rank_unmeasured"] = [str(p) for p in known if not cache.get(str(p), {}).get("complete")]
    chosen=[]; limit=max(0,int(count))
    if limit == 0: return [],partial
    simulator_root=str(home / "Library/Developer/CoreSimulator/Devices"); measured_paths={path for _size,path in rows}
    for size,path in rows:
        if path.startswith(simulator_root + '/'): continue
        if any((path.startswith(candidate.rstrip('/') + '/') for candidate in measured_paths if candidate != path)): continue
        if any((path.startswith(parent.rstrip('/') + '/') for _n, parent in chosen)): continue
        chosen.append((size,path))
        if len(chosen) >= limit: break
    return chosen, partial


def _disk_measure(path, row, value=None, st=None):
    if value is None: value, stamp = _disk_cached_value(row)
    else: _, stamp = _disk_cached_value(row)
    complete=bool(isinstance(row,dict) and row.get("complete")); age=max(0,int(time.time()-dt.datetime.fromisoformat(stamp).timestamp())) if stamp else None; chain=row.get("signature_chain") if isinstance(row,dict) else None
    if chain:
        try: info=Path(path).lstat(); fingerprint=hashlib.sha256(f"{path}\0{value}\0{chain}\0{info.st_mode}\0{info.st_mtime_ns}\0{info.st_ino}".encode()).hexdigest()[:24]
        except OSError: fingerprint="unreadable"
    else:
        try: info=Path(path).lstat(); fingerprint=hashlib.sha256(f"{path}\0{value}\0{info.st_mode}\0{info.st_mtime_ns}\0{info.st_ino}\n".encode()).hexdigest()[:24]
        except OSError: fingerprint="unreadable"
    return {"bytes":int(value) if value is not None else None,"complete":complete,"age":age, "display":("" if complete else "≥ ")+_disk_human(value) if value is not None else lab(st or {},"disk_unmeasured"),"fingerprint":fingerprint}


def _disk_human(n):
    n = float(max(0, n))
    for unit in ("B", "KiB", "MiB", "GiB", "TiB"):
        if n < 1024 or unit == 'TiB': return f"{n:.1f} {unit}"
        n /= 1024


def _disk_duration(seconds):
    if seconds is None: return "unknown"
    seconds=max(0,int(seconds)); hours,minutes=divmod(seconds,3600)[0],divmod(seconds,3600)[1]//60; return f"{hours}h {minutes}m" if hours else f"{minutes}m"


def _disk_pipe_capacity():
    read_fd, write_fd = os.pipe(); total = 0
    try:
        os.set_blocking(write_fd, False); chunk = b"x" * 65536
        while True:
            try: total += os.write(write_fd, chunk)
            except BlockingIOError: break
        return total
    finally: os.close(read_fd); os.close(write_fd)


def _disk_elapsed(start_time):
    value = str(start_time or "")
    for fmt in ("%a %b %d %H:%M:%S %Y",):
        try: started = dt.datetime.strptime(value, fmt).astimezone()
        except ValueError: continue
        return max(0.0, time.time() - started.timestamp())
    try:
        started = dt.datetime.fromisoformat(value.replace("Z", "+00:00"))
        if started.tzinfo is None: started = started.astimezone()
        return max(0.0, time.time() - started.timestamp())
    except ValueError: return None


def _disk_cmd_args(cmdline):
    try: return shlex.split(str(cmdline))
    except ValueError: return str(cmdline).split()


def _disk_option(cmdline, name):
    args=_disk_cmd_args(cmdline)
    return next((args[i+1] if value==name else value.split("=",1)[1] for i,value in enumerate(args[:-1]) if value==name or value.startswith(name+"=")),None)


def _disk_process_app_servers(rows, prefs, deadline=None):
    if deadline is not None: deadline = _DiskDeadline(deadline)
    by_pid={}; children_by_ppid={}
    for row in rows:
        if deadline is not None and deadline.over(): break
        if not isinstance(row, dict): continue
        pid=int(row.get("pid",0)); by_pid[pid]=row; children_by_ppid.setdefault(int(row.get("ppid",0)),[]).append(row)
    servers = []; idle_after = float(_pref_in(prefs,"health_app_server_idle_hours")) * 3600
    for server in rows:
        if deadline is not None and deadline.over(): break
        if not isinstance(server, dict): continue
        cmd = str(server.get("cmdline", server.get("command", "")))
        if not re.search('(?:^|[/\\s])codex\\s+app-server(?:\\s|$)', cmd): continue
        pid = int(server.get("pid", 0)); descendants=[]; seen={pid}; frontier={pid}
        while frontier:
            if deadline is not None and deadline.over(): break
            direct=[]
            for parent_pid in frontier:
                if deadline is not None and deadline.over(): break
                for child in children_by_ppid.get(parent_pid,[]):
                    child_pid=int(child.get("pid",0))
                    if child_pid not in seen: seen.add(child_pid); direct.append(child)
            descendants.extend(direct); frontier={int(r.get("pid", 0)) for r in direct}
        children = descendants; repl = [r for r in children if re.search(r"node_repl", str(r.get("cmdline", r.get("command", ""))), re.I)]; active = [r for r in children if r not in repl]; parent = by_pid.get(int(server.get("ppid", 0)), {}); broker_cmd = str(parent.get("cmdline", parent.get("command", "")))
        if 'app-server-broker.mjs' not in broker_cmd: broker_cmd = ""
        cwd = _disk_option(broker_cmd, "--cwd") if broker_cmd else None; pid_file = _disk_option(broker_cmd, "--pid-file") if broker_cmd else None; broker_dir = Path(pid_file).parent if pid_file else None
        if broker_dir is None and broker_cmd:
            args = _disk_cmd_args(broker_cmd); script = next((arg for arg in args if "app-server-broker.mjs" in arg), None)
            if script: broker_dir = Path(script).parent
        if broker_dir is None and cwd: broker_dir = Path(cwd) / ".teamwork"
        job_running = None
        if broker_dir and broker_dir.is_dir():
            for pattern in ("*.json", "**/*.json"):
                for status_file in broker_dir.glob(pattern):
                    if deadline is not None and deadline.over(): break
                    try:
                        payload = json.loads(status_file.read_text(encoding="utf-8")); states = []
                        def collect(value):
                            if deadline is not None and deadline.over(): return
                            if isinstance(value, dict):
                                if 'status' in value: states.append(str(value["status"]).lower())
                                for item in value.values(): collect(item)
                            elif isinstance(value, list):
                                for item in value: collect(item)
                        collect(payload)
                        if 'running' in states: job_running = True; break
                        if states: job_running = False
                    except (OSError, ValueError): continue
                if job_running is True or (deadline is not None and deadline.over()): break
        log_times = []
        if broker_dir and broker_dir.is_dir():
            try:
                for pattern in ("**/*.jsonl", "**/*.log"):
                    for log_path in broker_dir.glob(pattern):
                        if deadline is not None and deadline.over(): break
                        try: log_times.append(log_path.stat().st_mtime)
                        except OSError: pass
            except OSError: pass
        last_log_age = max(0.0, time.time() - max(log_times)) if log_times else None; idle_processes = not active; idle_status = job_running is False; idle = (idle_processes or idle_status) and last_log_age is not None and last_log_age >= idle_after; repl_ages = [age for age in (_disk_elapsed(r.get("start_time")) for r in repl) if age is not None]
        servers.append({"broker_pid": int(parent.get("pid", 0)) if broker_cmd else None, "broker_cmdline": broker_cmd, "broker_start_time": str(parent.get("start_time", "")) if broker_cmd else "", "broker_dir": str(broker_dir) if broker_dir else None, "app_server_pid": pid, "app_server_cmdline": cmd, "app_server_start_time": str(server.get("start_time", "")), "app_server_age_s": _disk_elapsed(server.get("start_time")), "node_repl_count": len(repl), "node_repl_longest_s": max(repl_ages) if repl_ages else None, "node_repl_median_s": statistics.median(repl_ages) if repl_ages else None, "worktree": cwd, "active_child_pids": [int(r.get("pid", 0)) for r in active], "job_running": job_running, "last_log_age_s": last_log_age, "idle": bool(idle)})
    return servers


def _disk_pipe_holders(fixture=None, deadline=None, budget_s=3.0):
    if deadline is not None: deadline = _DiskDeadline(deadline)
    if isinstance(fixture, list): return fixture[:5], ("fixture returned no holders" if not fixture else None)
    tool=shutil.which("lsof")
    if not tool: return [], "lsof is unavailable"
    try:
        timeout=max(.01,float(budget_s)); raw_result=subprocess.run([tool, "-nP", "-Fpcft"], capture_output=True, text=True, timeout=timeout)
        if raw_result.stderr and any((term in raw_result.stderr.lower() for term in ('permission', 'operation not permitted'))): return [], "no permission: " + raw_result.stderr.strip()[:120]
        if raw_result.returncode not in (0, 1): reason=(raw_result.stderr or "lsof exited with status %s" % raw_result.returncode).strip(); return [], "no permission" if "permission" in reason.lower() or "operation not permitted" in reason.lower() else "lsof failed: " + reason[:160]
        raw=raw_result.stdout
    except subprocess.TimeoutExpired: return [], "timed out after %.1f seconds" % timeout
    except PermissionError: return [], "no permission"
    except (OSError, subprocess.SubprocessError) as exc: return [], "lsof failed: " + str(exc)[:160]
    counts = {}; current_pid = None; current_name = "?"; pipe_fd = False
    for line in raw.splitlines():
        if deadline is not None and deadline.over(): break
        if not line: continue
        tag, value = line[0], line[1:]
        if tag == 'p': current_pid = value; current_name = "?"
        if tag == 'c': current_name = value
        if tag == 'f': pipe_fd = False
        if tag == 't': pipe_fd = value.upper() in ("FIFO", "PIPE")
        if tag == 't' and pipe_fd and current_pid: key = (current_pid, current_name); counts[key] = counts.get(key, 0) + 1
    try: holders=[{"pid": int(pid), "name": name, "pipes": count} for (pid, name), count in sorted(counts.items(), key=lambda item: item[1], reverse=True)[:5]]
    except (TypeError, ValueError): return [], "parse failed: invalid process id"
    saw_type=any(line.startswith("t") for line in raw.splitlines()); reason=None if holders else ("parse failed: no file-type records" if raw.strip() and not saw_type else "lsof found no pipe holders"); return holders, reason


def _disk_health(st, deadline=None, fixture=None):
    if deadline is not None: deadline = _DiskDeadline(deadline)
