def _disk_expand_rules(rules, deadline, add):
    for root, category, keep in rules:
        try:
            for path in root:
                if deadline.over(): return
                try:
                    if keep(path): add(path, category)
                except OSError: continue
        except OSError: pass


def _disk_stale(path, cutoff, deadline):
    """Old only when nothing in the whole tree changed since cutoff (not just the top folder). A checkout or
    worktree (any session's) or a ledger inside is never stale; unsure means not stale."""
    stack = [Path(path)]
    try:
        while stack:
            top = stack.pop(); info = top.lstat()
            if deadline.over() or info.st_mtime >= cutoff: return False
            if stat.S_ISDIR(info.st_mode):
                with os.scandir(top) as entries:
                    for entry in entries:
                        if entry.name in (".git", ".teamwork") or deadline.over(): return False
                        stack.append(Path(entry.path))
    except OSError: return False
    return True


