OPENING_DEFAULTS = {"perm_policy": "managed", "gpt_policy": "yes"}
OPENING_RECOMMENDED = {"spawn_policy": 2, "perm_policy": 2, "gpt_policy": 2}  # index into each scale
OPENING_CHANGE = {"spawn_policy": "ask", "perm_policy": "ask", "gpt_policy": "no"}  # the example value in the change line


def policy(st, key):
    """The policy in force: the user's answer, else the recommended default (spawn_policy has none)."""
    value = pref(st, key)
    return value or OPENING_DEFAULTS.get(key, value)


def _trial_cause(st, trial):
    scores = trial.get("scores") or {}
    if trial.get("veto") or scores.get("P5") == 0:
        return lab(st, "relead_cause_veto")
    low = [key for key in sorted(scores) if scores[key] == min(scores.values(), default=2)]
    return lab(st, "relead_cause_low", items=", ".join(low[:3])) if low and len(low) < len(scores) else ""


def opening_data(d, st):
    answers = []
    for folder in find_projects(d.parent.parent):  # the other projects under the same served folder
        if folder.resolve() == d.parent.resolve():
            continue
        try:
            other = json.loads((folder / ".teamwork" / "state.json").read_text(encoding="utf-8"))
            for key, record in (pref(other, 'policy_said') or {}).items():
                if key in OPENING and record.get("text"):
                    answers.append((record.get("at", ""), key, pref(other, key), record["text"]))
        except (OSError, ValueError, TypeError, AttributeError):  # another project's broken state is skipped
            continue
    rows = []
    zh = _zh(st)
    for key, (question, scale, costs, _) in OPENING.items():
        if zh: question, scale, costs = OPENING_ZH[key]
        prior = max((x for x in answers if x[1] == key), key=lambda x: (str(x[0]), str(x[2]), str(x[3])), default=None)
        rows.append({"key": key, "question": question, "scale": [{"step": s, "cost": c} for s, c in zip(scale, costs)],
                     "current": pref(st, key) or None,
                     "last": ({"value": prior[2], "text": prior[3], "at": prior[0]} if prior else None),
                     **({"default": policy(st, key)} if key in OPENING_DEFAULTS else {}),
                     "recommended": OPENING_RECOMMENDED[key],
                     "change": lab(st, "opening_change", pref=key, value=OPENING_CHANGE[key]),
                     "never_default": False})
    thread_screens = {n: _screen_label(st, n) for n in st.get("threads", {}) if _screen_label(st, n)}
    started_statuses = set(TASK_STATUSES[TASK_STATUSES.index("approved") + 1:]) - {"dropped", "recalled"}
    started = any(task.get("status") in started_statuses for task in st.get("tasks", {}).values()) \
        and not st.get("lead_trials")  # a relead chain still screens its new lead
    return {"started": started, "questions": rows, "thread_screens": thread_screens,
            "unanswered_now": [k for k in OPENING if not pref(st, k)],
            "defaults_in_effect": {k: policy(st, k) for k in OPENING_DEFAULTS if not pref(st, k)},
            "rule": lab(st, "opening_rule")}


def cmd_opening(a):
    d = need(find_dir()); st = load(d)
    if getattr(a, "takeover", False):
        result = _takeover_data(st)
        if a.json: print(json.dumps(result, ensure_ascii=False))
        else: print("\n".join(result["lines"]))
        return
    result = opening_data(d, st)
    started = result.pop("started", False)  # a running project: the questions still show, no new screen is made
    result["gpt_private_question"] = model_lab(st, "gpt_private_question")
    if st.get("lead", {}).get("permission_mode") == "auto": result["managed_note"] = model_lab(st, "auto_note")
    result["lead_screen"] = _lead_existing_screen_status(st) if started else _lead_opening_screen(d, st)
    if a.json:
        print(json.dumps(result, ensure_ascii=False))
    else:
        ls = result["lead_screen"]
        if ls.get("status") == "asked" and ls.get("message"):  # the questions come first: this turn answers them
            print(ls["message"])
            print(lab(st, "lead_screen_howto", screen=ls["screen"]))
        elif ls.get("screen"):
            print(lab(st, "lead_screen_status", screen=ls["screen"], status=ls["status_label"]))
        elif ls.get("status") == "no_session":
            print(lab(st, "lead_screen_no_session"))
        for row in result["questions"]:
            print(f"{row['key']}: {row['question']}")
            for n, step in enumerate(row["scale"], 1):
                print(f"  {n}. {step['step']} — {step['cost']}" + (lab(st, "opening_recommended") if n - 1 == row["recommended"] else ""))
            last = row["last"]
            print(lab(st, "opening_current", current=row["current"] or lab(st, "opening_unset"),
                      last=lab(st, "opening_last", value=last["value"], text=last["text"]) if last else lab(st, "opening_no_last")))
            print("  " + row["change"])
        print(result["gpt_private_question"])
        if result.get("managed_note"): print(result["managed_note"])
        print(lab(st, "opening_unanswered_list", keys=lab(st, "language_list_sep").join(result["unanswered_now"]))
              if result["unanswered_now"] else lab(st, "opening_all_answered"))
        for name, status in result["thread_screens"].items(): print(f"{name}: {status}")
        print(result["rule"])


def _lead_opening_screen(d, st):
    """The lead's own opening screen: made once per lead session, afterwards only reported."""
    sid = ((st.get("lead") or {}).get("session_id") or "").strip()
    attempt = len(st.get("lead_trials") or []) + 1
    if not sid:
        return {"status": "no_session"}
    found = next(((k, v) for k, v in reversed(list(st.get("screens", {}).items()))
                  if v.get("seat") == "lead" and (v.get("session_id") or "").strip() == sid), None)
    if not found:
        if pref(st, 'screen_mode') == "off":
            return {"status": "off", "attempt": attempt}
        if write_locked(st):
            return {"status": "locked", "attempt": attempt}
        screen, message = _screen_ask(d, st, "lead", sid, "strict", None)
        return {"screen": screen, "message": message, "status": "asked", "attempt": attempt}
    screen, rec = found
    message = None
    keyfile = _keys_dir(st) / f"{screen}.json"
    try:
        questions = json.loads(keyfile.read_text(encoding="utf-8")).get("questions", {})
        message = lab(st, "screen_prompt") + "\n" + "\n".join(f"{p}: {questions[p]}" for p in rec.get("items", []) if p in questions)
    except (OSError, ValueError, AttributeError):  # the questions live outside the project; without them only the status is shown
        pass
    out = {"screen": screen, "message": message, "attempt": attempt}
    if rec.get("verdict") in ("pass", "marginal", "fail"):
        out.update(status=rec["verdict"], score=rec.get("score"), max=rec.get("max"),
                   status_label=lab(st, "screen_row", verdict=_verdict_word(st, rec["verdict"]), score=rec.get("score"), max=rec.get("max")))
    elif rec.get("verdict") == "unscored" or rec.get("status") == "unscored":
        out.update(status="unavailable", status_label=_verdict_word(st, "unscored"))
    else:
        out.update(status="asked", status_label=lab(st, "lead_screen_asked"))
    return out


def _lead_existing_screen_status(st):
    sid = ((st.get("lead") or {}).get("session_id") or "").strip()
    if not sid:
        return {"status": "not_new"}
    found = next(((k, v) for k, v in reversed(list(st.get("screens", {}).items()))
                  if v.get("seat") == "lead" and (v.get("session_id") or "").strip() == sid), None)
    if not found:
        return {"status": "not_new"}
    screen, rec = found
    if rec.get("verdict") in ("pass", "marginal", "fail"):
        return {"screen": screen, "status": rec["verdict"]}
    if rec.get("verdict") == "unscored" or rec.get("status") == "unscored":
        return {"screen": screen, "status": "unavailable"}
    return {"screen": screen, "status": "asked"}


def _takeover_data(st):
    threads = []
    for name, thread in st.get("threads", {}).items():
        if not thread.get("session_id") or thread.get("status") == "archived": continue
        active = [(tid, task) for tid, task in st.get("tasks", {}).items()
                  if task.get("owner") == name and task.get("status") not in ("done", "dropped", "recalled")]
        current = "; ".join(f"{tid} {task.get('title') or tid}" for tid, task in active[:2])
        threads.append({"seat": name, "status": thread.get("status", "?"), "task": current or thread.get("summary") or thread.get("focus") or "-",
                        "last_report_at": thread.get("last_status_at") or thread.get("last_seen") or "?"})
    promises = [x for x in st.get("promises", []) if x.get("status") != "done"]
    asks = [x for x in st.get("questions", []) if not x.get("answered") and not x.get("answered_at")] \
        + [x for x in st.get("notices", []) if not x.get("done") and x.get("kind") in ("needs-user", "parked")]
    issues = [x for x in st.get("issues", []) if x.get("status") not in ("merged", "verified")]
    rows = [model_lab(st, "tk_head", project=st.get('project'), goal=st.get('goal') or '-', n=len(threads))]
    def section(label, items, render, count_label):
        rows.append(label + (("；" if model_lab(st, "tk_none") == "无" else "; ").join(render(x) for x in items[:5]) or model_lab(st, "tk_none")))
        if len(items) > 5: rows.append(model_lab(st, "tk_more", n=len(items) - 5, what=count_label))
    section("", threads, lambda x: model_lab(st, "tk_thread", seat=x['seat'], status=x['status'], task=x['task'], at=x['last_report_at']), model_lab(st, "tk_threads"))
    section(model_lab(st, "tk_promises_h"), promises, lambda x: x.get("text", x.get("id", "")), model_lab(st, "tk_promises"))
    section(model_lab(st, "tk_asks_h"), asks, lambda x: x.get("text", ""), model_lab(st, "tk_asks"))
    section(model_lab(st, "tk_issues_h"), issues, lambda x: x.get("text", ""), model_lab(st, "tk_issues"))
    if st.get("lead", {}).get("permission_mode") == "auto": rows.append(model_lab(st, "auto_note"))
    rows.append(model_lab(st, "takeover_final"))
    return {"takeover": True, "threads": threads, "promises": promises, "asks": asks, "issues": issues, "lines": rows}


def newer_release(info=None):
    label, info = running_version() if info is None else (None, info)
    skill = Path(__file__).resolve().parents[1]
    if info.get("type") != "release": return None
    try:
        releases = json.loads((skill.parent / "index.json").read_text(encoding="utf-8"))["releases"]
        latest = max(releases, key=lambda r: _release_stamp(r.get("name") or "") or "") if releases else None
        return latest["name"] if latest and version_relation(latest["name"], info["name"]) == "older" else None
    except (OSError, ValueError, KeyError): return None


def cmd_selfcheck(a):
    d = find_dir(); st = load(d) if d else {}; lead = st.get("lead", {})
    def item(name, ok, detail="", fix=""): return {"item": name, "ok": ok, "detail": detail, "fix": fix}
    mode = a.mode or lead.get("permission_mode")
    items = [item("mode", mode == "auto" if mode else None, mode or lab(st,"selfcheck_input_missing"), lab(st,"selfcheck_mode_fix")),
             item("session", bool(lead.get("session_id")), str(lead.get("session_id") or lab(st,"selfcheck_session_missing")), "TW lead --session <id>")]
    lead_screen = next((x for x in reversed(list(st.get("screens", {}).values())) if x.get("seat") == "lead"), None)
    if lead_screen:
        items.append(item("screening", lead_screen.get("verdict") == "pass",
                          _screen_label(st, "lead") or _verdict_word(st, "unscored"),
                          f"TW screen ask lead --session {lead.get('session_id') or '<id>'}"))
    served_model = getattr(a, "served_model", None) or getattr(a, "last_served_model", None)
    items.append(item("model", a.model == served_model if a.model and served_model else None,
                      lab(st,"selfcheck_model_detail",served=served_model,configured=a.model) if a.model and served_model and a.model != served_model else "",
                      lab(st,"selfcheck_model_fix")))
    items.append(item("gpt_model", None, str(pref(st, 'gpt_model') or "not recorded")))
    items.append(item("effort", a.effort == a.want_effort if a.want_effort else None,
                      lab(st,"selfcheck_effort_detail",effort=a.effort,wanted=a.want_effort) if a.want_effort and a.effort != a.want_effort else "",
                      lab(st,"selfcheck_effort_fix")))
    folder = Path(st.get("repo", {}).get("path") or (d.parent if d else "."))
    used = a.seats_used
    if used is None:  # the seat cap counts every project's sessions on this computer, not only this one's
        used = 1 if lead.get("session_id") else 0
        own = d.parent.resolve() if d else None
        for f in find_projects(Path(a.served).expanduser() if a.served else (d.parent.parent if d else Path("."))):
            try:
                o = json.loads((f / ".teamwork" / "state.json").read_text(encoding="utf-8"))
            except (OSError, ValueError):
                continue
            if not isinstance(o, dict):
                continue
            used += sum(1 for t in (o.get("threads") or {}).values()
                        if isinstance(t, dict) and t.get("status") != "archived" and t.get("session_id"))
            used += 1 if f.resolve() != own and (o.get("lead") or {}).get("session_id") else 0
    items.append(item("seats", used < a.seats_max, lab(st,"selfcheck_seats_detail",used=used,max=a.seats_max), lab(st, "selfcheck_seats_fix")))
    codex = shutil.which("codex")
    gpt_status, gpt_detail = None, lab(st, "selfcheck_gpt_missing")
    if codex:
        try:
            probe = subprocess.run([codex, "--version"], capture_output=True, text=True, timeout=10)
            gpt_status = probe.returncode == 0
            gpt_detail = (probe.stdout or probe.stderr).strip().splitlines()[0] if (probe.stdout or probe.stderr).strip() else lab(st, "selfcheck_gpt_version_failed", code=probe.returncode)
        except (OSError, subprocess.TimeoutExpired) as exc:
            gpt_detail = lab(st, "selfcheck_gpt_version_error", error=type(exc).__name__)
    items.append(item("gpt", gpt_status, gpt_detail, lab(st, "selfcheck_gpt_fix")))
    if getattr(a, "gpt_probe", False):
        model = pref(st, 'gpt_model') or "gpt-6-luna"
        try:
            result = subprocess.run([codex, "exec", "--skip-git-repo-check", "-m", model, "reply OK"],
                                    capture_output=True, text=True, timeout=60) if codex else None
            st["selfcheck"]["gpt_probe"] = {"at": now(), "ok": bool(result and result.returncode == 0),
                "detail": ((result.stdout or result.stderr).strip().splitlines()[-1][:240] if result and (result.stdout or result.stderr).strip() else lab(st, "selfcheck_gpt_probe_missing"))}
        except (OSError, subprocess.TimeoutExpired) as exc:
            st["selfcheck"]["gpt_probe"] = {"at": now(), "ok": False, "detail": type(exc).__name__}
    label, info = running_version(); newer = newer_release(info)
    host_key = hashlib.sha256(socket.gethostname().encode()).hexdigest()[:8]
    st["versions"][host_key] = {"version": label, "at": now()}
    other_versions = []
    for k,v in st["versions"].items():
        if k == host_key: continue
        relation=version_relation(label,v.get("version"))
        if relation == "older": other_versions.append(lab(st,"version_other_computer",host=k,version=v.get("version")))
        elif relation == "newer": other_versions.append(lab(st,"version_computer_newer",host=k,version=v.get("version")))
        elif relation == "incomparable": other_versions.append(lab(st,"version_incomparable"))
    version_needs_attention = bool(newer or any(version_relation(label,v.get("version")) in ("older","incomparable") for k,v in st["versions"].items() if k != host_key))
    edge_detail = lab(st, "version_edge_detail") if info.get("type") == "edge" else ""
    items.append(item("version", not version_needs_attention,
                      "; ".join(([lab(st, "version_newer_detail", version=newer)] if newer else [lab(st, "version_detail", version=label, edge=edge_detail)]) + other_versions),
                      lab(st, "version_fix") if version_needs_attention else ""))
    items.append(item("ledger", bool(d and (d / "state.json").exists() and (d / "BOARD.md").exists()),
                      lab(st, "selfcheck_ledger_files")))
    found = {"SessionStart": False, "PreToolUse": False}  # RC sessions start in the served folder: its hooks count too
    for base in dict.fromkeys([folder, Path(a.served).expanduser() if a.served else folder.parent]):
        for name in ("settings.json", "settings.local.json"):
            try:
                hk = json.loads((base / ".claude" / name).read_text(encoding="utf-8")).get("hooks") or {}
            except (OSError, ValueError, AttributeError):
                continue
            for ev, word in (("SessionStart", "context"), ("PreToolUse", "bash-guard")):
                for g in hk.get(ev) or []:
                    for h in (g.get("hooks") or []) if isinstance(g, dict) else []:
                        c = str(h.get("command", "")) if isinstance(h, dict) else ""
                        found[ev] |= "tw.py" in c and word in c
    hookok = all(found.values())
    items.append(item("hooks", hookok, lab(st,"selfcheck_hooks_detail") if hookok else lab(st,"selfcheck_hooks_missing"), lab(st,"selfcheck_hooks_fix")))
    errs = guard_errors_recent()
    if errs:  # reported only when there is something to report
        items.append(item("guard_errors", False, lab(st, "guard_errors", n=errs), f"read {guard_log_path()} and report the error"))
    missing = [k for k in ("perm_policy", "gpt_policy") if not pref(st, k)]
    items.append(item("opening", True, lab(st, "opening_defaults_detail", pairs=", ".join(f"{k}={policy(st, k)}" for k in missing))
                      if missing else "answered", ""))
    if st.get("compactions",{}).get("lead"):
        compact=st["compactions"]["lead"]
        check=(st.get("signals",{}).get("lead") or {}).get("compact_check") or {}
        items.append(item("compact_check",bool(check.get("answered") and check.get("passed")),
                          _compact_label(st,"lead"),"use the command in the compact block to answer"))
    modeitem, proj = items[0], st.get("project")
    # Every checklist entry states whether it was measured, recorded, or left untested.
    for x in items:
        x["how"] = "tested" if x.get("ok") is not None else "not-tested"
        if x["how"] == "not-tested": x["why"] = x.get("detail") or "required input was not available"
    items[0]["how"] = "tested" if a.mode else "recorded" if lead.get("permission_mode") else "not-tested"
    if not a.mode: items[0]["ok"] = None
    if not a.mode and lead.get("permission_mode"):
        items[0].pop("why", None)
        items[0]["detail"] += " (" + lab(st, "mode_recorded_detail") + ")"
    elif not a.mode:
        items[0]["why"] = lab(st, "mode_not_supplied")
    model_item = next(x for x in items if x["item"] == "model")
    effort_item = next(x for x in items if x["item"] == "effort")
    model_item["how"] = "tested" if a.model and a.served_model else "recorded" if a.model else "not-tested"
    effort_item["how"] = "tested" if a.want_effort else "recorded" if a.effort else "not-tested"
    if model_item["how"] == "not-tested": model_item["why"] = lab(st, "selfcheck_model_input_missing")
    else: model_item.pop("why", None)
    if effort_item["how"] == "not-tested": effort_item["why"] = lab(st, "selfcheck_effort_input_missing")
    else: effort_item.pop("why", None)
    spawn = lead.get("spawn_probe") or {}; spawn_ok = spawn.get("result") == "ok"
    spawn_word=lab(st,"spawn_" + spawn.get("result", "untested") if spawn.get("result") in ("ok","refused","untested") else "spawn_untested")
    items.append(item("spawn", spawn_ok if spawn.get("result") in ("ok", "refused") else None,
                      spawn_word + (f": {spawn['note']}" if spawn.get("note") else ""),
                      lab(st,"selfcheck_spawn_fix")))
    if spawn.get("result") in ("ok", "refused"): items[-1]["how"] = "tested"
    if not spawn.get("result") or spawn.get("result") == "untested": items[-1]["how"] = "not-tested"; items[-1]["why"] = items[-1]["fix"]
    if lead.get("opened_by"):
        items.append(item("opened_by", None,
                          lab(st, "mode_opened_elsewhere_detail") if lead.get("opened_by") != "self" else lab(st, "mode_opened_self"),
                          lab(st, "mode_trusted_fix") if lead.get("opened_by") != "self" else ""))
        items[-1]["how"] = "recorded"
        if lead.get("opened_by") != "self" and not a.mode:
            items[0].update(ok=None, how="not-tested", why=lab(st, "mode_opened_elsewhere"))
    dev = bool(st.get("tasks")) or bool(re.search(r"\b(app|software|website|webapp|feature|implement|code|build|开发|应用|网站)\b", st.get("goal", ""), re.I))
    if dev and not st.get("features"):
        items.append(item("features", False, lab(st, "dev_features_missing"), lab(st, "feature_fix")))
        items[-1]["how"] = "tested"
    else:
        items.append(item("features", True, lab(st, "features_count", n=len(st.get("features") or {})) if dev else lab(st, "features_not_required")))
        items[-1]["how"] = "tested"
    probe_row = (st.get("selfcheck") or {}).get("gpt_probe")
    if probe_row:
        age = _minutes_since(probe_row.get("at"))
        items.append(item("gpt_probe", bool(probe_row.get("ok")), f"{probe_row.get('detail', '')}; age {age if age is not None else '?'} min",
                          lab(st, "selfcheck_gpt_probe_fix") if not probe_row.get("ok") else ""))
        items[-1]["how"] = "recorded"
    st["selfcheck"]["items"] = items
    st["selfcheck"]["at"] = now()
    if d: save(d, st, {"ev": "selfcheck"})
    if not d:
        first = lab(st,"selfcheck_first_none",project="",version=label)
    elif a.desktop or lead.get("desktop"):
        first = lab(st,"selfcheck_first_desktop",project=proj,version=label)
    elif modeitem["ok"]:
        first = lab(st,"selfcheck_first_auto",project=proj,version=label)
    elif modeitem["ok"] is None:
        first = lab(st,"selfcheck_first_unknown",project=proj,version=label)
    else:
        first = lab(st,"selfcheck_first_switch",project=proj,fix=modeitem['fix'],version=label)
    failed = [x for x in items if x["ok"] is False]
    opening_status = lab(st, "open_session_tests")
    notice = st.get("version_notice") or {}
    notice_line = lab(st, "version_notice", n=len(notice.get("sessions") or []), sessions=", ".join(notice.get("sessions") or [])) if notice.get("release") == label and notice.get("sessions") else None
    if a.json: print(json.dumps({"items": items, "first_line": first, "session_opening": opening_status, **({"version_notice": notice_line} if notice_line else {})}, ensure_ascii=False))
    else:
        print(first)
        if notice_line: print(notice_line)
        print(opening_status)
        for x in (failed if a.brief else items):
            status = lab(st, "selfcheck_tested") if x.get("ok") is True and x.get("how") == "tested" else lab(st, "selfcheck_failed") if x.get("ok") is False else lab(st, "selfcheck_recorded") if x.get("how") == "recorded" else lab(st, "selfcheck_untested", why=x.get("why", "原因未记录"))
            name = lab(st, "selfcheck_item_" + x["item"])
            print(f"{status} {name}: {x['detail']}" + (lab(st, "selfcheck_fix_sep") + x['fix'] if x["ok"] is False and x.get("fix") else ""))


def cmd_worker_prompt(a):
    d = need(find_dir())
    st = load(d)
    if a.thread not in st["threads"]:
        sys.exit(f"unknown thread {a.thread}")
    t = st["threads"][a.thread]
    tpl = (TEMPLATES / "worker-protocol.md").read_text(encoding="utf-8")
    if t["kind"] == "rc":
        channel = (
            "Push: send_message to the lead's session_id (works rc->rc; allowed without a prompt if setup was done). "
            "Also end every turn with the STATUS block, because the lead may read your transcript instead."
        )
    else:
        channel = (
            "Pull only: you are a cloud thread, and a message from a cloud session to an RC session (the lead) is "
            "blocked by account trust rules, so NEVER send_message to the lead and never call confirm_repository_trust. "
            "End EVERY turn with the STATUS block; the lead reads your transcript (get_session / list_events). You MAY "
            "send_message to other cloud threads. You cannot see the project folder; code reaches the lead through git: "
            "commit and push your branch."
        )
    fill = {
        "PROJECT": st["project"],
        "TAG": tag(st),
        "GOAL": st.get("goal") or "-",
        "THREAD": a.thread,
        "KIND": t["kind"],
        "FOCUS": t.get("focus") or "-",
        "OWNS": ", ".join(t.get("owns", [])) or "-",
        "BRANCH": branch_of(st, a.thread),
        "BASE": st.get("repo", {}).get("base") or "main",
        "LEAD_SESSION": st["lead"].get("session_id") or "(unset)",
        "ROSTER": render_roster(st, a.thread),
        "MY_TASKS": render_tasks(st, only_owner=a.thread),
        "INSTRUCTIONS": read_file(d, "INSTRUCTIONS.md").strip()[:16000] or "(none)",
        "MEMORY": read_file(d, "MEMORY.md").strip() or "(empty)",
        "REPORT_CHANNEL": channel,
        "FOLDER": st.get("repo", {}).get("path") or "-",
        "LANGUAGE": language_rule(st),
        "REVIEW_MAX": (f"**{review_max(st)}** rounds" if review_max(st) else "**none** (no round limit; "
                       "the 'at the limit' rule does not apply)"),
        "GUARD": (f"run `python3 \"{SKILL_DIR / 'scripts' / 'tw.py'}\" -C \"{st.get('repo', {}).get('path') or '.'}\" "
                  "guard --repo .` in your worktree before every push; it must print `guard: ok`"
                  if t["kind"] == "rc" else
                  "you cannot see the private list, so never write names of the user's own products, people, "
                  "accounts or machines into files, commits or branch names. Your TASK carries a check script with "
                  "a salted, hashed list (`tw-guard.py`): save it outside the repo (e.g. /tmp/tw-guard.py, never "
                  "commit it) and run `python3 /tmp/tw-guard.py origin/<base>` before every push; it must print "
                  "`guard: ok`. It only catches accidents; the lead re-checks your branch with the real list before "
                  "merging"),
        "WORKTREE": (f"`{t.get('worktree') or worktree_path(st, a.thread)}` (the lead creates it; if it is missing, "
                     f"create it yourself with exactly: `{worktree_cmd(st, a.thread)}`)")
        if t["kind"] == "rc" else "your container's checkout of the repo (cloud thread)",
        "SOURCE_BASELINE": "事实来源与版本基线：" if pref(st, 'language') == "zh" else "Source of truth and version baseline:",
    }
    out = tpl
    for k, v in fill.items():
        out = out.replace("{{" + k + "}}", v)
    left = re.findall(r"\{\{[A-Z_]+\}\}", out)
    if left:
        sys.exit(f"template placeholders not filled: {left}")
    print(out)


def clear_thread_tmp(project, thread, names=()):
    """Delete what is in <project>/.teamwork/private/<thread>/tmp (or only the named entries) without a shell (R84; the space
    manager uses it too). Walks real directory handles opened with O_NOFOLLOW, so a link swapped in at any moment is
    removed as a link, never followed. Returns (removed names, bytes freed)."""
    if not re.fullmatch(NAME_RE, thread): sys.exit(f"bad thread name {thread!r}")
    bad = [n for n in names if not n or n in (".", "..") or "/" in n or os.sep in n]
    if bad: sys.exit(f"names inside tmp only, no paths: {', '.join(map(repr, bad))}")
    flags = os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW
    project = Path(project).resolve()
    tmp_path = project / ".teamwork" / "private" / thread / "tmp"
    evidence = set()
    try:
        ledger = json.loads((project / ".teamwork" / "state.json").read_text(encoding="utf-8"))
        def collect(value, marked=False):
            if isinstance(value, dict):
                for key, child in value.items(): collect(child, marked or "evidence" in str(key).lower())
            elif isinstance(value, list):
                for child in value: collect(child, marked)
            elif marked and isinstance(value, str):
                raw = Path(value).expanduser()
                candidates = (raw, project / raw, tmp_path / raw)
                for candidate in candidates:
                    try:
                        rel = candidate.resolve(strict=False).relative_to(tmp_path)
                        if rel.parts: evidence.update(rel.parts[:i] for i in range(1, len(rel.parts) + 1))
                    except (OSError, ValueError): pass
        collect(ledger)
    except (OSError, ValueError, TypeError):
        pass
    fd = os.open(project, flags)
    try:
        for part in (".teamwork", "private", thread, "tmp"):  # .teamwork itself may not be a link either
            try: nxt = os.open(part, flags, dir_fd=fd)
            except FileNotFoundError: return [], 0, []
            except OSError: sys.exit(f"{part}: not a plain folder (a link on the way?); nothing touched")
            os.close(fd); fd = nxt
        removed, kept, freed = [], [], 0
        for name in (names or sorted(os.listdir(fd))):
            if (name,) in evidence or any(path[0] == name for path in evidence):
                kept.append(name); continue
            try: info = os.lstat(name, dir_fd=fd)
            except FileNotFoundError: continue
            if stat.S_ISDIR(info.st_mode):
                sub = os.open(name, flags, dir_fd=fd)
                try: freed += sum(os.lstat(f, dir_fd=r).st_size for _, _, fs, r in os.fwalk(dir_fd=sub) for f in fs)
                finally: os.close(sub)
                shutil.rmtree(name, dir_fd=fd)  # fd-based: does not follow links (shutil.rmtree.avoids_symlink_attacks)
            else:
                freed += info.st_size; os.unlink(name, dir_fd=fd)
            removed.append(name)
        return removed, freed, kept
    finally:
        os.close(fd)


def cmd_worktree(a):
    """Create the rc thread's git worktree and branch if missing (idempotent)."""
    d = need(find_dir())
    st = load(d)
    if a.thread not in st["threads"]:
        sys.exit(f"unknown thread {a.thread}")
    if a.clear_tmp is not None:
        removed, freed, kept = clear_thread_tmp(st.get("repo", {}).get("path") or d.parent, a.thread, a.clear_tmp)
        print(json.dumps({"thread": a.thread, "removed": removed, "freed_bytes": freed,
                          "kept (referenced as evidence)": kept}, ensure_ascii=False)); return
    t = st["threads"][a.thread]
    if t["kind"] != "rc":
        sys.exit("cloud threads have no local worktree; they push their branch")
    repo = st.get("repo", {}).get("path") or "."
    base = st.get("repo", {}).get("base") or "main"
    path = Path(t.get("worktree") or worktree_path(st, a.thread))
    git = lambda *x: subprocess.run(["git", "-C", repo, *x], capture_output=True, text=True)
    if git("rev-parse", "--git-dir").returncode != 0:
        sys.exit(f"{repo} is not a git repository: no worktree needed; the thread works in the project folder")
    br = branch_of(st, a.thread)
    res = {"thread": a.thread, "worktree": str(path), "branch": br}
    if path.exists():
        res["created"] = False
        res["note"] = "already exists"
        top = git("-C", str(path), "rev-parse", "--show-toplevel")
        own = top.returncode == 0 and Path(top.stdout.strip()).resolve() == path.resolve()
        r = git("-C", str(path), "symbolic-ref", "-q", "--short", "HEAD") if own else top  # a plain folder: no checks
        if own and r.returncode == 0 and r.stdout.strip() != br:
            sys.exit(f"{path} is on {r.stdout.strip()}, but {a.thread}'s branch is {br}: leases and trace "
                     "follow the ledger's branch; switch the worktree or fix the ledger before the thread works")
        if own and r.returncode != 0:
            sys.exit(f"{path} is on a detached HEAD, but {a.thread}'s branch is {br}: commits there belong to no "
                     f"branch, so leases and trace miss them. `git -C \"{path}\" switch {br}` before the thread works")
    else:
        has_branch = git("show-ref", "--verify", "--quiet", f"refs/heads/{br}").returncode == 0
        cmd = (["worktree", "add", str(path), br] if has_branch
               else ["worktree", "add", "-b", br, str(path), base])
        res["command"] = "git -C " + repo + " " + " ".join(cmd)
        if a.dry_run:
            res["created"] = False
            res["note"] = "dry run"
        else:
            path.parent.mkdir(parents=True, exist_ok=True)
            r = git(*cmd)
            if r.returncode != 0:
                sys.exit(f"git worktree add failed: {r.stderr.strip()}")
            res["created"] = True
            src = Path(repo) / ".claude" / "settings.local.json"
            dst = path / ".claude" / "settings.local.json"
            if src.is_file() and not dst.exists():  # the project's permission rules follow the thread (T36)
                dst.parent.mkdir(parents=True, exist_ok=True)
                dst.write_bytes(src.read_bytes())
                common = git("rev-parse", "--git-common-dir").stdout.strip()
                ex = (Path(repo) / common / "info" / "exclude") if common else None
                if ex is not None:
                    ex.parent.mkdir(parents=True, exist_ok=True)
                    cur = ex.read_text(encoding="utf-8") if ex.exists() else ""
                    if ".claude/settings.local.json" not in cur.splitlines():
                        ex.write_text(cur + ("" if cur.endswith("\n") or not cur else "\n")
                                      + ".claude/settings.local.json\n", encoding="utf-8")
                res["settings"] = str(dst)
    if t.get("worktree") != str(path):
        t["worktree"] = str(path)
        save(d, st, {"ev": "worktree", "thread": a.thread, "path": str(path)})
    elif res.get("created"):
        log(d, {"ev": "worktree", "thread": a.thread, "path": str(path)})
    print(json.dumps(res, ensure_ascii=False))


def live_tasks(st, q):
    """A request's linked tasks that still count: a dropped task neither delivers it nor holds it back."""
    return [t for t in (q.get("tasks") or []) if st["tasks"].get(t, {}).get("status") != "dropped"]


def tasks_ready(st, q):
    """True when the request has live linked work and all of it is in review or done (all dropped: not ready)."""
    ts = live_tasks(st, q)
    return bool(ts) and all(st["tasks"].get(t, {}).get("status") in ("review", "done") for t in ts)


def deliver_ready(st):
    """Requests whose live linked tasks are all in review or done move dispatched -> delivered. Returns the ids."""
    moved = []
    for r, q in st.get("requests", {}).items():
        changed_after_reopen = not q.get("reopened_at") or any(
            (st.get("tasks", {}).get(t, {}).get("updated") or "") >
            q.get("reopened_task_updates", {}).get(t, "") for t in live_tasks(st, q))
        if q["status"] == "dispatched" and tasks_ready(st, q) and changed_after_reopen:
            q["status"] = "delivered"
            q["updated"] = now()
            moved.append(r)
    return moved


def undeliver(st):
    """A delivered or reported request whose task went back to work (review fail, rework) is dispatched again:
    what was delivered or told to the user is no longer the result (report the new one when it comes back)."""
    moved = []
    for r, q in st.get("requests", {}).items():
        ts = live_tasks(st, q)  # every task dropped: the result already told stays told (not re-dispatched)
        if q["status"] in ("delivered", "reported") and not q.get("gate") and not all(  # landed stays; gated waits for the user
                st["tasks"].get(t, {}).get("status") in ("review", "done") for t in ts):
            q["status"] = "dispatched"
            q["updated"] = now()
            q["reopened_at"] = now()
            q["reopened_task_updates"] = {t: st.get("tasks", {}).get(t, {}).get("updated", "") for t in ts}
            moved.append(r)
    return moved


def unreported_note(st):
    u = unreported(st)
    if not u:
        return ""
    items = "; ".join(f"{r}: {q['text']}" for r, q in u.items())
    return (f"{lab(st, 'unreported')}: {items}. Tell the user what came back, then "
            "`tw.py req set <R> --status reported`.\n\n")


def next_req_id(st):
    nums = [int(r[1:]) for r in st.get("requests", {}) if r[1:].isdigit()]
    return f"R{max(nums, default=0) + 1}"


def check_tasks(st, ids):
    bad = [t for t in ids if t not in st["tasks"]]
    if bad:
        sys.exit(f"unknown task(s) {', '.join(bad)}; add them with `task add` first")
    gone = [t for t in ids if st["tasks"][t].get("status") == "dropped"]
    if gone:
        sys.exit(f"{', '.join(gone)} dropped: a request waits only on live work, link the task that replaces it")


def set_req_status(st, r, q, new, by_import=False, user_said=None):
    """The only place a request's status changes (besides close/drop): checks framework A9 preconditions."""
    if new not in REQ_STATUSES:
        sys.exit(f"status must be one of {REQ_STATUSES}")
    if by_import:
        q["status"] = new
        return
    cur = q["status"]
    if new == cur:
        return
    if new in REQ_END:
        sys.exit(f"only the user ends a request: `req close {r} --user-said \"<their words>\"` (accepted) or "
                 f"`req drop {r} --user-said \"<their words>\"` (not to do it)")
    frm = q.get("held_from") or "open" if cur == "held" else cur  # IL-33: held pauses a request where it was
    moves = ({frm} | REQ_MOVES.get(frm, set())) - {"held"} if cur == "held" else set(REQ_MOVES.get(cur, set()))
    if cur not in REQ_END:
        moves.add("wont")  # any live request can be set aside with a reason (F7)
    if new not in moves:
        allowed = ", ".join(sorted(moves)) or "nothing (it has ended)"
        sys.exit(f"{r} is {cur}" + (f" (paused while {frm})" if cur == "held" else "") + f": it can move to {allowed}")
    user_said = (user_said or "").strip() or None
    if (frm, new) in REQ_NEEDS_USER and not user_said:
        sys.exit(f"{r} {cur} -> {new} is the user's decision: add --user-said \"<their words>\"")
    if new == "landed" and cur != "reported":
        sys.exit(f"{r}: landed is only allowed from reported")
    if new == "reported" and cur == "open":
        busy = [t for t in live_tasks(st, q) if st["tasks"].get(t, {}).get("status") not in ("review", "done")]
        if busy:
            sys.exit(f"{r} has work still in progress ({', '.join(busy)}): it is reported once that work is delivered")
    # A request the user had to say yes to keeps that gate through waiting_user / wont / open (no side door)
    if new in ("waiting_user", "wont") and frm in ("proposed", "reported", "landed"):
        q["gate"] = frm
    if new == "dispatched" and q.get("gate") and not user_said:
        sys.exit(f"{r} came from {q['gate']}: dispatching it is the user's decision: add --user-said \"<their words>\"")
    if new == "dispatched" and user_said:
        q.pop("gate", None)
    if new == "delivered":
        ts = live_tasks(st, q)
        not_ready = [t for t in ts if st["tasks"].get(t, {}).get("status") not in ("review", "done")]
        if not ts or not_ready:
            sys.exit(f"{r} is delivered only when every linked task that is not dropped is in review or done"
                     + (f" (not yet: {', '.join(not_ready)})" if not_ready else
                        " (all linked tasks are dropped: link the new work, or ask the user to drop the request)"
                        if q.get("tasks") else " (no tasks linked)"))
    if new == "held":
        q["held_from"] = cur
    else:
        q.pop("held_from", None)
    q["status"] = new
    if user_said:
        q.setdefault("user_said", []).append({"t": now(), "to": new, "text": user_said})
    if new == "reported":
        q["reported_at"] = now()


def cmd_req(a):
    d = need(find_dir())
    st = load(d)
    reqs = st["requests"]
    if a.action == "list":
        rows = {r: q for r, q in reqs.items() if (not a.status or q.get("status") == a.status) and
                (a.all or a.status or (q["status"] not in REQ_END and q["status"] != "remark"))}
        print(json.dumps(rows, ensure_ascii=False, indent=2))
        return
    if a.action == "confirm":
        said=(a.user_said or "").strip()
        if not said: sys.exit(lab(st,"req_confirm_words"))
        ids=[rid for rid,q in reqs.items() if awaiting_confirm(st,q)] if a.all else a.args
        if not ids: sys.exit(lab(st,"req_confirm_ids"))
        bad=[rid for rid in ids if rid not in reqs or not awaiting_confirm(st,reqs[rid])]
        if bad: sys.exit(lab(st,"req_confirm_reported",ids=", ".join(bad)))
        for rid in ids:
            q=reqs[rid]; q.update(status="closed",confirmed_at=now(),confirmed_by=said,updated=now())
        save(d,st,{"ev":"req-confirm","ids":ids,"user_said":said})
        print(json.dumps({rid:reqs[rid] for rid in ids},ensure_ascii=False,indent=2)); return
    if a.action == "import":
        cmd_req_import(a, d, st); return
    if a.action == "migrate":
        suggestions = {}
        for rid, q in reqs.items():
            if q.get("status") != "reported" or q.get("migrated"): continue
            text = " ".join(str(q.get(k) or "") for k in ("followup", "where", "text")); low = text.lower()
            rule = None; target = None
            if any(w in low for w in ("等你", "待你", "确认", "回访", "你定", "wait for you")): target="waiting_user"; rule=next(w for w in ("等你", "待你", "确认", "回访", "你定", "wait for you") if w in low)
            elif q.get("where") and any(w in low for w in ("已合并", "合入", "merged", "已做")): target="landed"; rule=next(w for w in ("已合并", "合入", "merged", "已做") if w in low)
            elif any(w in low for w in ("不做", "放弃", "won't")): target="wont"; rule=next(w for w in ("不做", "放弃", "won't") if w in low)
            suggestions[rid] = {"suggested": target or "unclear", "rule": rule}
        only = set(csv(a.only)) if a.only else None
        if only and only - set(suggestions): sys.exit(f"--only: not in the preview: {', '.join(sorted(only - set(suggestions)))}")
        if a.apply:
            said = (a.user_said or "").strip()
            if not said: sys.exit("req migrate --apply requires --user-said")
            moved = []
            for rid, rec in suggestions.items():
                if rec["suggested"] == "unclear" or (only is not None and rid not in only): continue
                q=reqs[rid]; q["status"]=rec["suggested"]; q["updated"]=now()
                q["migrated"]={"from":"reported","at":now(),"rule":rec["rule"],"user_said":said}
                q.setdefault("user_said", []).append({"t": now(), "to": rec["suggested"], "text": said})
                if rec["suggested"] in ("waiting_user", "wont"):
                    q["gate"] = "reported"  # agreeing to the migration is not agreeing to more work
                if rec["suggested"] == "wont": q["reason"]=f"migrated (matched: {rec['rule']})"
                if rec["suggested"] == "landed": q["evidence"]=q.get("where")
                moved.append(rid)
            if moved: save(d, st, {"ev":"req-migrate", "ids":moved, "user_said":said})
        print(json.dumps(suggestions, ensure_ascii=False, indent=2))
        print(f"migrate: {sum(x['suggested'] != 'unclear' for x in suggestions.values())} suggested, {sum(x['suggested'] == 'unclear' for x in suggestions.values())} unclear", file=sys.stderr)
        return
    if a.action == "add":
        if not a.args:
            sys.exit('usage: req add "<what the user asked, close to their words>" [--tasks T1,T2]')
        r = a.id or next_req_id(st)
        if r in reqs:
            sys.exit(f"request {r} exists")
        tasks = csv(a.tasks)
        kind = a.kind  # --remark alone stays a request that may be promoted later (T56); --kind says it is never one
        if a.remark and tasks: sys.exit("remark cannot have tasks")
        if kind != "request" and tasks: sys.exit(lab(st, "req_not_request"))
        check_tasks(st, tasks)
        check_never_raise(d, " ".join(a.args), getattr(a, "override", None))
        text = " ".join(a.args)
        auto_area = next((n for n, ar in st.get("areas",{}).items() if (a.where or "").lower() in {n.lower(), *(x.lower() for x in ar.get("aka",[]))}), None)
        if not (getattr(a,"area",None) or auto_area):
            auto_area=next((area_of_task(st,st["tasks"][tid]) for tid in tasks if area_of_task(st,st["tasks"][tid])),None)
        category=_norm_category(a.category)
        q = {"text": text, "status": "remark" if a.remark or kind != "request" else "open", "kind": kind,
             "tasks": [] if (a.remark or a.kind != "request") else tasks, "where": a.where or "",
             "followup": a.followup or "", "created": now(), "updated": now(),
             **{k: (category if k=="category" else getattr(a,k)) for k in ("phase", "category") if getattr(a, k)},
             **({"area": _area_key(st,a.area) if getattr(a,"area",None) else auto_area} if (getattr(a,"area",None) or auto_area) else {}),
             **({"patchy": True} if patchy_text(text) and (not category or category in ("bug","correction")) else {})}
        reqs[r] = q
        if tasks and not a.remark:
            q["status"] = "dispatched"
            deliver_ready(st)  # linked to work that is already in review or done
        save(d, st, {"ev": "req-add", "req": r, "text": q["text"], "tasks": tasks})
        print(json.dumps({r: q}, ensure_ascii=False))
        owners = ", ".join(dict.fromkeys(st["tasks"][t]["owner"] for t in tasks if st["tasks"][t].get("owner")))
        print(lab(st, "rcpt_remark", r=r) if a.remark or kind != "request" else lab(st, "rcpt_given", r=r, who=owners) if owners
              else lab(st, "rcpt_open", r=r), file=sys.stderr)  # B3: the receipt the lead repeats; stdout stays JSON
        return
    if not a.args:
        sys.exit(f"usage: req {a.action} R<n> ...")
    r = a.args[0]
    if r not in reqs:
        sys.exit(f"unknown request {r}; known: {', '.join(reqs) or '-'}")
    q = reqs[r]
    if a.action == "link":
        if q.get("status") == "remark": sys.exit("remark cannot have tasks")
        if getattr(a, "remove", None):
            if q["status"] in REQ_END:
                sys.exit(lab(st, "req_ended_edit", r=r, status=q["status"]))
            removed = list(a.remove) + csv(a.tasks)
            if not removed:
                sys.exit("usage: req link R<n> --remove T<n> [T<n> ...]")
            q["tasks"] = [t for t in q.get("tasks", []) if t not in removed]
            q["updated"] = now()
            deliver_ready(st)
            save(d, st, {"ev": "req-link", "req": r, "status": q["status"]})
            print(json.dumps({r: q}, ensure_ascii=False)); return
        tasks = csv(",".join(a.args[1:])) + csv(a.tasks)
        if not tasks:
            sys.exit("usage: req link R<n> T1 [T2 ...]")
        check_tasks(st, tasks)
        q["tasks"] = list(dict.fromkeys(q.get("tasks", []) + tasks))
        for tid in tasks:
            task = st["tasks"][tid]
            if not task.get("user_said") and q.get("text"):
                task["user_said"] = q["text"]
        if not q.get("area") and tasks:
            q["area"]=next((area_of_task(st,st["tasks"][tid]) for tid in tasks if area_of_task(st,st["tasks"][tid])),None)
        if q["status"] in REQ_END:
            sys.exit(f"{r} has ended ({q['status']}); register a new request instead")
        if q["status"] in ("reported", "landed"):
            # more work on something already reported: the user reopens it (reported -> dispatched)
            set_req_status(st, r, q, "dispatched", user_said=a.user_said)
            q["reopened_at"] = now()
        if q["status"] == "open" and q.get("gate"):  # was proposed / reported / landed: the user's yes first
            set_req_status(st, r, q, "dispatched", user_said=a.user_said)
        if q["status"] == "open":
            q["status"] = "dispatched"  # proposed stays proposed until the user says yes
        undeliver(st)  # a new task still in progress
        deliver_ready(st)
    elif a.action == "set":
        if q["status"] in REQ_END:
            sys.exit(lab(st, "req_ended_edit", r=r, status=q["status"]))
        was_held = q["status"] == "held"
        if (a.status and q.get("kind", "request") != "request" and a.status not in ("remark", "dropped")) \
                or (getattr(a, "tasks", None) and q.get("kind", "request") != "request"):
            sys.exit(lab(st, "req_not_request"))
        if a.text is not None:
            if not a.text.strip():
                sys.exit("request text cannot be empty")
            check_never_raise(d, a.text, getattr(a, "override", None))
            if q.get("status") not in ("open", "held") and a.text != q.get("text"):
                if not (a.user_said or "").strip():
                    sys.exit(f"{r}: changing dispatched request text requires --user-said")
                q.setdefault("text_history", []).append({"text": q.get("text", ""), "at": now()})
                q.setdefault("user_said", []).append({"t": now(), "to": q.get("status"), "text": a.user_said.strip()})
        old_status = q.get("status")
        if a.status:
            if a.status == "wont":
                if not (a.reason or "").strip(): sys.exit("wont requires --reason")
                q["reason"] = a.reason.strip()
            if a.status == "landed":
                if not (a.evidence or "").strip(): sys.exit("landed requires --evidence")
                q["evidence"] = a.evidence.strip()
            set_req_status(st, r, q, a.status, user_said=a.user_said)
        if a.status == "dispatched" and not q.get("tasks"):
            sys.exit(f"{r} has no tasks: link the work first (`req link {r} T<n>`), which dispatches it")
        if was_held and a.status == "dispatched":
            deliver_ready(st)  # back from held after the work finished meanwhile (rework stays dispatched)
        if old_status in ("reported", "delivered") and q.get("status") == "dispatched":
            q["reopened_at"] = now()
            q["reopened_task_updates"] = {t: st.get("tasks", {}).get(t, {}).get("updated", "") for t in live_tasks(st, q)}
        for k in ("where", "followup", "text", "phase", "category", "area"):
            v = getattr(a, k)
            if v is not None:
                q[k] = _area_key(st,v) if k=="area" else _norm_category(v) if k=="category" else v
        if patchy_text(q.get("text", "")) and q.get("category") in (None,"bug","correction"): q["patchy"] = True
        else: q.pop("patchy",None)
        if q.get("status") == "dispatched":
            deliver_ready(st)
    elif a.action in ("close", "drop"):
        drop = a.action == "drop" or a.declined
        a.user_said = (a.user_said or "").strip()
        if not a.user_said:
            sys.exit(f"only the user ends a request: add --user-said \"<the user's words>\" "
                     f"({'not to do it' if drop else 'accepting the result'})")
        if q["status"] in REQ_END:
            sys.exit(f"{r} has already ended ({q['status']})")
        if not drop and q["status"] == "wont":
            sys.exit(f"{r} is set aside (wont): if the user agrees not to do it, `req drop {r} --user-said \"<their words>\"`")
        if not drop and q["status"] not in ("reported", "landed"):
            sys.exit(f"{r} is {q['status']}: report it to the user first (`req set {r} --status reported`), "
                     "then close it when they accept")
        if not drop:
            for t in q.get("tasks") or []:
                why = accept_gate(st, t) if st["tasks"].get(t, {}).get("status") == "review" else None
                if why:
                    sys.exit(f"{r}: {t} {why}; the user accepts only checked work")
        back = [t for t in live_tasks(st, q) if st["tasks"].get(t, {}).get("status") not in ("review", "done")]
        if not drop and back:
            sys.exit(f"{r} was reported, but {', '.join(back)} went back to work since: report the new result "
                     "first (the user accepted an old one)")
        q["status"] = "dropped" if drop else "closed"
        if drop:
            active = [t for t in q.get("tasks", []) if st.get("tasks", {}).get(t, {}).get("status") in
                      ("dispatched", "working", "blocked")]
            if active:
                print(lab(st, "req_drop_active", r=r, tasks=", ".join(active)), file=sys.stderr)
        q["closed_reason"] = "dropped" if drop else "accepted"
        q["closed_at"] = now()
        q.setdefault("user_said", []).append({"t": now(), "to": q["status"], "text": a.user_said})
        if a.note:
            q["closed_note"] = a.note
    q["updated"] = now()
    save(d, st, {"ev": f"req-{a.action}", "req": r, "status": q["status"]})
    print(json.dumps({r: q}, ensure_ascii=False))


def cmd_req_import(a, d, st):
    """Import a markdown table ledger: | # | what the user said | where | status | follow-up |."""
    if not a.args:
        sys.exit("usage: req import <file.md> [--dry-run]")
    lines = Path(a.args[0]).read_text(encoding="utf-8").splitlines()
    rows = [[c.strip() for c in ln.strip().strip("|").split("|")] for ln in lines if ln.strip().startswith("|")]
    rows = [r for r in rows if not all(set(c) <= set("-: ") for c in r)]
    if not rows:
        sys.exit("no markdown table found")
    head, body = rows[0], rows[1:]
    def col(*names):
        for i, h in enumerate(head):
            if any(n in h.lower() for n in names):
                return i
        return None
    ci = {"id": col("#", "id"), "text": col("用户说的", "request", "asked", "said"),
          "where": col("落到哪里", "where"), "status": col("状态", "status"), "followup": col("回访", "follow")}
    if ci["id"] is None or ci["text"] is None or ci["status"] is None:
        sys.exit(f"table needs id, request and status columns; found header {head}")
    reqs = st["requests"]
    out, skipped = {}, []
    for row in body:
        get = lambda k: (row[ci[k]] if ci[k] is not None and ci[k] < len(row) else "").strip()
        r = get("id")
        if not re.fullmatch(r"R\d+", r):
            continue
        if r in reqs:
            skipped.append(r)
            continue
        status = REQ_STATUS_ALIASES.get(get("status"))
        if status is None:
            sys.exit(f"{r}: unknown status {get('status')!r}; use one of {sorted(REQ_STATUS_ALIASES)}")
        clean = lambda v: "" if v in ("—", "-", "–") else v
        where = clean(get("where"))
        tasks = [t for t in dict.fromkeys(re.findall(r"\bT\d+\b", where)) if t in st["tasks"]]
        span = re.search(r"\bT(\d+)\s*[–-]\s*T(\d+)\b", where)  # T10–T13
        if span:
            tasks += [f"T{i}" for i in range(int(span.group(1)), int(span.group(2)) + 1)
                      if f"T{i}" in st["tasks"] and f"T{i}" not in tasks]
        tasks.sort(key=lambda t: int(t[1:]))
        q = {"text": get("text"), "status": "open", "tasks": tasks, "where": where,
             "followup": clean(get("followup")), "created": now(), "updated": now(), "imported": True}
        set_req_status(st, r, q, status, by_import=True)
        if status in REQ_END:
            q["closed_reason"] = "imported (ended in the old ledger; no user words recorded here)"
        if status == "landed" and not q.get("evidence"):
            q["evidence"] = "imported: " + (where or "no evidence in the old ledger")
        if status == "wont" and not q.get("reason"):
            q["reason"] = "imported (no reason in the old ledger)"
        if status in ("waiting_user", "wont", "landed"):
            q["gate"] = "imported"  # history unknown: dispatching it again takes the user's words
        if q["status"] == "delivered" and tasks and not tasks_ready(st, q):
            q["status"] = "dispatched"  # linked work is not finished (an old row without tasks keeps its status)
        out[r] = q
    if a.dry_run:
        print(json.dumps({"would_import": out, "skipped_existing": skipped}, ensure_ascii=False, indent=2))
        return
    reqs.update(out)
    save(d, st, {"ev": "req-import", "file": a.args[0], "ids": list(out), "skipped": skipped})
    print(json.dumps({"imported": list(out), "skipped_existing": skipped}, ensure_ascii=False))


# ------------------------------------------------------------------ privacy guard

PRIVATE_HELP = """# Private words and paths: never in commits, branches, messages to public places.
# This file lives in .teamwork/ and is never committed. One entry per line, case-insensitive.
#   some-private-product        a word or phrase (substring match)
#   path: secrets/**            a path glob that must never be committed
#   disk: ~/Library/MyApp/**    a path glob that disk cleanup must never remove
# Private notes and files go in .teamwork/private/ (ignored, never committed).
"""


def _clean_entry(ln):
    ln = ln.strip()
    m = re.fullmatch(r"<!--\s*(.*?)\s*-->", ln)
    if m:
        ln = m.group(1)  # <!-- X --> still means X
    ln = re.sub(r"^(>\s*)+", "", ln)  # quotes
    ln = re.sub(r"^([-*+]|\d+[.)])\s+", "", ln)  # list bullets and numbering
    ln = re.sub(r"^\[[ xX]?\]\s*", "", ln)  # task-list boxes: - [ ] X, - [x] X
    ln = ln.replace("~~", "")  # strikethrough
    if ln.startswith("#"):
        return ""
    ln = re.sub(r"\s+#.*$", "", ln)  # inline comment
    m = re.fullmatch(r"(\*\*|__)?\s*path:\s*(.*)", ln.strip(), re.I | re.S)
    if m:
        g = m.group(2).strip()  # a path glob keeps its * and _ ; only bold around the whole rule, quotes, backticks go
        if m.group(1) and g.endswith(m.group(1)):
            g = g[: -len(m.group(1))].strip()
        while len(g) > 1 and g[0] == g[-1] and g[0] in "`\"'":
            g = g[1:-1].strip()
        return "path:" + g
    ln = ln.strip().strip("*_`\"'").strip()  # markdown emphasis / quotes
    return ln


def _entry_terms(ln):
    """One cleaned line -> its terms. The whole line always counts; so do its comma/、/；-separated parts and the
    head of 'X - note', 'X — note', 'X: note', 'X（note）' (extra terms only make the guard stricter)."""
    out = [ln]
    parts = [p.strip().strip("*_`\"'").strip() for p in re.split(r"\s*[,，、;；/|]\s*", ln)]
    if len(parts) > 1:
        out += parts
    for p in list(out):
        kv = re.split(r"[:：]\s*", p, maxsplit=1)
        if len(kv) == 2:
            out += [x.strip().strip("*_`\"'").strip() for x in kv]  # 'Client: X' -> both sides
        head = re.split(r"\s+[-–—]\s+|\s*[（(]", p, maxsplit=1)[0].strip().strip("*_`\"'").strip()
        if head and head != p:
            out.append(head)
    return [t for t in dict.fromkeys(out) if len(t) >= 2 or (t and ord(t[0]) > 0x2E7F)]  # 1 char only if CJK


def home_terms():
    """Built-in private words: this machine's home folder path in its usual spellings (a home path in a repo is
    always a leak). The bare user name is not added: it is often a public handle too."""
    out = []
    for h in {str(Path.home()), os.environ.get("HOME") or ""}:
        h = h.rstrip("/\\")
        if len(h) >= 6 and h.count("/") + h.count("\\") >= 2:
            out += [h, h.replace("/", "\\"), h.replace("\\", "/")]
    return list(dict.fromkeys(out))


def load_private(d, extra=None):
    """(terms, path globs, files found). Missing files are reported by the caller (fail closed).
    Accepts plain lines, bullets, numbering, task boxes, **bold**, '# comments', comma lists, 'X - note' and
    markdown tables (first cell of each row; the header row and the --- row are skipped)."""
    terms, paths, found = [], [], []
    for f in [d / "PRIVATE.md"] + [Path(x).expanduser() for x in (extra or [])]:
        if not f.exists():
            continue
        found.append(f)
        raw_b = f.read_bytes()
        try:
            if raw_b[:2] in (b"\xff\xfe", b"\xfe\xff"):
                txt = raw_b.decode("utf-16")
            else:
                txt = raw_b.decode("utf-8-sig")
        except UnicodeDecodeError:
            sys.exit(f"{f.name}: not UTF-8 or UTF-16 text; save it as UTF-8 (the guard fails closed)")
        lines = txt.splitlines()
        for i, raw in enumerate(lines):
            s = raw.strip()
            if s.startswith("|"):
                cells = [c.strip() for c in s.strip("|").split("|")]
                if all(re.fullmatch(r":?-{2,}:?", c) for c in cells if c):
                    continue  # | --- | --- |
                nxt = lines[i + 1].strip() if i + 1 < len(lines) else ""
                if nxt.startswith("|") and re.fullmatch(r"[|\s:\-]+", nxt):
                    continue  # header row
                s = cells[0] if cells else ""
            ln = _clean_entry(s)
            if not ln:
                continue
            body = re.sub(r"^\s*(>\s*)*([-*+]|\d+[.)])?\s*(\[[ xX]?\]\s*)?", "", s)
            lit = re.fullmatch(r"(`|\"|')(.+)\1(\s+#.*)?", body.strip())  # a quoted entry keeps its own '#'
            body = re.sub(r"\s+#.*$", "", body).strip()
            lit = lit or re.fullmatch(r"(`|\"|')(.+)\1", body)
            if lit and not ln.lower().startswith("path:"):
                if len(lit.group(2).strip()) >= 2:  # one character would match every file
                    terms.append(lit.group(2).strip())  # quoted or `code`: the whole text, never split
                continue
            if re.match(r"(~|/|[A-Za-z]:[\\/]|\\\\)", ln) and not ln.lower().startswith("path:"):
                # a filesystem path (/Users/x, ~/x, C:\\x) counts whole: never split at / or :. A list of them
                # (`/a/x, /b/y` or `;`) adds each path whole; a bare `/` or `~` is too short to count.
                # a note after it (`X - note`, `X: note`, `X (note)`) is dropped first, as for any entry
                pl = re.sub(r"\s+-\s+.*$|:\s+.*$|\s+\([^()]*\)\s*$", "", ln).strip()
                terms += [p for p in (x.strip() for x in re.split(r"\s*[,;]\s+|\s*;\s*|,(?=[/~]|[A-Za-z]:[\\/])", pl)) if len(p) >= 3
                          and p not in ("~/", "//")]
                continue
            if ln.lower().startswith("path:"):
                g = ln[5:].strip()
                if g:
                    paths.append(g)
            else:
                terms += _entry_terms(ln)
    return list(dict.fromkeys(terms)), list(dict.fromkeys(paths)), found


def mask(term):
    return "*" * 5  # never reveal the word, its first letter or its length


class _Masker:
    def __init__(self, terms):
        self.res = [re.compile(re.escape(t), re.I) for t in sorted(terms, key=len, reverse=True)]

    def __call__(self, text):
        for r in self.res:
            text = r.sub("*****", text)
        return text


_GUARD_ENCODINGS = ("utf-8", "utf-16-le", "utf-16-be", "gb18030", "big5", "shift_jis", "cp1252", "latin-1")


def _needles(terms):
    """Escaped byte-regex alternatives for all supported encodings; phrase separators are matched together."""
    import unicodedata
    out = set()
    for t in terms:
        forms = {unicodedata.normalize(f, t) for f in ("NFC", "NFD")}
        for v in {x for f in forms for x in (f, f.lower(), f.upper(), f.title())}:
            for enc in _GUARD_ENCODINGS:
                try:
                    parts = re.split(r"([ _-]+)", v)
                    if len(parts) == 1:
                        out.add(re.escape(v.encode(enc).lower()))
                    elif all(parts[i] for i in range(0, len(parts), 2)):
                        sep = re.escape(" ".encode(enc).lower()) + b"|" + re.escape("_".encode(enc).lower()) + b"|" + re.escape("-".encode(enc).lower())
                        sep = b"(?:" + sep + b")+"
                        out.add(b"".join(sep if i % 2 else re.escape(part.encode(enc).lower())
                                          for i, part in enumerate(parts)))
                        words = [parts[i] for i in range(0, len(parts), 2)]
                        if all(len(re.findall(r"[A-Za-z]", word)) >= 4 for word in words):
                            out.add(b"".join(re.escape(word.encode(enc).lower()) for word in words))
                except (UnicodeEncodeError, LookupError):
                    continue
    return sorted((n for n in out if n), key=len)


GUARD_UNIT_CAP = 256 * 1024 * 1024


def _guard_unchecked(label, reason):
    print(f"guard: following {label or 'file'} was not fully checked ({reason})", file=sys.stderr)


def _bytes_has(data, needles, depth=0, label=""):
    """True if raw bytes hold any needle (case-insensitive for ASCII; other cases via the variants above).
    Zip-based files (docx, xlsx, pptx, odt, jar, zip) and gzip are opened and their contents checked too."""
    if isinstance(needles, str):
        needles = _needles([needles])
    low = data.lower()
    if _hit(needles, low):
        return True
    for alt in _decoded_views(data):  # escaped text, entities, percent encoding, and XML/HTML split tags
        if _hit(needles, alt):
            return True
    compressed = data[:4] == b"PK\x03\x04" or data[:2] == b"\x1f\x8b" or data[:3] == b"BZh" or data[:6] == b"\xfd7zXZ\x00"
    if depth >= 2:
        if compressed: _guard_unchecked(label or "archive", "nested deeper than 2 levels")
        return False
    import io
    if data[:5] == b"%PDF-":
        hit = False
        for raw, partial in _pdf_streams(data):
            hit = _bytes_has(raw, needles, depth + 1, label) or hit
            if partial: _guard_unchecked(label or "PDF", f"stream decompressed beyond {GUARD_UNIT_CAP // (1024 * 1024)} MB")
        return hit
    if data[:2] == b"\x1f\x8b" or data[:3] == b"BZh" or data[:6] == b"\xfd7zXZ\x00":
        import bz2, lzma, zlib
        gzip = data[:2] == b"\x1f\x8b"
        decoder = lambda: zlib.decompressobj(16 + zlib.MAX_WBITS) if gzip else \
            (bz2.BZ2Decompressor() if data[:3] == b"BZh" else lzma.LZMADecompressor())
        remaining, hit = data, False
        while remaining:
            dec = decoder()
            try: raw = dec.decompress(remaining, GUARD_UNIT_CAP)
            except (OSError, EOFError, ValueError, zlib.error, lzma.LZMAError):
                _guard_unchecked(label or "compressed file", "corrupt compressed data"); break
            hit = _bytes_has(raw, needles, depth + 1, label) or hit
            tail = getattr(dec, "unconsumed_tail", b"")
            if tail or (not dec.eof and len(raw) == GUARD_UNIT_CAP):
                _guard_unchecked(label or "compressed file", f"member decompressed beyond {GUARD_UNIT_CAP // (1024 * 1024)} MB")
                while not dec.eof:
                    try: dec.decompress(dec.unconsumed_tail if gzip else b"", GUARD_UNIT_CAP)
                    except (OSError, EOFError, ValueError, zlib.error, lzma.LZMAError): break
                    if not gzip and dec.needs_input: break
                if not dec.eof: break
            elif not dec.eof:
                _guard_unchecked(label or "compressed file", "truncated compressed member"); break
            remaining = dec.unused_data
        return hit
    if data[:4] == b"PK\x03\x04":
        import zipfile
        try:
            with zipfile.ZipFile(io.BytesIO(data)) as z:
                infos = z.infolist()
                if len(infos) > 2000:
                    _guard_unchecked(label or "archive", "over 2000 entries")
                for info in infos[:2000]:
                    if _bytes_has(info.filename.encode("utf-8", "replace"), needles, depth + 1, label):
                        return True
                    member_label = f"{label}/{info.filename}".strip("/")
                    with z.open(info) as member:
                        raw = member.read(GUARD_UNIT_CAP); partial = len(raw) == GUARD_UNIT_CAP and member.read(1) != b""
                    if partial: _guard_unchecked(member_label, f"entry decompressed beyond {GUARD_UNIT_CAP // (1024 * 1024)} MB")
                    if _bytes_has(raw, needles, depth + 1, member_label):
                        return True
        except Exception:
            _guard_unchecked(label or "archive", "corrupt zip")
            return False
    return False


def _hit(needles, low):
    if callable(needles): return needles(low)
    if not needles: return False
    return _compiled_needles(tuple(needles)).search(low) is not None


@functools.lru_cache(maxsize=16)
def _compiled_needles(needles):
    """Compile the private-word alternatives once per list; a regex scan avoids N full substring scans per file."""
    import re as _re
    literal, other = [], []
    special = b"\\. ^$*+?{}[]()|"
    for pattern in needles:
        if b"(?:" in pattern:
            other.append(pattern); continue
        value, i = bytearray(), 0
        while i < len(pattern):
            if pattern[i] == 92 and i + 1 < len(pattern) and pattern[i + 1] in special:
                i += 1
            elif pattern[i] in special:
                break
            value.append(pattern[i]); i += 1
        else:
            literal.append(bytes(value)); continue
        other.append(pattern)
    if len(literal) > 128:
        trie = {}
        for value in literal:
            node = trie
            for byte in value: node = node.setdefault(byte, {})
            node[None] = {}
        def emit(node):
            choices = [b""] if None in node else []
            choices += [(_re.escape(bytes((byte,))) + emit(child)) for byte, child in node.items() if byte is not None]
            return choices[0] if len(choices) == 1 else b"(?:" + b"|".join(choices) + b")"
        other.append(emit(trie))
    else:
        other.extend(_re.escape(value) for value in literal)
    return _re.compile(b"(?:" + b"|".join(other) + b")")


class HashedList:
    """Salted hashes of private words, for a cloud thread that must not see the words (SKILL step 3): a word is
    found anywhere in the text (as with the real guard), after NFC and case folding. No lengths are stored; decoys
    (random values, never hashes of a real string, so they cannot match) pad the list. The prefilter keeps 3 hex
    digits (4096 buckets) of each word's first three characters, so it narrows a guess but does not name the
    prefix; two-character words are checked directly. The salt ships with the list: anyone with the kit can still
    test guesses against it (a dictionary word or a short name falls fast). It stops an accidental push, not
    someone set on guessing. Text over 64 MB is not checked and counts as a hit (fails closed)."""

    MAXLEN = 64
    PRE = 3
    LIMIT = 64 * 1024 * 1024

    def __init__(self, salt, hashes, pre):
        import hashlib
        self.salt, self.hashes, self.pre = salt, set(hashes), set(pre)
        self._base = hashlib.sha256(salt.encode("utf-8"))

    @staticmethod
    def norm(t):
        import unicodedata
        return unicodedata.normalize("NFC", t).casefold()

    def h(self, t, n=20):
        x = self._base.copy()  # = sha256(salt + t), without hashing the salt again for every window
        x.update(t.encode("utf-8"))
        return x.hexdigest()[:n]

    @classmethod
    def make(cls, terms):
        import secrets
        salt = secrets.token_hex(16)
        self = cls(salt, [], [])
        words = [cls.norm(t) for t in terms if len(cls.norm(t)) >= 2]
        words = [w[: cls.MAXLEN] for w in words]
        n_decoys = len(words) + secrets.randbelow(8) + 3
        hashes = [self.h(w) for w in words] + [secrets.token_hex(10) for _ in range(n_decoys)]
        pre = [self.h(w[:3], cls.PRE) for w in words if len(w) >= 3] + \
            [secrets.token_hex(2)[:cls.PRE] for _ in range(secrets.randbelow(4))]
        secrets.SystemRandom().shuffle(hashes)
        secrets.SystemRandom().shuffle(pre)
        return {"teamwork_hashed_private_list": 1, "salt": salt, "hashes": hashes, "pre": sorted(set(pre))}

    @classmethod
    def load(cls, path):
        try:
            j = json.loads(Path(path).read_text(encoding="utf-8"))
            return cls(j["salt"], j["hashes"], j["pre"])
        except (OSError, ValueError, KeyError, TypeError):
            sys.exit(f"guard: FAILED, {path} is not a hashed private list (`tw.py guard --hash-list` makes one)")

    def kit(self):
        """A self-contained check script (stdlib only) for a cloud thread whose repo has no tw.py."""
        return KIT_TEMPLATE.replace("@SALT@", self.salt).replace("@H@", json.dumps(sorted(self.hashes))) \
            .replace("@P@", json.dumps(sorted(self.pre)))

    def __call__(self, low):
        if len(low) > self.LIMIT:
            return True  # too large to check: fail closed
        t = self.norm(low.decode("utf-8", "replace"))
        H, P, h = self.hashes, self.pre, self.h
        for i in range(len(t) - 1):
            if h(t[i:i + 2]) in H:
                return True
            if i + 3 <= len(t) and h(t[i:i + 3], self.PRE) in P:
                for j in range(i + 3, min(len(t), i + self.MAXLEN) + 1):
                    if h(t[i:j]) in H:
                        return True
        return False


KIT_TEMPLATE = r'''#!/usr/bin/env python3
# tw-guard.py: teamwork privacy check for a cloud thread. Keep it OUTSIDE the repo; never commit it.
# Salted hashes only: it stops accidental pushes, not someone guessing a word. Usage: python3 tw-guard.py origin/main
import hashlib, os, subprocess, sys, unicodedata
S, H, P = "@SALT@", set(@H@), set(@P@)
B = hashlib.sha256(S.encode("utf-8"))
def h(t, n):
    x = B.copy(); x.update(t.encode("utf-8")); return x.hexdigest()[:n]
def hit(b):  # same rule as tw.py's HashedList: 2-char words directly, longer ones behind a 3-char prefilter
    if len(b) > 64 * 1024 * 1024: return True  # too large to check: fail closed
    t = unicodedata.normalize("NFC", b.decode("utf-8", "replace")).casefold()
    for i in range(len(t) - 1):
        if h(t[i:i + 2], 20) in H: return True
        if i + 3 <= len(t) and h(t[i:i + 3], 3) in P:
            for j in range(i + 3, min(len(t), i + 64) + 1):
                if h(t[i:j], 20) in H: return True
    return False
base = sys.argv[1] if len(sys.argv) > 1 else "origin/main"
def g(*a):  # any git error fails closed: a wrong base or no repo must never print ok
    r = subprocess.run(["git", *a], capture_output=True)
    if r.returncode != 0:
        sys.exit("guard: FAILED, git " + a[0] + " failed (" + r.stderr.decode("utf-8", "replace").strip()[:200]
                 + "); check the base (git fetch first) and run it inside the repo")
    return r.stdout
g("rev-parse", "--verify", "--quiet", base + "^{commit}")
os.chdir(g("rev-parse", "--show-toplevel").decode("utf-8", "replace").strip())  # from a subfolder too: every file
bad = []
if hit(g("-c", "log.showRoot=true", "log", "--diff-merges=separate", "-p", "-m", "--text", "--format=%an %ae %cn %ce %B", base + "..HEAD")): bad.append("commits")
if hit(g("-c", "log.showRoot=true", "log", "--diff-merges=separate", "--name-only", "--format=", base + "..HEAD")): bad.append("a file name in the commits")
if hit(g("rev-parse", "--abbrev-ref", "HEAD")): bad.append("the branch name")
for n in [x for x in g("ls-files", "-z", "--cached", "--others", "--exclude-standard").split(b"\0") if x]:
    if not os.path.isfile(n):
        continue  # deleted in the work tree, a folder (submodule) or a dangling link: nothing to read
    try:
        data = open(n, "rb").read()
    except OSError:
        bad.append(n.decode("utf-8", "replace") + " (unreadable)"); continue
    if hit(n) or hit(data): bad.append("(a file name)" if hit(n) else n.decode("utf-8", "replace"))
print("guard: FAILED, private words in: " + ", ".join(bad) if bad else "guard: ok")
sys.exit(1 if bad else 0)
'''


def _decoded_views(data):
    """Lower-cased UTF-8 views of data with common text escapes undone, only when the data has such escapes:
    JSON/Python \\uXXXX, RTF \\uN (TextEdit), HTML/XML &#N; &#xH; &amp;, URL %XX, and XML/HTML with its tags
    removed (a docx word split into runs). Each view is checked like the raw bytes."""
    if len(data) > 64 * 1024 * 1024:
        return []
    out = []
    try:
        t = data.decode("utf-8")
    except UnicodeDecodeError:
        t = data.decode("latin-1")
    if "\\u" in t:
        def u4(m):
            return chr(int(m.group(1), 16))
        v = re.sub(r"\\u([0-9a-fA-F]{4})", u4, t)  # JSON / Python: exactly four hex digits
        try:
            v = v.encode("utf-16", "surrogatepass").decode("utf-16")  # join surrogate pairs
        except UnicodeError:
            pass
        out.append(v)
        def rtf(m):  # RTF: signed decimal, then one fallback character (?, \'hh or a space-separated char)
            c = int(m.group(1)) % 65536
            return "" if 0xD800 <= c <= 0xDFFF else chr(c)
        out.append(re.sub(r"\\u(-?\d{1,5}) ?(?:\\'[0-9a-fA-F]{2}|\?)?", rtf, t))
    if re.search(r"\\x[0-9a-fA-F]{2}", t):
        out.append(re.sub(r"\\x([0-9a-fA-F]{2})", lambda m: chr(int(m.group(1), 16)), t))
    if "&" in t and ";" in t:
        import html
        out.append(html.unescape(t))
    if re.search(r"%[0-9a-fA-F]{2}", t):
        from urllib.parse import unquote
        out.append(unquote(t, errors="replace"))
        if re.search(r"%25[0-9a-fA-F]{2}", t, re.I):
            out.append(unquote(unquote(t, errors="replace"), errors="replace"))
    if "</" in t or "/>" in t or re.search(r"<[^<>]{1,2000}>", t):
        import html
        stripped = re.sub(r"<[^<>]{0,2000}>", "", t)
        compact = re.sub(r">\s+<", "><", t)
        out.append(html.unescape(stripped + "\n" + re.sub(r"<[^<>]{0,2000}>", "", compact)))
    return [v.lower().encode("utf-8", "replace") for v in out]


def _pdf_streams(data):
    """Decoded content of a PDF's streams (FlateDecode via zlib) plus the text shown with Tj/TJ joined, so
    '(Zor) -20 (blax) TJ' reads as Zorblax. Fonts with custom encodings are not decoded."""
    import zlib
    out = []
    for m in re.finditer(rb"stream\r?\n", data):
        start = m.end()
        end = data.find(b"endstream", start)
        if end < 0:
            break
        raw = data[start:end]
        partial = False
        try:
            dec = zlib.decompressobj()
            raw = dec.decompress(raw, GUARD_UNIT_CAP)
            partial = bool(dec.unconsumed_tail)
        except zlib.error:
            pass
        strings = re.findall(rb"\(((?:\\.|[^\\)])*)\)", raw)
        hexes = re.findall(rb"<([0-9A-Fa-f\s]{2,})>", raw)
        joined = b"".join(re.sub(rb"\\(.)", rb"\1", x) for x in strings)
        for h in hexes:
            try:
                joined += bytes.fromhex(h.decode().replace(" ", "").replace("\n", ""))
            except ValueError:
                pass
        if joined:
            raw += b"\n" + joined
        out.append((raw, partial))
        if len(out) > 4000:
            break
    return out


def _path_rule_hit(name, g):
    """gitignore-like and case-insensitive: 'secrets/*', '/secrets/', 'Notes.md' (any folder), '**/x'."""
    import fnmatch
    n = name.lower().lstrip("/")
    g = g.lower().strip()
    anchored = g.startswith("/")
    g = g.lstrip("/")
    core = g.rstrip("/")
    if not core:
        return False
    if fnmatch.fnmatchcase(n, core) or fnmatch.fnmatchcase(n, core + "/*") or n.startswith(core + "/"):
        return True
    if fnmatch.fnmatchcase(n, core.replace("**/", "")):
        return True
    if not anchored and "/" not in core:
        return any(fnmatch.fnmatchcase(c, core) for c in n.split("/"))  # bare name: any folder level
    if not anchored and core.startswith("**/"):
        return any(fnmatch.fnmatchcase("/".join(n.split("/")[i:]), core[3:]) for i in range(len(n.split("/"))))
    return False


def guard_scan(repo, rng, ref, terms, paths, worktree=True, refnames=(), hashed=None):
    """Hits [(where, what)] for the commits in rng (git rev args; messages, author/committer, diffs incl. binary
    and merges, changed paths), tag objects, the tree of ref, ref names, and (worktree=True) every non-ignored
    file in the checkout (names and bytes). Nothing private is printed: names are masked."""
    rp = str(repo)

    env = {**os.environ, "GIT_NO_REPLACE_OBJECTS": "1"}  # scan what is really sent, not local replacements

    def git(*x, text=True, inp=None):
        return subprocess.run(["git", "-c", "core.quotePath=false", "-C", rp, *x], capture_output=True, text=text,
                              input=inp, env=env)

    if git("rev-parse", "--git-dir").returncode != 0:
        sys.exit(f"{repo} is not a git repository")
    # literal parts of path rules are private too: never print them
    rule_words = [w for g in paths for w in re.split(r"[*?\[\]{}/,]+", g) if len(w) >= 2]
    m = _Masker(list(terms) + rule_words) if hashed is None else \
        (lambda x: "(name hidden)" if hashed(x.lower().encode("utf-8", "replace")) else x)
    needles = _needles(terms) if hashed is None else hashed
    hits = []

    def name_hits(where, name, show=None):
        shown = m(show if show is not None else name)
        if any(_path_rule_hit(name, g) for g in paths):
            shown = "(name hidden)"
        if _bytes_has(name.encode("utf-8", errors="replace"), needles):
            hits.append((f"{where} {shown}", "private word in a name"))
        for i, g in enumerate(paths, 1):
            if _path_rule_hit(name, g):
                hits.append((f"{where} {shown}", f"private path rule #{i}"))

    for rn in refnames:
        name_hits("ref name", rn)
    if rng:
        raw = git("-c", "log.showRoot=true", "log", "--diff-merges=separate", "--encoding=UTF-8", "-p", "-m", "--text", "--no-textconv", "--no-ext-diff", "--no-renames",
                  "--format=%x00commit %H%n%an <%ae>%n%cn <%ce>%n%B", *rng, text=False).stdout
        for chunk in raw.split(b"\x00commit ")[1:]:
            if _bytes_has(chunk, needles):
                hits.append((f"history {chunk[:12].decode('ascii', 'replace')}", "private word"))
        names = git("-c", "log.showRoot=true", "log", "--diff-merges=separate", "-m", "--no-renames", "--name-only", "-z", "--format=", *rng, text=False).stdout
        for n in {x.decode("utf-8", errors="replace").strip("\n") for x in names.split(b"\0")}:
            if n:
                name_hits("history path", n)
    def scan_blobs(blobs, where):
        if not blobs:
            return
        out = git("cat-file", "--batch", inp=b"".join(x.encode() + b"\n" for x, _ in blobs), text=False).stdout
        pos = 0
        for sha, pth in blobs:
            nl = out.index(b"\n", pos)
            head = out[pos:nl].split()
            if len(head) != 3:  # "<sha> missing"
                pos = nl + 1
                continue
            size = int(head[2])
            data = out[nl + 1:nl + 1 + size]
            pos = nl + 1 + size + 1
            if _bytes_has(data, needles, label=pth):
                hits.append((f"{where}{m(pth)}", "private word"))

    def scan_tree(tree, label):
        ls = git("ls-tree", "-r", "-z", tree, text=False).stdout
        blobs = []
        for e in [x for x in ls.split(b"\0") if x]:
            meta, _, path = e.partition(b"\t")
            pth = path.decode("utf-8", errors="replace")
            name_hits(f"tree {label}:", pth)
            f = meta.split()
            if len(f) == 3 and f[1] == b"blob":  # symlinks are blobs too: their target text is scanned
                blobs.append((f[2].decode(), pth))
        scan_blobs(blobs, f"tree {label}:")

    if rng:  # every blob the pushed commits add, read whole: archives (docx, zip, gz) deep in a diff get opened
        rawl = git("log", "-m", "--no-renames", "--raw", "--no-abbrev", "-z", "--format=", *rng, text=False).stdout
        items, blobs = rawl.split(b"\0"), {}
        for i, e in enumerate(items):
            if e.lstrip(b"\n").startswith(b":") and i + 1 < len(items):
                f = e.lstrip(b"\n").split()
                if len(f) >= 5 and set(f[3]) != {ord("0")}:
                    blobs.setdefault(f[3].decode(), items[i + 1].decode("utf-8", errors="replace"))
        scan_blobs(list(blobs.items()), "history file ")

    # every tag object on the way down (nested tags too), and whatever the chain ends at
    ends = set()
    for t in dict.fromkeys([ref] + [x for x in refnames if x.startswith("refs/tags/")]):
        if not t:
            continue
        obj, seen = t, set()
        while git("cat-file", "-t", obj).stdout.strip() == "tag" and obj not in seen:
            seen.add(obj)
            body = git("cat-file", "-p", obj, text=False).stdout
            if _bytes_has(body, needles):
                hits.append((f"tag {m(t)}", "private word in a tag message"))
            mo = re.match(rb"object ([0-9a-f]{40,64})", body)
            if not mo:
                break
            obj = mo.group(1).decode()
        kind = git("cat-file", "-t", obj).stdout.strip()
        end = git("rev-parse", "--verify", "--quiet", obj).stdout.strip() or obj
        if end in ends:
            continue
        ends.add(end)
        if kind == "blob":  # also a lightweight tag that names a blob directly
            scan_blobs([(end, "(tagged blob)")], f"tag {m(t)} -> ")
        elif kind == "tree":
            scan_tree(end, f"{m(t)}^{{tree}}")
    # the tree that is being pushed / merged, every blob in raw bytes
    if ref and git("rev-parse", "--verify", "--quiet", ref + "^{commit}").returncode == 0:
        scan_tree(ref + "^{commit}", m(ref))
    if worktree:
        out = git("ls-files", "-z", "--cached", "--others", "--exclude-standard", text=False).stdout
        for n in [x.decode("utf-8", errors="replace") for x in out.split(b"\0") if x]:
            name_hits("worktree", n)
            if n.startswith(".teamwork/private/") or n == ".teamwork/PRIVATE.md":
                hits.append(("worktree .teamwork/" + ("private/*****" if "/private/" in n else "PRIVATE.md"),
                             "private folder is tracked or not ignored"))
            fp = Path(rp) / n
            try:
                # a symlink is committed as its target path, so scan that text, never the file it points to
                data = os.readlink(fp).encode("utf-8", "replace") if fp.is_symlink() else fp.read_bytes()
            except OSError:
                continue
            if _bytes_has(data, needles, label=n):
                hits.append((f"worktree {m(n)}", "private word"))
    return list(dict.fromkeys(hits))


def cmd_guard(a):
    if a.hash_list:
        d = need(find_dir())
        terms, _, found = load_private(d, a.private)
        if not found:
            sys.exit(f"guard: no private list {d / 'PRIVATE.md'}")
        missing = [str(Path(x).expanduser()) for x in (a.private or []) if not Path(x).expanduser().exists()]
        if missing:
            sys.exit("guard: no private list " + ", ".join(missing))
        # no home path here: it would hand the cloud thread a guessable user name, and a cloud container's home
        # differs anyway; the lead's own guard checks the home path when the branch comes back
        j = HashedList.make(terms)
        print(HashedList(j["salt"], j["hashes"], j["pre"]).kit() if a.kit else json.dumps(j))
        return
    hashed = HashedList.load(a.hashed) if a.hashed else None
    if hashed is not None:  # a cloud thread: no .teamwork here, only the hashed list from its TASK
        d, st, terms, paths, found = None, {}, [], [], [a.hashed]
    else:
        d = need(find_dir())
        st = load(d)
        terms, paths, found = load_private(d, a.private)
        missing = [str(Path(x).expanduser()) for x in (a.private or []) if not Path(x).expanduser().exists()]
        if missing:
            sys.exit("guard: no private list " + ", ".join(missing))
    terms = terms + [t for t in home_terms() if hashed is None and t.lower() not in {x.lower() for x in terms}]
    if not found:
        sys.exit(f"guard: FAILED, no private list: create {d / 'PRIVATE.md'} (tw.py init does; it may stay empty "
                 "if the user has nothing private)")
    repo = Path(a.repo or os.getcwd()).resolve()
    if hashed is None and (repo / ".gitmodules").is_file():
        print("guard: note: submodule contents are not scanned; inspect them separately", file=sys.stderr)
    if hashed is None:
        gitdir = subprocess.run(["git", "-C", str(repo), "rev-parse", "--git-path", "info/grafts"], capture_output=True, text=True)
        if gitdir.returncode == 0:
            grafts = Path(gitdir.stdout.strip())
            if not grafts.is_absolute(): grafts = repo / grafts
            if grafts.exists():
                sys.exit("guard: FAILED, .git/info/grafts changes the history view; remove grafts before scanning")
    genv = {**os.environ, "GIT_NO_REPLACE_OBJECTS": "1"}
    git = lambda *x: subprocess.run(["git", "-C", str(repo), *x], capture_output=True, text=True, env=genv)
    ok = lambda r: git("rev-parse", "--verify", "--quiet", r + "^{commit}").returncode == 0
    jobs = []  # (rev args for the commits to scan, ref whose tree is scanned, ref names)
    if a.pre_push:
        # git pre-push: argv remote name; stdin <local ref> <local sha> <remote ref> <remote sha>
        remote, advertised = a.remote, None
        lines = sys.stdin.read().splitlines()
        if not [x for x in lines if x.strip()] and a.stdin_owned:
            print("guard: ok (nothing to push)")  # git runs the hook with empty stdin when everything is up to date
            return
        if not [x for x in lines if x.strip()]:
            sys.exit("guard: FAILED, the pre-push hook got no refs on stdin: another command in the hook read it "
                     "first (git lfs pre-push does). Save it once with input=$(cat) and pipe \"$input\" to each "
                     "command (install.py --pre-push prints the lines); the guard fails closed")
        for ln in lines:
            parts = ln.split()
            if len(parts) != 4 or set(parts[1]) == {"0"}:
                continue  # deleting a remote branch sends nothing
            local_ref, local_sha, remote_ref, remote_sha = parts
            tip = git("rev-parse", "--verify", "--quiet", local_sha + "^{commit}").stdout.strip()
            if not tip:
                rng = None  # a tag on a blob or tree: guard_scan peels and scans it
            elif not set(remote_sha) == {"0"} and ok(remote_sha):
                rng = [f"{remote_sha}..{tip}"]
            else:
                # Branch new on this remote. Local remote-tracking refs can be stale (the remote URL changed),
                # so exclude only commits the server itself advertises now; offline: scan everything.
                if advertised is None:
                    advertised = []
                    if remote:
                        pu = git("remote", "get-url", "--push", remote)  # pushurl / pushInsteadOf: where it goes
                        r = git("ls-remote", pu.stdout.strip() if pu.returncode == 0 and pu.stdout.strip()
                                else remote)
                        advertised = [x.split()[0] for x in r.stdout.splitlines() if x.split()] \
                            if r.returncode == 0 else []
                    advertised = [x for x in dict.fromkeys(advertised) if ok(x)]
                rng = [tip, "--not", *advertised] if advertised else [tip]
            jobs.append((rng, local_sha, [local_ref, remote_ref]))
    else:
        ref = a.ref
        if a.base:
            if not ok(a.base):
                sys.exit(f"base {a.base} not found (git fetch first, or pass --base)")
            base = a.base
        else:
            b = st.get("repo", {}).get("base") or "main"
            base = f"origin/{b}" if ok(f"origin/{b}") else b
            if not ok(base):
                sys.exit(f"base {base} not found (git fetch first, or pass --base)")
        full = git("rev-parse", "--symbolic-full-name", ref).stdout.strip()
        jobs.append(([f"{base}..{ref}"], ref, [x for x in dict.fromkeys((ref, full)) if x and x != "HEAD"]))
    if not terms and not paths and hashed is None:
        print(f"guard: ok (private list {found[0]} is empty)")
        return
    hits = []
    for i, (rng, ref, names) in enumerate(jobs):
        hits += guard_scan(repo, rng, ref, terms, paths, worktree=not a.pre_push and i == 0, refnames=names,
                           hashed=hashed)
    hits = list(dict.fromkeys(hits))
    if hits:
        print(f"guard: FAILED, {len(hits)} private hit(s). Remove them (history hits need the commits rewritten "
              "before any push):")
        for where, what in hits:
            print(f"  {where}: {what}")
        sys.exit(1)
    print("guard: ok (hashed list: words anywhere in the text, no path rules; the lead re-checks with the real list)" if hashed is not None
          else f"guard: ok ({len(terms)} words, {len(paths)} paths checked)")


def _read_log(d):
    out = []
    if (d / "log.jsonl").exists():
        for ln in (d / "log.jsonl").read_bytes().decode("utf-8", errors="replace").split("\n"):
            if not ln.strip():
                continue
            try:
                e = json.loads(ln)
            except ValueError:
                continue
            if isinstance(e, dict):
                out.append(e)
    return out


def trace_data(d, st, r):
    q = st["requests"][r]
    repo = st.get("repo", {}).get("path")
    git = (lambda *x: subprocess.run(["git", "-c", "core.quotePath=false", "-C", repo, *x],
                                     capture_output=True, text=True)) if repo else None
    is_git = bool(git) and git("rev-parse", "--git-dir").returncode == 0
    base = _base_ref(st, git) if is_git else None
    warnings = []
    if is_git and base is None:
        warnings.append(f"base branch {st.get('repo', {}).get('base') or 'main'} not found: commits on the base "
                        "cannot be listed (fix repo.base)")
    log_all = _read_log(d)
    linked = q.get("tasks") or []
    def ids_of(e):  # hand-edited logs may hold anything here
        v = e.get("ids")
        return csv(v) if isinstance(v, str) else [str(x) for x in v] if isinstance(v, list) else []
    events = [e for e in log_all
              if e.get("req") == r or e.get("task") in linked or r in ids_of(e)]
    # T1 is not T10, T1.5, T1a, T1-2 or T1_x
    idre_of = lambda tid: re.compile(rf"(^|[^A-Za-z0-9_]){re.escape(tid)}(?![0-9A-Za-z_]|[.-][0-9A-Za-z])")
    any_linked = [idre_of(x) for x in linked]
    since = [f"--since={st['created']}"] if st.get("created") else []
    tasks, other_work, other_seen = [], {}, set()
    for tid in linked:
        k = st["tasks"].get(tid, {})
        owners = []  # every thread that ever owned it, current one last
        for e in log_all:
            if e.get("task") == tid:
                delta = e.get("delta") or {}
                changes = delta.get("tasks") if isinstance(delta.get("tasks"), dict) else {}
                sn = (changes.get(tid) if isinstance(changes.get(tid), dict) else
                      e.get("snap_task") if isinstance(e.get("snap_task"), dict) else {})
                o = sn.get("owner") or e.get("owner")
                if isinstance(o, str) and o and o not in owners:
                    owners.append(o)
        if k.get("owner"):
            owners = [o for o in owners if o != k["owner"]] + [k["owner"]]
        th = st["threads"].get(k.get("owner") or "", {})
        item = {"task": tid, "title": k.get("title"), "status": k.get("status"), "review": k.get("review"),
                "checks": k.get("checks"), "touches": k.get("touches") or [], "owners": owners,
                "thread": k.get("owner"), "thread_status": th.get("status"), "session_id": th.get("session_id"),
                "sessions": [h.get("session_id") for h in th.get("sessions", [])],
                "session_history": th.get("sessions", []),
                "branch": th.get("branch"), "worktree": th.get("worktree"), "commits": []}
        if is_git:
            idre = idre_of(tid)
            seen = set()
            for o in owners:
                br0 = (st["threads"].get(o) or {}).get("branch")
                for br in ([br0, f"origin/{br0}"] if br0 else []):
                    if not base or git("rev-parse", "--verify", "--quiet", br).returncode != 0:
                        continue
                    for x in git("log", "--format=%h %ad %s", "--date=short", f"{base}..{br}").stdout.splitlines():
                        h = x.split(" ", 1)[0]
                        if h in seen:
                            continue
                        seen.add(h)
                        subj = x.split(" ", 2)[-1]
                        if idre.search(subj):
                            item["commits"].append(f"(unmerged {br}) {x}")
                        elif o == k.get("owner") and k.get("status") not in ("done", "dropped", "recalled") \
                                and not any(rx.search(subj) for rx in any_linked) and h not in other_seen:
                            other_seen.add(h)  # listed once, under the first branch that has it
                            other_work.setdefault(br, []).append(x)
            if base:
                for x in git("log", "--format=%h %ad %s", "--date=short", "-E", *since,
                             f"--grep=(^|[^A-Za-z0-9]){re.escape(tid)}([^0-9]|$)", base).stdout.splitlines():
                    if x.split(" ", 1)[0] not in seen and idre.search(x.split(" ", 2)[-1]):
                        item["commits"].append(f"({base}) {x}")
        tasks.append(item)
    return {"request": r, **{k: q.get(k) for k in ("text", "status", "where", "followup", "created", "updated",
                                                   "reported_at", "closed_at", "closed_reason", "closed_note")},
            "tasks": tasks, "other_branch_work": other_work, "events": events, "warnings": warnings,
            "followups": [{"task": t, "title": x.get("title"), "status": x.get("status"), "owner": x.get("owner"),
                           "followup_of": x.get("followup_of"),
                           **({"parent_verdict_voided": x["parent_verdict_voided"]}
                              if x.get("parent_verdict_voided") else {})}
                          for t, x in st["tasks"].items() if r in (x.get("from_requests") or [])]}


def cmd_trace(a):
    d = need(find_dir())
    st = load(d)
    r = a.request
    if r not in st.get("requests", {}):
        sys.exit(f"unknown request {r}; known: {', '.join(st.get('requests', {})) or '-'}")
    t = trace_data(d, st, r)
    if a.json:
        print(json.dumps(t, ensure_ascii=False, indent=2))
        return
    L = lambda k: lab(st, k)
    out = [f"{r} [{L('req_' + t['status'])}] {t['text']}",
           f"  {L('t_created')} {t['created'] or '-'}  {L('t_reported')} {t['reported_at'] or '-'}"
           + (f"  {L('t_closed')} {t['closed_at'] or '-'} ({t['closed_reason']})" if t["status"] in REQ_END else "")]
    if t.get("closed_note"):
        out.append(f"  {L('t_closed')}: {t['closed_note']}")
    if t["where"]:
        out.append(f"  {L('t_where')}: {t['where']}")
    if t["followup"]:
        out.append(f"  {L('followup')}: {t['followup']}")
    for w in t["warnings"]:
        out.append(f"  ! {w}")
    if not t["tasks"]:
        out.append(f"  ({L('t_no_tasks')}: `req link {r} T<n>`)")
    for k in t["tasks"]:
        rv = k["review"] or {}
        out.append(f"  - {k['task']} [{k['status']}] {k['title']}"
                   + (f"  review {rv.get('result')} ({rv.get('reviewer') or '-'})" if rv else ""))
        out.append(f"      {L('t_thread')} {k['thread'] or '-'} [{k['thread_status'] or '-'}]"
                   f"  {L('t_session')} {k['session_id'] or '-'}  {L('t_branch')} {k['branch'] or '-'}"
                   + (f"  (owners: {' -> '.join(k['owners'])})" if len(k["owners"]) > 1 else ""))
        if len(k.get("session_history") or []) > 1:
            out.append("      sessions: " + " -> ".join(
                f"{h.get('session_id')}" + (f" ({h['reason']})" if h.get("reason") else "")
                for h in k["session_history"]))
        for c in k["commits"]:
            out.append(f"      {c}")
    for f in t.get("followups") or []:
        out.append(f"  - {f['task']} [{f['status']}] follow-up of {f['followup_of']} (does not hold {r}): {f['title']}"
                   + (f" (its verdict was voided: {f['parent_verdict_voided']})" if f.get("parent_verdict_voided") else ""))
    for br, cs in t["other_branch_work"].items():
        out.append(f"  {L('t_other')} {br}:")
        out += [f"      {c}" for c in cs]
    if t["events"]:
        out.append(f"  {L('t_log')}:")
        for e in t["events"]:
            out.append(f"    {e.get('t', '')} {e.get('ev')} " + " ".join(
                f"{x}={e[x]}" for x in ("req", "task", "status", "owner") if e.get(x)))
    print("\n".join(out))


def archive_candidates(st):
    rows = []
    lead_sid = (st.get("lead") or {}).get("session_id")
    live_sids = {t.get("session_id") for t in st.get("threads", {}).values()
                 if t.get("status") in ("working", "starting", "waiting", "review", "landing") and t.get("session_id")}
    cutoff = _when(now()) - dt.timedelta(days=int(pref(st, 'archive_idle_days')))
    for name, t in st.get("threads", {}).items():
        sessions = t.get("sessions") or []
        current = t.get("session_id")
        live = t.get("status") in ("working", "starting", "waiting")
        reported_current = bool(current and (t.get("last_report_session") == current or any(
            h.get("session_id") == current and _later(t.get("last_status_at"), _when(h.get("from")) or EPOCH)
            for h in sessions)))
        for h in sessions:
            sid = h.get("session_id")
            other_current = any(n != name and x.get("status") != "archived" and x.get("session_id") == sid
                                for n, x in st.get("threads", {}).items())
            if not sid or sid == lead_sid or sid in live_sids or other_current or st.get("archive", {}).get(sid, {}).get("archived_at"):
                continue
            if h.get("to") and h.get("reason") and t.get("session_id") != sid and reported_current and t.get("status") != "starting":
                ho=next((x["id"] for x in st.get("handovers",{}).values() if x.get("phase") in ("seated","retired") and x.get("old_session")==sid and x.get("seat")==name),None)
                why=lab(st,"archive_replaced_handover",handover=ho) if ho else lab(st,"archive_replaced")
                rows.append({"session_id": sid, "seat": name, "category": "replaced", "reason": why})
        sid = current
        if not sid or sid == lead_sid or sid in live_sids or st.get("archive", {}).get(sid, {}).get("archived_at"):
            continue
        disconnected = bool(t.get("disconnected"))
        if disconnected:
            rows.append({"session_id": sid, "seat": name, "category": "disconnected", "reason": lab(st, "archive_disconnected_note")})
        stamp = _when(t.get("last_status_at") or t.get("last_seen") or t.get("created"))
        if not disconnected and t.get("status") in ("idle", "resolved") and stamp and stamp < cutoff:
            rows.append({"session_id": sid, "seat": name, "category": "idle-old", "reason": lab(st, "archive_idle_note")})
    for h in st.get("handovers", {}).values():
        if h.get("kind") != "lead" or h.get("phase") not in ("seated", "retired") or not h.get("old_session"):
            continue
        sid = h["old_session"]
        if sid == lead_sid or sid in live_sids or st.get("archive", {}).get(sid, {}).get("archived_at"):
            continue
        missing_ack = len(set(h.get("ack_needed", [])) - set(h.get("acks", [])))
        missing_move = len(set(h.get("move_items", [])) - set(h.get("moved", [])))
        if h.get("move_none_required") and not h.get("move_none"): missing_move = max(1, missing_move)
        if h.get("move_none") and not h.get("move_items"): missing_move = 0
        blockers = []
        if missing_ack: blockers.append(lab(st,"succ_archive_ack",n=missing_ack))
        if missing_move: blockers.append(lab(st,"succ_archive_move",n=missing_move))
        if not h.get("window") or not h.get("reconciled"): blockers.append(lab(st,"succ_archive_window"))
        rows.append({"session_id":sid,"seat":"lead","category":"blocked-replaced" if blockers else "replaced",
                     "reason":lab(st,"succ_reason_sep").join(blockers) if blockers else lab(st,"succ_archive_lead",id=h["id"])})
    return rows


def cmd_archive(a):
    d = need(find_dir()); st = load(d)
    st["archive"]
    if a.action == "candidates":
        rows = archive_candidates(st)
        print(json.dumps(rows, ensure_ascii=False) if a.json else "\n".join(
            f"{x['session_id']} [{x['seat']}] {x['category']}: {x['reason']}" for x in rows) or "(none)")
        return
    if a.action == "list":
        rows = [{"session_id": sid, **rec, "restore": lab(st, "archive_restorable"),
                 "result": lab(st, "archive_failed") if rec.get("check") == "failed" else lab(st, "archive_verified")}
                for sid, rec in st["archive"].items() if rec.get("archived_at")]
        current_sids = {t.get("session_id") for t in st.get("threads", {}).values()  # back at work: no longer a failed archive
                        if t.get("session_id") and t.get("status") in ("working", "starting", "waiting", "review", "landing")}
        failed = [{"session_id": sid, **rec} for sid, rec in st["archive"].items()
                  if rec.get("check") == "failed" and not rec.get("archived_at") and sid not in current_sids]
        if a.json: print(json.dumps({"archived": rows, "failed": failed}, ensure_ascii=False))
        else:
            print("\n".join(f"{x['session_id']} [{x.get('seat')}] {x['archived_at']} — {x['result']}; {x['restore']}" for x in rows) or "(none)")
            if failed: print("\n".join(f"{x['session_id']} [{x.get('seat')}] — {lab(st, 'archive_failed')}" for x in failed))
        return
    sid = a.session_id
    if a.action in ("verify","done") and any((h.get("phase") not in ("aborted","retired") and (sid == h.get("successor") or any(c.get("session_id")==sid and not c.get("void") for c in h.get("candidates",[])))) for h in st.get("handovers",{}).values()):
        sys.exit("handover candidate or successor cannot be archived")
    candidates = {x["session_id"]: x for x in archive_candidates(st)}
    if a.action in ("verify", "done") and sid in candidates and candidates[sid].get("category") == "blocked-replaced":
        sys.exit(candidates[sid].get("reason") or "lead handover follow-up is incomplete")
    if a.action in ("verify", "done") and sid not in candidates:
        sys.exit(f"{sid} is not an archive candidate")
    if a.action == "verify" and candidates[sid].get("category") != "replaced":
        seat = candidates[sid].get("seat")
        pending_tasks = [(tid, k) for tid, k in st.get("tasks", {}).items()
                         if k.get("owner") == seat and k.get("status") not in ("done", "dropped", "recalled")]
        pending_asks = [q for q in st.get("questions", []) if q.get("from") == seat and not q.get("answered") and not q.get("answered_at")]
        pending_issues = [i for i in st.get("issues", []) if i.get("owner") == seat and i.get("status") not in ("verified", "merged")]
        unmerged = False
        thread = st.get("threads", {}).get(seat) or {}
        try:
            repo = Path((st.get("repo") or {}).get("path") or d.parent)
            base_branch = (st.get("repo") or {}).get("base") or "main"
            branch = thread.get("branch")
            if branch:
                count = subprocess.run(["git", "-C", str(repo), "rev-list", "--count", f"{base_branch}..{branch}"], capture_output=True, text=True, timeout=5)
                unmerged = count.returncode == 0 and int(count.stdout.strip() or "0") > 0
        except (OSError, ValueError, subprocess.TimeoutExpired):
            pass
        merged_recorded = any(e.get("ev") == "merge" and e.get("thread") == seat for e in _read_log(d))
        blockers = [*(f"task {tid}" for tid, _ in pending_tasks),
                    *(f"ask {q.get('id') or q.get('text')}" for q in pending_asks),
                    *(f"issue {i.get('id')}" for i in pending_issues),
                    *( [f"branch {thread.get('branch')} has unmerged commits"] if unmerged and not merged_recorded else [])]
        if blockers and not (getattr(a, "handed_to", None) or getattr(a, "park", None)):
            sys.exit(lab(st, "archive_handover_needed", items=", ".join(blockers)))
        target = getattr(a, "handed_to", None)
        if target:
            if target == seat:
                sys.exit(lab(st, "archive_handover_needed", items=f"{seat} cannot hand work to itself"))
            if target != "lead" and target not in st.get("threads", {}): sys.exit(f"unknown handoff owner {target}")
            for n in st.get("notices", []):
                if n.get("kind") == "parked" and n.get("original_owner") == seat and not n.get("done"): n.update(done=True, handed_to=target)
            for tid, k in pending_tasks:
                k.setdefault("owner_history", []).append({"owner": seat, "at": now()})
                k.setdefault("past_owners", []).append(seat)
                k["owner"] = target
            for q in pending_asks: q["owner"] = target
            for i in pending_issues: i["owner"] = target
            if blockers:
                st["archive_handoffs"].append({"session": sid, "from": seat, "to": target,
                                                               "items": blockers, "at": now()})
        elif getattr(a, "park", None):
            for item in blockers:
                notices = st["notices"]
                if not any(n.get("kind") == "parked" and n.get("text") == item and
                           n.get("original_owner") == seat and n.get("reason") == a.park and not n.get("done")
                           for n in notices):
                    notices.append({"thread": "lead", "kind": "parked", "text": item,
                        "original_owner": seat, "reason": a.park, "at": now(), "done": False})
    rec = st["archive"].setdefault(sid, {})
    if a.action == "verify":
        if not a.stopped.strip(): sys.exit("archive verify needs --stopped with evidence")
        rec.update({"verified_at": now(), "evidence": a.stopped.strip(), "seat": candidates[sid]["seat"],
                    "category": candidates[sid]["category"],
                    "report_count": st["threads"].get(candidates[sid]["seat"], {}).get("report_count", 0)})
        seat_name = candidates[sid]["seat"]
        current = st.get("threads", {}).get(seat_name, {})
        if current.get("session_id") == sid:
            archives = st["archive_packs"]
            existing = next(((key, value) for key, value in archives.items() if value.get("session") == sid), None)
            if existing:
                archive_id, pack = existing
                out_dir, gaps = Path(pack["dir"]), pack.get("gaps", [])
            else:
                archive_id = f"AR{len(archives) + 1}"
                pack_rec = {"seat": seat_name, "kind": "archive", "old_session": sid, "freeze": {"at": now()}}
                out_dir, gaps, written = _pack_session(d, st, archive_id, pack_rec, a)  # reuse successor extraction
                archives[archive_id] = {"session": sid, "seat": seat_name, "dir": str(out_dir), "at": now(), "gaps": gaps, "files": written}
            print(lab(st, "succ_pack_line", path=out_dir / "BRIEF.md", gap=lab(st, "succ_gap"), n=len(gaps)), file=sys.stderr)

    elif a.action == "done":
        if not rec.get("verified_at"):
            sys.exit(lab(st, "archive_verify_first"))
        refreshed = {x["session_id"]: x for x in archive_candidates(st)}
        if sid not in refreshed:
            sys.exit(f"{sid} is no longer an archive candidate")
        t = st["threads"].get(rec.get("seat"), {})
        if rec.get("category") == "replaced" and t.get("last_report_session") == sid and \
                _later(t.get("last_status_at"), _when(rec["verified_at"]) or EPOCH):
            sys.exit("the archived session reported after verification; verify again")
        if (rec.get("category") != "replaced" or t.get("last_report_session") == sid) and (int(t.get("report_count") or 0) != int(rec.get("report_count") or 0) or \
                _later(t.get("last_status_at"), _when(rec["verified_at"]) or EPOCH)):
            sys.exit("a newer report arrived after verification; verify again")
        direct_disconnected=rec.get("category")=="disconnected" and bool(pref(st, 'archive_disconnected_direct'))
        if rec.get("category") in ("disconnected", "idle-old") and not direct_disconnected and not (a.user_said or "").strip():
            sys.exit("this category needs --user-said (user decision)")
        rec["archived_at"] = now()
        if "archive" in pref(st, 'standing_grants'):
            st.setdefault("grant_uses", []).append({"grant": "archive", "at": now(), "what": sid})
        rec.pop("check", None); rec.pop("checked_at", None)
        rec["user_said"] = (a.user_said or "").strip()
        if direct_disconnected: rec["direct_disconnected_id_verified"] = sid
        handoff = next((x for x in reversed(st.get("archive_handoffs", [])) if x.get("session") == sid), None)
        receiver = handoff.get("to") if handoff else "lead"
        thread = st.get("threads", {}).get(rec.get("seat"), {})
        delivery = thread.get("branch") or next((x.get("link") for x in st.get("docs", {}).values() if x.get("link")), None) or "-"
        if t.get("session_id") == sid:  # the seat's own session goes: tell the team who owns the area now (a replaced one changes nothing)
            rec["receiver"] = receiver
            print(model_lab(st, "archive_broadcast", seat=rec.get('seat'), who=receiver, where=delivery), file=sys.stderr)
        if rec.get("category") != "replaced" and t.get("session_id") == sid:
            rec["thread_status_before"] = t.get("status")
            t["status"] = "archived"
            t["last_seen"] = now()
            t.pop("stuck_on", None); t.pop("waiting_for", None)
            bump_roster(st, rec.get("seat"))
    elif a.action == "check":
        if not (a.still_archived or a.not_archived): sys.exit("archive check needs --still-archived or --not-archived")
        if not rec.get("archived_at"): sys.exit("session has no archived record")
        if a.still_archived:
            rec["checked_at"] = now(); rec["check"] = "still-archived"
        else:
            checked = now()
            rec.setdefault("history", []).append({"verified_at": rec.get("verified_at"), "evidence": rec.get("evidence"),
                "archived_at": rec.get("archived_at"), "check": "failed", "checked_at": checked})
            rec.pop("verified_at", None); rec.pop("evidence", None); rec.pop("archived_at", None)
            rec["checked_at"] = checked; rec["check"] = "failed"
            seat = rec.get("seat")
            t = st.get("threads", {}).get(seat, {})
            if t.get("session_id") == sid and t.get("status") == "archived" and rec.get("thread_status_before"):
                t["status"] = rec["thread_status_before"]
                t["last_seen"] = now()
                bump_roster(st, seat)
            print(lab(st, "archive_failed_notice", sid=sid), file=sys.stderr)
    save(d, st, {"ev": f"archive-{a.action}", **({"user_said": rec.get("user_said")} if a.action == "done" else {})})
    print(json.dumps(rec, ensure_ascii=False))


def _succ_save(d, st, rec, step, record_step=True):
    stamp = _when(now())
    prior = [_when(x) for x in rec.setdefault("steps", {}).values()]
    prior = [x for x in prior if x]
    if prior and stamp <= max(prior): stamp = max(prior) + dt.timedelta(seconds=1)
    value = stamp.astimezone().isoformat(timespec="seconds")
    if record_step: rec["steps"][step] = value
    event={"ev":"succ-"+step,"handover":rec["id"]}
    if rec.get("kind")=="lead" and step=="seat": event["lead_change"]={"from":rec.get("old_session"),"to":rec.get("successor")}
    save(d, st, event)


_SUCC_SECRET_RE = re.compile(r"(?P<secret>\bsk-[A-Za-z0-9_-]{12,}|\bAKIA[A-Z0-9]{16}\b|\bghp_[A-Za-z0-9]{20,}|\bxox[A-Za-z0-9-]{10,}|-----BEGIN [A-Z ]*KEY-----|(?i:password|token|secret)\s*[=:]\s*[^\s,;]+)", re.ASCII)


def _succ_redact(value):
    if not isinstance(value, str): return value, 0
    return _SUCC_SECRET_RE.sub("[REDACTED]", value), len(_SUCC_SECRET_RE.findall(value))


def _succ_scrub(value):
    if isinstance(value, str): return _succ_redact(value)[0]
    if isinstance(value, list): return [_succ_scrub(x) for x in value]
    if isinstance(value, dict): return {k:_succ_scrub(v) for k,v in value.items()}
    return value


def _succ_answer_path(st, value):
    text = str(value or "")
    keydir = _keys_dir(st).expanduser().resolve()
    keypaths = {str(keydir), str(keydir).replace(str(Path.home()), "~", 1)
                if str(keydir).startswith(str(Path.home())) else str(keydir)}
    escaped = "|".join(re.escape(x.rstrip("/")) for x in sorted(keypaths, key=len, reverse=True))
    return bool((escaped and re.search(r"(?:" + escaped + r")(?=$|[/\\\s'\"])", text, re.I)) or
                re.search(r"(?<![A-Za-z0-9])(?:SC\d+(?:-grade\.md|\.json)|HO\d+-(?:quiz|used)(?:[-.]|\b))", text, re.I))


def _succ_git_snapshot(st, branch=None, repo_override=None):
    candidates=[repo_override, st.get("repo",{}).get("path")]
    here=find_dir()
    if here: candidates.append(str(Path(here).parent))  # the project folder itself when no repo path is recorded
    repo=next((x for x in candidates if x and Path(x).is_dir()), None)
    if not repo: return {"available":False,"head":"-","fingerprint":"-","dirty_files":[],"unpushed":[]}
    def git(*args): return subprocess.run(["git","-C",repo,*args],capture_output=True)
    if git("rev-parse","--git-dir").returncode: return {"available":False,"head":"-","fingerprint":"-","dirty_files":[],"unpushed":[]}
    head=git("rev-parse","HEAD").stdout.decode(errors="replace").strip() or "-"
    mine=["--",".",":(exclude).teamwork"]  # the ledger and the handover pack change during a handover by design
    diff=git("diff","HEAD","--binary",*mine).stdout
    names=git("ls-files","--others","--exclude-standard","-z",*mine).stdout.split(b"\0")
    untracked=[]; untracked_hashes={}; digest=hashlib.sha256(diff)
    for raw in names:
        if not raw: continue
        rel=os.fsdecode(raw); untracked.append(rel); path=Path(repo)/rel
        try:
            content=path.read_bytes(); untracked_hashes[rel]=hashlib.sha256(content).hexdigest(); digest.update(raw+b"\0"+content)
        except OSError: digest.update(raw+b"\0-")
    status=git("status","--porcelain","-z",*mine).stdout.decode(errors="replace")
    dirty=[x[3:] for x in status.split("\0") if len(x)>3]
    target=branch or ""
    base=st.get("repo",{}).get("base") or "main"
    remote=f"origin/{target}" if target and git("rev-parse","--verify","--quiet",f"refs/remotes/origin/{target}").returncode==0 else (f"origin/{base}" if git("rev-parse","--verify","--quiet",f"refs/remotes/origin/{base}").returncode==0 else base)
    unpushed=git("log","--format=%H","--reverse",f"{remote}..{target}").stdout.decode(errors="replace").splitlines() if target and git("rev-parse","--verify","--quiet",target).returncode==0 else []
    return {"available":True,"head":head,"fingerprint":digest.hexdigest() if diff or untracked else "-","dirty_files":sorted(set(dirty)),"unpushed":unpushed,"base":remote,"status":status,"untracked_hashes":untracked_hashes}


def _succ_relay_count(st, seat, today=None):
    today=today or _when(now()).date()
    count=0
    for h in st.get("handovers",{}).values():
        if h.get("seat")!=seat or h.get("phase") not in ("seated","retired"): continue
        stamp=_when((h.get("steps") or {}).get("seat"))
        if stamp and stamp.astimezone().date()==today: count+=1
    return count


def _succ_normalize(text):
    return "".join(unicodedata.normalize("NFKC",str(text)).lower().split())


def _succ_keywords(text):
    """Content words in the order the user said them: ASCII words, and Chinese phrases (no spaces to split on)."""
    terms=[]
    for m in re.finditer(r"[a-z0-9]+|[\u3400-\u9fff]{2,}",text.lower()):
        w=m.group(0)
        if re.match(r"[\u3400-\u9fff]",w):
            w=re.sub(r"^(?:不要|别|不能|必须|永远|记住|改成|要求|用户)+", "", w)
            if len(w)<2: continue
            w=w[:8]
        elif len(w)<3 or w in {"the","and","for","you","not","don","doesn","isn","with","this","that","use","from","into","are","all","any"}: continue
        terms.append(w)
    stop={"不要","不能","必须","用户","要求","记住","永远","改成","这个","那个","请勿","不要碰","不要改","don","never","always"}
    return list(dict.fromkeys(x for x in terms if x not in stop))[:3]


def _succ_hit(key, norm):
    """A keyword is said: ASCII words must appear; a Chinese phrase counts when most of its characters appear."""
    key=_succ_normalize(key)
    if not key: return False
    for words in (("yes","是","对","存在","true"),("no","否","不","没有","false")):  # a yes/no answer counts in either language
        if key in words:
            other=("no","否","不","没有","false") if words[0]=="yes" else ("yes","是","对","存在","true")
            said=lambda ws: any(re.search(rf"(?<![a-z]){re.escape(w)}(?![a-z])",norm) for w in ws)
            return said(words) and not (key in ("yes","是","对","存在","true") and said(("no","否","不是","false")))
    if not re.search(r"[\u3400-\u9fff]",key): return key in norm
    chars=set(key)
    return sum(c in norm for c in chars)*10>=len(chars)*6


def _succ_quiz_material(rec, st):
    root=Path(rec.get("pack_dir") or "")
    material=[]
    def latest(name):
        stem=Path(name).stem; suffix=Path(name).suffix
        paths=list(root.glob(stem+"*"+suffix))
        return max(paths,key=lambda p: (0 if p.stem==stem else int(p.stem.rsplit("-",1)[-1]) if p.stem.rsplit("-",1)[-1].isdigit() else -1)) if paths else root/name
    words=latest("words.md")
    if words.exists():
        entries=[]
        for line in words.read_text(encoding="utf-8").splitlines():  # an entry runs until the next numbered line
            if re.match(r"(★ )?\[(#|L#|P#)\d+\] ",line) or not entries: entries.append(line)
            else: entries[-1]+="\n"+line
        for line in entries:
            if re.match(r"\[[LP]#\d+\] \[tw:[^\]]*\][^\n]*\n",line):  # the [tw:] header says who and what type, not what
                line=line.split("] ",1)[0]+"] "+line.split("\n",1)[1]
            line=" ".join(line.split()) if not line.startswith("★") else line
            m=re.match(r"★ \[#\d+\] (.*)",line)
            if not m:
                m=re.match(r"\[[LP]#\d+\] (.*)",line)
                if m:
                    text=m.group(1).replace("[REDACTED]"," ").replace("[含打码]"," ").replace("[redacted]"," ")
                    key=[k for k in _succ_keywords(text) if k.lower()!="redacted"]
                    if len(key)>=2:
                        material.append({"question":lab(st,"succ_question_lead",x=key[0]),"keywords":key[1:4]})
                continue
            text=m.group(1).replace("[REDACTED]"," ").replace("[含打码]"," ").replace("[redacted]"," ")
            key=[k for k in _succ_keywords(text) if k.lower()!="redacted"]
            if key and len(key[0])>2 and re.search(r"[\u3400-\u9fff]",key[0]):  # name the first two characters, ask for the rest
                key=[key[0][:2],key[0][2:],*key[1:]]
            if len(key)>=2:  # the question names one word; the answer must bring the others back
                material.append({"question":lab(st,"succ_question_user",x=key[0]),"keywords":key[1:4]})
    try: facts=json.loads(latest("facts.json").read_text(encoding="utf-8"))
    except (OSError,ValueError): facts={}
    if facts.get("branch") and facts["branch"]!="-":
        material.append({"question":lab(st,"succ_question_branch"),"keywords":[facts["branch"]]})
    for task in facts.get("tasks",[]):
        accept=task.get("done_when") or ""
        words=_succ_keywords(accept)
        if words: material.append({"question":lab(st,"succ_question_task",task=task.get("id")),"keywords":words})
    material.append({"question":lab(st,"succ_question_unpushed"),"keywords":[str(len(facts.get("unpushed_commits",[])))]})
    for f in facts.get("files",[]):
        material.append({"question":lab(st,"succ_question_file",path=f.get("path")),"keywords":[lab(st,"succ_yes" if f.get("exists") else "succ_no")]})
    for rid,q in facts.get("requests",{}).items():
        material.append({"question":lab(st,"succ_question_request",id=rid),"keywords":[rid,str(q.get("status",""))]})
    unique={}
    for item in material:
        key=(item["question"],tuple(item.get("keywords",[])))
        unique.setdefault(key,item)
    return list(unique.values())


_BRIDGE_UNVERIFIED=object()


def _succ_bridge_remote(local_id, config_dirs):
    if not local_id: return None
    saw_bridge=False
    for config in config_dirs:
        for bridge in Path(config).glob("bridge-transcript-cse_*.jsonl"):
            saw_bridge=True
            try:
                if str(local_id).encode("utf-8") not in bridge.read_bytes(): continue
                with bridge.open(encoding="utf-8") as stream:
                    for line in stream:
                        if not line.strip(): continue
                        try: row=json.loads(line)
                        except ValueError: continue
                        if isinstance(row,dict) and str(row.get("session_id") or "").strip()==str(local_id).strip():
                            return "session_"+bridge.stem.removeprefix("bridge-transcript-cse_").removeprefix("session_")
            except (OSError,UnicodeError): continue
    # A miss remains unverified while bridge metadata exists.
    return _BRIDGE_UNVERIFIED if saw_bridge else None


def _succ_bridge_locals(remote_session, config_dirs):
    """Return local session UUIDs claimed by any row in the remote session's bridge."""
    if not remote_session: return set()
    suffix=str(remote_session).removeprefix("session_")
    locals_found=set()
    for config in config_dirs:
        bridge=Path(config)/f"bridge-transcript-cse_{suffix}.jsonl"
        if not bridge.is_file(): continue
        try:
            with bridge.open(encoding="utf-8") as stream:
                for line in stream:
                    if not line.strip(): continue
                    try: row=json.loads(line)
                    except ValueError: continue
                    local=row.get("session_id") if isinstance(row,dict) else None
                    if isinstance(local, str) and local.strip(): locals_found.add(local.strip())
        except (OSError,UnicodeError): continue
    return locals_found


def _succ_transcript_rows(path, expected_session=None, config_dirs=None):
    """Read successor records through the shared transcript and platform-result parsers."""
    raw_export=None
    try:
        p=Path(path)
        rows, _bad = _transcript_rows(p)
        if expected_session and p.suffix.lower()==".json":
            raw_export=json.loads(p.read_text(encoding="utf-8"))
            export_rows=_tool_rows(raw_export,("data","events","items"))
            if export_rows is not None:
                rows=_rows_from_events(export_rows)
    except (OSError, ValueError, UnicodeError):
        # A saved list_events tool result may be a text-only <other-session>
        # wrapper, which is not itself JSONL even when the export uses .json.
        try:
            raw_export=Path(path).read_text(encoding="utf-8")
            payload=_tool_rows(raw_export, ("data", "events", "items"))
        except (OSError, UnicodeError):
            return []
        rows=_rows_from_events(payload) if payload is not None else []
    if len(rows) == 1:
        page = _tool_rows(rows[0], ("data", "events", "items"))
        if page is not None:
            rows=_rows_from_events(page)
    configs=config_dirs if config_dirs is not None else [Path.home()/".claude",*Path.home().glob(".claude-*")]
    if expected_session:
        expected=str(expected_session).strip()
        p=Path(path)
        if p.suffix.lower()!=".json":
            # Local Claude JSONL rows are attributable only through the bridge for
            # the requested remote session. A filename is never ownership proof.
            local_ids=_succ_bridge_locals(expected,configs)
            if not local_ids or not rows:
                return []
            # Platform bookkeeping (for example file-history records) has no
            # dialogue or tool payload and is not an ownership-bearing transcript row.
            content_rows=[]
            for row in rows:
                blocks=_row_blocks(row)
                if blocks is None:
                    return []
                if any(isinstance(block,dict) and block.get("type") in ("text","input_text","tool_use","tool_call","tool_result","tool_output") for block in blocks):
                    content_rows.append(row)
            rows=content_rows
            if not rows:
                return []
            for row in rows:
                owner=row.get("sessionId") or row.get("session_id")
                if owner and str(owner).strip() not in local_ids or not owner and p.stem not in local_ids:
                    return []
        else:
            if isinstance(raw_export,str):
                raw_export=_tool_json(raw_export)
            wrapper_owners=set()
            def collect_wrappers(value):
                if isinstance(value,list):
                    for item in value: collect_wrappers(item)
                elif isinstance(value,dict):
                    ccr=value.get("ccr")
                    if isinstance(ccr,dict):
                        sid=ccr.get("id")
                        if isinstance(sid,str) and sid.strip(): wrapper_owners.add(sid.strip())
                    for child in value.values(): collect_wrappers(child)
            collect_wrappers(raw_export)
            if wrapper_owners:
                if wrapper_owners!={expected}: return []
            else:
                event_rows=_tool_rows(raw_export,("data","events","items"))
                if not event_rows: return []
                paired={}
                def blocks_for(event):
                    msg=event.get("message")
                    content=msg.get("content",[]) if isinstance(msg,dict) else event.get("content",[])
                    return content if isinstance(content,list) else []
                for event in event_rows:
                    for block in blocks_for(event):
                        if not isinstance(block,dict) or block.get("type")!="tool_use": continue
                        inp=block.get("input")
                        sid=inp.get("session_id") if isinstance(inp,dict) else None
                        if isinstance(sid,str) and sid.strip() and block.get("id"):
                            paired[block["id"]]=sid.strip()
                for event in event_rows:
                    owners=set()
                    sid=event.get("session_id")
                    if isinstance(sid,str) and sid.strip(): owners.add(sid.strip())
                    for block in blocks_for(event):
                        if not isinstance(block,dict): continue
                        if block.get("type")=="tool_use":
                            inp=block.get("input")
                            sid=inp.get("session_id") if isinstance(inp,dict) else None
                            if isinstance(sid,str) and sid.strip(): owners.add(sid.strip())
                        elif block.get("type")=="tool_result" and block.get("tool_use_id") in paired:
                            owners.add(paired[block["tool_use_id"]])
                    if owners!={expected}: return []
    stem=Path(path).stem
    remote=_succ_bridge_remote(stem,configs) if not expected_session and re.fullmatch(r"[0-9a-fA-F]{8}-[0-9a-fA-F-]{27}",stem) else None
    if remote is _BRIDGE_UNVERIFIED: return []
    if remote:
        local_ids=_succ_bridge_locals(remote,configs)
        if not local_ids or stem not in local_ids: return []
        for row in rows:
            owner=row.get("sessionId") or row.get("session_id")
            if owner and str(owner).strip() not in local_ids: return []
    return rows


def _succ_zero_tool_window(rows, question, answer_lines):
    answer_tokens=list(dict.fromkeys(x.strip() for x in answer_lines if x.strip()))
    def text(row):
        if _row_role(row)=="tool_result": return ""
        blocks=_row_blocks(row) or []
        parts=[str(x.get("text") or x.get("content") or "") for x in blocks if isinstance(x,dict)]
        for block in blocks:
            if not isinstance(block,dict): continue
            if block.get("type")=="tool_use" and block.get("name")=="mcp__claude-code-remote__send_message":
                inp=block.get("input") or {}
                if all(token in str(inp.get("message", "")) for token in answer_tokens):
                    parts.append(str(inp.get("message", "")))
        return " ".join(parts)
    qidx=next((i for i,r in enumerate(rows) if question and question in text(r)),None)
    if qidx is None: return False
    seen=set(); aidx=None
    for i in range(qidx+1,len(rows)):
        body=text(rows[i])
        seen.update(tok for tok in answer_tokens if tok in body)
        if answer_tokens and len(seen)==len(answer_tokens):
            aidx=i; break
    if aidx is None: return False
    for row in rows[qidx+1:aidx]:
        content=_row_blocks(row)
        if content is None: return False
        if any(isinstance(block,dict) and block.get("type")=="tool_use" and
                block.get("name")!="mcp__claude-code-remote__send_message" for block in content): return False
    return True


def _succ_get_session_results(rows):
    results={}; calls={}
    for row in rows:
        content=(row.get("message") or {}).get("content",[])
        blocks=content if isinstance(content,list) else []
        for block in blocks:
            if isinstance(block,dict) and block.get("type")=="tool_use" and "get_session" in str(block.get("name")):
                inp=block.get("input") or {}; sid=inp.get("session_id") or inp.get("id")
                if sid: calls[block.get("id")]=sid
        for block in blocks:
            if not isinstance(block,dict) or block.get("type")!="tool_result" or block.get("tool_use_id") not in calls: continue
            raw=_tool_result_text(block.get("content"))
            value=_tool_json(raw)
            if value is None: value={"status":raw} if raw else {}
            if isinstance(value,dict):
                if isinstance(value.get("ccr"),dict): value=dict(value["ccr"])  # the platform's real shape
                returned=value.get("session_id") or value.get("sessionId") or value.get("id")
                requested=calls[block["tool_use_id"]]
                if returned and str(returned).strip()!=str(requested).strip(): continue
                if "connection_status" in value: value.setdefault("connected",value.get("connection_status")=="connected")
                if "archived" not in value and value.get("session_status"):
                    value["archived"]="ARCHIV" in str(value.get("session_status")).upper()
                if value.get("status_bucket"): value["status_bucket"]=str(value["status_bucket"]).lower().replace("session_status_bucket_","")
                value["_record_at"]=row.get("timestamp") or row.get("created_at") or row.get("time")
                previous=results.get(requested) or {}; current_at=_when(value["_record_at"]); previous_at=_when(previous.get("_record_at"))
                if requested not in results or (current_at and (not previous_at or current_at>previous_at)): results[requested]=value
    return results


def _pack_session(d, st, hid, rec, a):
    """Extract a handover pack for rec["old_session"] from its record into .teamwork/private/handover/<hid>-<seat>/ (T58 J11).
    Shared by `succ pack` and the archive handover (J2). Returns (pack dir, gaps, files written)."""
    base=d.parent/".teamwork"/"private"/"handover"/f"{hid}-{rec['seat']}"; base.mkdir(parents=True,exist_ok=True)
    old_files=[p for p in base.iterdir() if p.name!="superseded"]
    if old_files:  # a re-pack replaces the whole set; the old one is kept aside, never mixed with the new names
        aside=base/"superseded"/now().replace(":","").replace("+","p"); aside.mkdir(parents=True,exist_ok=True)
        for p in old_files: p.rename(aside/p.name)
    gaps=[]; rows=[]; paths=[]
    searched_dirs=[]
    for path in a.transcript or []:
        p=Path(path)
        if p.exists(): paths.append(p)
        else: gaps.append(lab(st,"succ_missing_transcript",path=path))
    cfg=list(dict.fromkeys([*(_config_dirs() if not a.config_dir else []), *(a.config_dir or [])]))
    if not a.transcript:
        versions = d / "session-versions.jsonl"
        if versions.exists():
            for line in versions.read_text(encoding="utf-8", errors="replace").splitlines():
                try: config_dir = json.loads(line).get("config_dir")
                except (ValueError, AttributeError): continue
                if isinstance(config_dir, str) and config_dir and config_dir not in cfg:
                    cfg.append(config_dir)
        searched_dirs = cfg
        paths = _find_transcripts(rec.get("old_session"), cfg)

    skipped_answer_files=0
    for p in paths:
        try:
            found=_succ_transcript_rows(p, rec.get("old_session"), cfg)
            child_record=bool(re.search(SUBAGENT_ID_RE, p.stem))
            answer_reference=_succ_answer_path(st,p.as_posix()) or any(_succ_answer_path(st,json.dumps(row,ensure_ascii=False)) for row in found)
            if child_record and answer_reference:
                skipped_answer_files += 1
                continue
            found=[{**row,"_handover_source":str(p)} for row in found]
            if child_record:
                found=[{**row,"_handover_subagent":True} for row in found]
            rows += found
        except (OSError,ValueError): gaps.append(lab(st,"succ_unreadable_transcript",path=p))
    if skipped_answer_files: gaps.append(lab(st,"succ_skipped_answers",n=skipped_answer_files))
    if a.transcript and not rows: sys.exit("pack transcript contains zero readable records; unverified")
    if not rows and not a.transcript:
        dirs = ", ".join(searched_dirs) or "-"
        gaps.append(f"Transcript extraction failed: no readable source rows were available; {lab(st, 'succ_no_transcript', dirs=dirs)}")

    seat_sessions=(st.get("threads",{}).get(rec["seat"]) or {}).get("sessions",[])
    stint=next((x for x in seat_sessions if x.get("session_id")==rec.get("old_session")),None)
    stint_from=_when(stint.get("from")) if stint else None
    freeze_at=_when((rec.get("freeze") or {}).get("at"))
    screen_windows=[]
    for screen in st.get("screens",{}).values():
        if screen.get("session_id") != rec.get("old_session"): continue
        cutoff=screen.get("cleared_at") or screen.get("graded_at") or screen.get("created_at")
        screen_windows.append((_when(screen.get("created_at")),_when(cutoff)))
        if not screen.get("cleared_at"):
            gaps.append(lab(st,"succ_screen_uncleared",id=next((k for k,v in st.get("screens",{}).items() if v is screen),"SC?"),at=cutoff or "-"))
    compact_count=sum(bool(x.get("isCompactSummary") or x.get("type") in ("compact_boundary","summary")) for x in rows)
    kept=[]
    for row in rows:
        stamp=_when(row.get("timestamp") or row.get("created_at") or row.get("createdAt") or row.get("time"))
        if stamp and ((stint_from and stamp < stint_from) or (freeze_at and stamp > freeze_at)): continue
        invalid=bool(stamp and any((begin is None or stamp>=begin) and (end is None or stamp<=end) for begin,end in screen_windows))
        if invalid: row["_handover_window"]=lab(st,"succ_tests_void")
        kept.append(row)
    rows=kept
    key_tool_ids=set(); answer_rows=set(); cwd_keys=False; last_source=None
    for row_index,row in enumerate(rows):
        source=row.get("_handover_source")
        if source != last_source:
            cwd_keys=False; last_source=source
        msg=row.get("message") or {}; content=msg.get("content",[])
        blocks=content if isinstance(content,list) else []
        for block in blocks:
            if not isinstance(block,dict): continue
            if block.get("type")=="tool_use":
                name=block.get("name"); inp=block.get("input") or {}
                if name=="Bash":
                    command=str(inp.get("command") or "")
                    cd_matches=list(re.finditer(r"(?:^|[;&|]\s*)cd\s+(?:([\"'])(.*?)\1|([^;&|\s]+))",command))
                    hit_command=_succ_answer_path(st,command)
                    for match in cd_matches:
                        destination=match.group(2) if match.group(1) else match.group(3)
                        if _succ_answer_path(st,destination): cwd_keys=True
                        else: cwd_keys=False
                    if hit_command or cwd_keys:
                        if block.get("id") is not None: key_tool_ids.add(block.get("id"))
                        answer_rows.add(row_index)
                elif _succ_answer_path(st,json.dumps(block,ensure_ascii=False)):
                    if block.get("id") is not None: key_tool_ids.add(block.get("id"))
                    answer_rows.add(row_index)
            elif block.get("type")=="tool_result" and block.get("tool_use_id") in key_tool_ids:
                answer_rows.add(row_index)
        if any(isinstance(b,dict) and b.get("type")=="tool_result" and b.get("tool_use_id") in key_tool_ids
               for b in blocks):
            answer_rows.add(row_index)
    sanitized=[]
    for row_index,row in enumerate(rows):
        if row_index in answer_rows or _succ_answer_path(st,json.dumps(row,ensure_ascii=False)):
            sanitized.append({"type":row.get("type"),"timestamp":row.get("timestamp"),
                              "message":{"content":"[redacted answer key path]"}})
        else:
            sanitized.append({k:v for k,v in row.items() if k != "_handover_source"})
    rows=sanitized
    tool_map={}; file_ops={}; commands=[]; failures=[]; urls=set()
    for row in rows:
        msg=row.get("message") or {}; blocks=msg.get("content",[])
        if not isinstance(blocks,list): blocks=[]
        for block in blocks:
            if not isinstance(block,dict): continue
            if block.get("type")=="tool_use":
                name=block.get("name",""); inp=block.get("input") or {}; tid=block.get("id")
                if name in ("Read","Edit","Write","NotebookEdit"):
                    target=inp.get("file_path") or inp.get("path")
                    if target: file_ops[str(target)]=name
                if name=="Bash":
                    command=_succ_redact(str(inp.get("command") or ""))[0]
                    tool_map[tid]={"command":command}; commands.append(command)
            if block.get("type")=="tool_result":
                raw=_tool_result_text(block.get("content")); urls.update(re.findall(r"https?://[^\s)\]>]+",raw))
                tid=block.get("tool_use_id")
                exit_code=block.get("exit_code",block.get("code"))
                if block.get("is_error") or (isinstance(exit_code,int) and exit_code!=0) or re.search(r"(?:exit(?:ed)?(?: with)? code|status)\s*[:=]?\s*[1-9][0-9]*",raw,re.I):
                    failures.append({"tool_use_id":tid,"command":tool_map.get(tid,{}).get("command"),"result":_succ_redact(raw[:500])[0]})
        rawtext=json.dumps(row,ensure_ascii=False)
        if _succ_answer_path(st,rawtext):
            row={"type":row.get("type"),"timestamp":row.get("timestamp"),"message":{"content":"[redacted answer key path]"}}
            rawtext=json.dumps(row,ensure_ascii=False)
        urls.update(u.rstrip(").,;]'\"") for u in re.findall(r"https?://[^\s\"'<>]+",rawtext))
    file_facts=[]
    for name,op in sorted(file_ops.items()):
        p=Path(name); p=p if p.is_absolute() else Path(st.get("repo",{}).get("path") or d.parent)/p
        file_facts.append({"path":name,"operation":op,"exists":p.exists()})
    words=[]; peer_words=[]; compact=[]; users=0; peers=0
    for row in rows:
        role=_row_role(row)
        content=_row_text(row)
        stamp=_when(row.get("timestamp") or row.get("created_at") or row.get("createdAt") or row.get("time"))
        invalid=row.get("_handover_window")==lab(st,"succ_tests_void")
        if row.get("isCompactSummary") or row.get("type") in ("compact_boundary","summary"):
            compact=[_succ_redact(str(content))[0]]
        elif compact and role=="user" and not invalid: compact.append(_succ_redact(str(content))[0])
        if role not in ("user","peer"): continue
        if invalid: continue
        peer_message=role=="peer"
        if not row.get("_handover_subagent") and role=="user":
            users+=1; redacted,count=_succ_redact(str(content)); rule=bool(re.search(r"不要|别|改成|永远|记住|必须|always|never|don't|do not",redacted,re.I))
            words.append(f"{'★ ' if rule else ''}[#{users}] {redacted}" + (f" {lab(st,'succ_redacted')}" if count else ""))
        elif peer_message:
            sender,peer_text=_peer_message(str(content))
            if sender and sender in {c.get("session_id") for c in rec.get("candidates") or []}: continue  # the candidate's own test traffic
            leads={st.get("lead",{}).get("session_id")}|{x.get("session_id") for x in st.get("lead",{}).get("sessions") or []}
            tag="L" if sender is None or sender in leads else "P"
            peers+=1; peer_words.append(f"[{tag}#{peers}] {_succ_redact(peer_text)[0]}")
    t=st.get("threads",{}).get(rec["seat"],{}); branch=t.get("branch","-")
    snap=_succ_git_snapshot(st,branch,t.get("worktree"))
    open_tasks=[{"id":k,"title":v.get("title"),"done_when":v.get("accept"),"status":v.get("status"),"touches":v.get("touches",[]),"requests":[]} for k,v in st.get("tasks",{}).items() if v.get("owner")==rec["seat"] and v.get("status") not in ("done","dropped")]
    if not snap["available"]: gaps.append(lab(st,"succ_git_missing"))
    if any(not (x.get("timestamp") or x.get("created_at") or x.get("createdAt") or x.get("time")) for x in rows): gaps.append(lab(st,"succ_timestamp_missing"))
    related={r:{"status":q.get("status"),"tasks":q.get("tasks",[])} for r,q in st.get("requests",{}).items() if set(q.get("tasks",[])) & {x["id"] for x in open_tasks}}
    for task in open_tasks:
        linked=set((st.get("tasks",{}).get(task["id"]) or {}).get("requests",[]))
        req=(st.get("tasks",{}).get(task["id"]) or {}).get("req")
        if req: linked.add(req)
        linked.update(r for r,recq in related.items() if task["id"] in recq["tasks"])
        for r in linked:
            if r in st.get("requests",{}): related.setdefault(r,{"status":st["requests"][r].get("status"),"tasks":st["requests"][r].get("tasks",[])})
        task["requests"]=[{"id":r,"status":st.get("requests",{}).get(r,{}).get("status","unknown")} for r in sorted(linked)]
    facts={"files":file_facts,"commands":commands,"failed_commands":failures,"urls":sorted(urls),"branch":branch,"head":snap["head"],"unpushed_commits":snap["unpushed"],"dirty_files":snap["dirty_files"],"leases":sorted({x for task in open_tasks for x in task.get("touches",[])}),"tasks":open_tasks,"requests":related}
    if not any(file_ops.values()): gaps.append(lab(st,"succ_no_file_ops"))
    if not commands: gaps.append(lab(st,"succ_no_commands"))
    if not urls: gaps.append(lab(st,"succ_no_urls"))
    if not words and not peer_words:
        if rows:
            gaps.append("No user-authored statements in this seat term; transcript extraction completed with zero eligible user messages.")
        else:
            gaps.append("Transcript extraction failed: no readable source rows were available, so user-authored statements could not be assessed.")
    lead_extra = ""
    if rec.get("kind") == "lead":
        rec["cutoff_at"] = now()
        promise_re=re.compile(r"[^。！？.!?\n]*(?:我会|稍后|完了告诉你|I'll|I will)[^。！？.!?\n]*[。！？.!?]?",re.I)
        for row in rows:
            if _row_role(row)!="assistant": continue
            text=_row_text(row)
            for match in promise_re.finditer(text):
                promise=match.group(0).strip()
                if promise and not any(p.get("source_handover")==hid and p.get("text")==promise for p in st["promises"]):
                    promises=st["promises"]
                    pid="P"+str(max([int(re.search(r"\d+",str(p.get("id","P0"))).group(0)) for p in promises if re.search(r"\d+",str(p.get("id","")))] or [0])+1)
                    promises.append({"id":pid,"text":promise,"confidence":"low","source_handover":hid,"owner":"lead","status":"open","at":now()})
        rec["move_items"] = []
        team = [{"seat":n,"session":t.get("session_id"),"status":t.get("status"),"summary":t.get("summary"),"unmerged_commits":t.get("unmerged_commits",[])} for n,t in st.get("threads",{}).items()]
        lists=[]
        for arg, label in ((getattr(a,"triggers",None),"triggers"),(getattr(a,"subscriptions",None),"subscriptions")):
            display=lab(st,"succ_triggers" if label=="triggers" else "succ_subscriptions")
            if arg:
                try:
                    data=json.loads(Path(arg).read_text(encoding='utf-8'))
                    vals=data if isinstance(data,list) else data.get("items",[]) if isinstance(data,dict) else []
                    for x in vals:
                        if isinstance(x,dict) and label=="triggers": item=x.get("id")
                        elif isinstance(x,dict): item=x.get("owner_repo") or (f"{x.get('owner')}/{x.get('repo')}#{x.get('number')}" if x.get("owner") and x.get("repo") and x.get("number") else x.get("name"))
                        else: item=x
                        if item is not None: rec["move_items"].append(f"{label[:-1]}:{item}")
                    lists.append(f"{display}: {json.dumps(data,ensure_ascii=False)}")
                except OSError: gaps.append(lab(st,"succ_list_unreadable",name=display))
                except (ValueError,TypeError): gaps.append(lab(st,"succ_list_invalid",name=display))
            else: gaps.append(lab(st,"succ_list_missing",name=display))
        rec["move_none_required"] = not getattr(a,"triggers",None) or not getattr(a,"subscriptions",None)
        lead_extra = f"\n## {lab(st,'succ_team')} ({rec['cutoff_at']})\n{lab(st,'succ_thread_list')}：{json.dumps(team,ensure_ascii=False)}\n{lab(st,'succ_open_requests')}：{json.dumps({k:v for k,v in st.get('requests',{}).items() if v.get('status') not in ('closed','reported','dropped')},ensure_ascii=False)}\n{lab(st,'succ_questions')}：{json.dumps([q for q in st.get('questions',[]) if not q.get('answered_at')],ensure_ascii=False)}\n{lab(st,'succ_promises')}：{json.dumps(st.get('promises',[]),ensure_ascii=False)}\n{lab(st,'succ_grants')}：{json.dumps(pref(st, 'standing_grants'),ensure_ascii=False)}\n{lab(st,'succ_prefs')}：{json.dumps(stored(st).get('prefs',{}),ensure_ascii=False)}\n{lab(st,'succ_reminders')}：{' ; '.join(lists) or lab(st,'succ_gap')}\n"
    changes, memory_added = _seat_change_summary(d, st, rec["seat"], rec.get("cutoff_at") or rec.get("started_at"))
    env_heading = "## " + model_lab(st, "env_heading") + "\n"
    change_rows = []
    tracked = {"language", "model", "thread_permission_mode", "permission_mode", "branch", "base"}
    for event in changes:
        at = event.get("at") or "?"
        for setting in event.get("set") or []:
            key, sep, value = str(setting).partition("=")
            if sep and key in tracked:
                change_rows.append(f"- {at} | {key} | {model_lab(st, 'change_unknown')} → {value}")
        for key in ("mode", "branch", "base"):
            value = event.get(key)
            if value is not None:
                change_rows.append(f"- {at} | {key} | {model_lab(st, 'change_unknown')} → {value}")
    if memory_added:
        change_rows.extend(f"- {line}" for line in memory_added)
    env_section = env_heading + ("\n".join(change_rows) if change_rows else "- " + model_lab(st, "change_empty")) + "\n"
    brief=f"# {hid} · {rec['seat']}\n\n{lab(st,'succ_gap')}：{', '.join(gaps) if gaps else lab(st,'succ_none')}\n\n## {lab(st,'succ_current_facts')}\n{lab(st,'succ_old_session')}：{rec.get('old_session')}；{lab(st,'t_branch')}：{branch}；{lab(st,'succ_freeze_head')}：{(rec.get('freeze') or {}).get('head','-')}\n{lab(st,'succ_unpushed')}：{len(snap['unpushed'])}；{lab(st,'succ_dirty')}：{', '.join(snap['dirty_files']) or '-'}\n{lab(st,'succ_tasks')}：{json.dumps(open_tasks,ensure_ascii=False)}\n{lab(st,'succ_requests')}：{json.dumps(related,ensure_ascii=False)}；{lab(st,'succ_leases')}：{', '.join(facts['leases']) or '-'}\n{lab(st,'succ_files_hint')}\n{env_section}{lead_extra}"
    written=[]
    rule_lines=[line for line in words if line.startswith("★ ")]
    user_lines=[line for line in words if re.match(r"^\[#\d+\] ",line)]
    rule_text="\n".join("- "+line for line in rule_lines) if rule_lines else "- No ★ user rules were recorded in words.md."
    fact_text="- "+user_lines[0] if user_lines else "- No user-authored statement was recorded for this seat term; the transcript contained no eligible human-origin message."
    unresolved_text="\n".join("- "+str(gap) for gap in gaps) if gaps else "- none"
    handoff_template="# HANDOFF\n\n## Rules / 规则\n"+rule_text+"\n\n## Only-known-after-reading fact / 只有读过才知道的一条\n"+fact_text+"\n\n## Unresolved / 悬而未决\n"+unresolved_text+"\n"
    for name,data in (("BRIEF.md",brief),("words.md","\n".join(words+peer_words)+("\n" if words or peer_words else "")),("compact.md","\n".join(compact)+("\n" if compact else "")),("facts.json",json.dumps(facts,ensure_ascii=False,indent=2)),("HANDOFF.md",handoff_template)):
        path=base/name; ix=1
        while path.exists(): path=base/f"{Path(name).stem}-{ix}{Path(name).suffix}"; ix+=1
        path.write_text(data,encoding="utf-8"); written.append(str(path))
    rawdir=base/"raw"; rawdir.mkdir(exist_ok=True); rawfile=rawdir/"old.jsonl"; ix=1
    while rawfile.exists(): rawfile=rawdir/f"old-{ix}.jsonl"; ix+=1
    rawfile.write_text("\n".join(json.dumps(_succ_scrub(row),ensure_ascii=False) for row in rows),encoding="utf-8")
    file_hashes={str(p.relative_to(base)):hashlib.sha256(p.read_bytes()).hexdigest() for p in base.rglob("*") if p.is_file() and p.name!="MANIFEST.json" and "superseded" not in p.relative_to(base).parts}
    manifest={"id":hid,"seat":rec["seat"],"old_session":rec.get("old_session"),"candidates":rec.get("candidates"),"freeze":rec.get("freeze"),"cutoff_at":rec.get("cutoff_at"),"files":file_hashes,"gaps":gaps,"user_words":users,"rules":sum(x.startswith("★") for x in words),"compactions":compact_count,"redactions":sum(len(_SUCC_SECRET_RE.findall(json.dumps(x,ensure_ascii=False))) for x in rows)}
    mf=base/"MANIFEST.json"; ix=1
    while mf.exists(): mf=base/f"MANIFEST-{ix}.json"; ix+=1
    mf.write_text(json.dumps(manifest,ensure_ascii=False,indent=2),encoding="utf-8")
    return base, gaps, written


def _succ_pack_gate(base):
    base=Path(base); missing=[]
    brief=base/"BRIEF.md"; handoff=base/"HANDOFF.md"; manifest=base/"MANIFEST.json"
    if not brief.is_file() or not re.search(r"(?im)^## .*current facts|^## .*当前事实",brief.read_text(encoding="utf-8") if brief.is_file() else ""):
        missing.append("BRIEF first facts section")
    try:
        mf=json.loads(manifest.read_text(encoding="utf-8"))
        for name,digest in mf.get("files",{}).items():
            path=base/name
            if not path.is_file() or hashlib.sha256(path.read_bytes()).hexdigest()!=digest: missing.append("MANIFEST checksum: "+name)
    except (OSError,ValueError):
        mf={}; missing.append("MANIFEST.json")
    raw=base/"raw/old.jsonl"; words=base/"words.md"
    raw_count=sum(1 for line in raw.read_text(encoding="utf-8").splitlines() if line.strip()) if raw.is_file() else 0
    gaps=mf.get("gaps",[]) if isinstance(mf,dict) else []
    if raw_count==0 and not gaps: missing.append("original words or documented gap")
    words_text=words.read_text(encoding="utf-8") if words.is_file() else ""
    if not words.is_file(): missing.append("words.md")
    elif not words_text.strip():
        if not any("No user-authored statements" in str(g) or "Transcript extraction failed" in str(g) for g in gaps):
            missing.append("words.md empty without user-words gap explanation")
    handoff_text=handoff.read_text(encoding="utf-8") if handoff.is_file() else ""
    headings=list(re.finditer(r"(?im)^#{2,4} .+$",handoff_text))
    if len(headings)<3:
        missing.append("HANDOFF three sections")
    else:
        for i,heading in enumerate(headings[:3]):
            section=handoff_text[heading.end():headings[i+1].start() if i+1<len(headings) else len(handoff_text)]
            if not section.strip() or re.search(r"(?i)\bTODO\b|待填|待定|FIXME|XXX",section):
                missing.append("HANDOFF TODO/empty section: "+heading.group(0).lstrip("# ").strip())
    if not handoff.is_file() or not re.search(r"(?im)^#{1,4} .*rules|^#{1,4} .*规则",handoff_text):
        missing.append("HANDOFF rules section")
    return missing


def cmd_succ(a):
    d = need(find_dir()); st = load(d); hs = st["handovers"]
    if a.action == "start":
        seat = a.seat
        if seat == "lead" and (st.get("write_lock") or {}).get("relead"):
            sys.exit(lab(st, "succ_relead_start"))
        if seat != "lead" and seat not in st.get("threads", {}): sys.exit(lab(st,"succ_unknown_seat"))
        if not (a.reason or "").strip(): sys.exit(lab(st,"succ_need_reason"))
        if seat == "lead" and any(x.get("seat") != "lead" and _ho_open(x) for x in hs.values()): sys.exit(lab(st,"succ_thread_handover_first"))
        if seat != "lead" and any(x.get("seat") == "lead" and _ho_open(x) for x in hs.values()): sys.exit(lab(st,"succ_lead_handover_open"))
        if any(x.get("seat") == seat and _ho_open(x) for x in hs.values()):
            sys.exit(lab(st,"succ_seat_handover_open"))
        relay_count=_succ_relay_count(st,seat); relay_limit=int(pref(st, 'relay_max_per_day'))
        if relay_count >= relay_limit and not (getattr(a,"user_said",None) or "").strip():
            sys.exit(lab(st,"relay_user_said_required"))
        n = max([int(k[2:]) for k in hs if re.fullmatch(r"HO[0-9]+", k)] or [0]) + 1; hid = f"HO{n}"
        old = _seat_session(st,seat)
        rec = {"id": hid, "seat": seat, "kind": "lead" if seat == "lead" else "thread", "reason": a.reason, "old_session": old,
               "lead_session": (st.get("lead") or {}).get("session_id"),
               "candidates": [], "successor": None, "phase": "started", "steps": {"start": now()}}
        hs[hid] = rec; save(d, st, {"ev": "succ-start", "handover": hid, **({"user_said":a.user_said.strip()} if getattr(a,"user_said",None) else {})})
